# Dashboard runtime libraries (Vega/Vega-Lite/vega-embed, Mapbox GL, Grid.js)
# are pinned by vendor/manifest.json, fetched into vendor/<lib>@<ver>/ at image
# build time with sha256 verification, and served at /vendor/... with immutable
# caching. The page shim only ever emits URLs from that manifest; when a file is
# not on disk (a dev checkout that skipped the fetch) it falls back to the
# manifest's upstream URL so nothing breaks, just less self-contained.
_VENDOR_DIR = Path(__file__).resolve().parent / "vendor"
_VENDOR_ROUTE = "/vendor"


@functools.lru_cache(maxsize=1)
def _vendor_manifest() -> dict:
    try:
        return json.loads((_VENDOR_DIR / "manifest.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 — a missing manifest only disables vendoring
        return {"libraries": {}}


def _vendor_asset(name: str, filename: str) -> dict:
    """{'url', 'version', 'vendored'} for one manifest file (served locally, else upstream)."""
    lib = (_vendor_manifest().get("libraries") or {}).get(name) or {}
    version = str(lib.get("version") or "")
    spec = (lib.get("files") or {}).get(filename) or {}
    on_disk = bool(version) and (_VENDOR_DIR / f"{name}@{version}" / filename).is_file()
    if on_disk:
        return {"url": f"{_VENDOR_ROUTE}/{name}@{version}/{filename}", "version": version, "vendored": True}
    return {"url": str(spec.get("url") or ""), "version": version, "vendored": False}


def _vendor_runtime_config() -> dict:
    """What the shim tells authors about locally served libraries."""
    libs = {}
    for name, lib in sorted((_vendor_manifest().get("libraries") or {}).items()):
        files = {fname: _vendor_asset(name, fname) for fname in sorted((lib.get("files") or {}).keys())}
        libs[name] = {"version": lib.get("version"), "files": {k: v["url"] for k, v in files.items()},
                      "vendored": all(v["vendored"] for v in files.values())}
    return {"route": _VENDOR_ROUTE, "libraries": libs}


