# Schema scoping — the warehouse and rvbbit's own internals share one database, so we
# expose the data schemas and hide the engine's catalog. _DENY is always hidden;
# WAREHOUSE_SCHEMAS (optional CSV allowlist) further restricts to just those.
# The appliance's own schemas, never shown as company data. Mirrors
# rvbbit.is_system_schema() (migration 0496); cubes stays visible on purpose.
_DENY_SCHEMAS = {"information_schema", "rvbbit", "rvbbit_meta", "hindsight", "seeds", "parity",
                 "meaning_labels", "datarabbit", "dagster_operational", "fivetran_metadata", "n8n",
                 "cron", "pgsodium", "vault"}
_DENY_SCHEMA_PREFIXES = ("pg_", "_dlt_", "clover_")
_ALLOW_SCHEMAS = {s.strip() for s in os.environ.get("WAREHOUSE_SCHEMAS", "").split(",") if s.strip()}

# common PG type OIDs -> friendly names (best-effort, Phase-0)
_TYPE = {16: "bool", 20: "int8", 21: "int2", 23: "int4", 25: "text", 700: "float4",
         701: "float8", 1043: "varchar", 1082: "date", 1114: "timestamp",
         1184: "timestamptz", 1700: "numeric", 114: "json", 3802: "jsonb"}


def _uncounted_dsn(dsn: str) -> str:
    """The DSN with rvbbit.count_reads=off: pg_rvbbit counts client SELECTs as
    reads to decide what to accelerate, and background sweeps are not demand.
    A startup option, so it survives rollback, RESET ALL and SET ROLE."""
    params = psycopg.conninfo.conninfo_to_dict(dsn)
    options = params.get("options") or ""
    if "rvbbit.count_reads" not in options:
        params["options"] = f"{options} -c rvbbit.count_reads=off".strip()
    return psycopg.conninfo.make_conninfo(**params)


def _conn(read_only: bool = False, role: str | None = None, count_reads: bool = True):
    c = psycopg.connect(DSN if count_reads else _uncounted_dsn(DSN), row_factory=dict_row,
                        autocommit=not read_only)
    if read_only:
        # Set the transaction characteristic before SET ROLE, request tracking,
        # or any other statement starts the transaction.  Setting
        # default_transaction_read_only after a SELECT only affects the *next*
        # transaction and silently leaves this one writable.
        c.read_only = True
    if role:
        # Burrow mode (docs/BURROW_PLAN.md): execute as the caller's PG role —
        # their GRANTs/RLS govern the query. Connection is per-call, so plain
        # SET ROLE is safe (no pool to leak into).
        c.execute('SET ROLE "%s"' % role.replace('"', '""'))
    _set_request_tracking_user(c)
    if read_only:
        # belt: txn read-only blocks any write/DDL even for a superuser DSN.
        # suspenders (prod): the mapped role simply lacks write grants.
        c.execute(f"SET statement_timeout = {STMT_TIMEOUT_MS}")
    return c


_BURROW_ROLE_RE = re.compile(r"^[A-Za-z0-9_][A-Za-z0-9_$@.\-]{0,62}$")
# Session-cookie surfaces (the app data bridge) carry identity out-of-band of
# the OAuth token context — they park the subject here around tool calls so
# an extra role arg never leaks into the MCP tool schemas.
import contextvars
_SESSION_SUB = contextvars.ContextVar("rvbbit_session_sub", default=None)
# A native messaging adapter can call Warehouse through one long-lived shared
# MCP connection even though each turn belongs to a different human.  Hermes
# forwards that already-verified turn identity in request metadata.  Keep it in
# a task-local override so it can improve attribution without ever changing the
# access token, PG role, or authorization decision for the call.
_FORWARDED_CALLER = contextvars.ContextVar("rvbbit_forwarded_caller", default=None)


def _request_tracking_user():
    """Best-effort caller label for provider cost reporting, never auth."""
    try:
        caller_fn = globals().get("_caller")
        caller = caller_fn()[0] if callable(caller_fn) else None
    except Exception:  # noqa: BLE001 — attribution must not gate a request
        caller = None
    value = str(caller or "").strip()
    if not value or len(value) > 254 or any(ord(char) < 32 or ord(char) == 127 for char in value):
        return None
    return value


def _set_request_tracking_user(conn):
    """Park telemetry identity in the SQL session for pg_rvbbit provider calls."""
    user = _request_tracking_user()
    if user:
        # A custom GUC is intentionally used as an application telemetry seam.
        # pg_rvbbit captures it before dispatching work to worker threads. It is
        # never consulted by database or application authorization code.
        conn.execute("SELECT set_config('rvbbit.request_user', %s, false)", (user,))


@dataclass(frozen=True)
class ApplicationAuthorizationContext:
    """One request's application-layer actor/subject decision.

    ``actor`` is the principal whose credential reached Warehouse. ``subject``
    is the human Warehouse may authorize the application request as. They are
    deliberately different for a trusted Hermes delegation, and ``subject`` is
    deliberately empty for legacy shared-key forwarding. ``attributed_subject``
    retains that older display/ownership behavior without accidentally turning
    it into an access grant.

    This does not SET ROLE or alter database privileges. Team/artifact policy can
    consume ``subject`` later while Postgres authorization remains independent.
    """

    actor: str | None
    subject: str | None
    attributed_subject: str | None
    client_id: str | None
    mode: str
    assurance: str
    delegated: bool = False
    platform: str | None = None
    session_ref: str | None = None
    run_ref: str | None = None

    def audit_payload(self) -> dict:
        payload = {
            "actor": self.actor,
            "subject": self.subject,
            "attributed_subject": self.attributed_subject,
            "client_id": self.client_id,
            "mode": self.mode,
            "assurance": self.assurance,
            "delegated": self.delegated,
            "platform": self.platform,
            "session_ref": self.session_ref,
            "run_ref": self.run_ref,
        }
        return {key: value for key, value in payload.items() if value is not None}


# Populated for the full lifetime of a logged MCP invocation. This gives every
# tool the same decision and prevents nested helpers from re-resolving a mutable
# request envelope or leaking one request's subject into the next task.
_AUTHORIZATION_CONTEXT = contextvars.ContextVar(
    "rvbbit_application_authorization", default=None
)
_HERMES_SERVICE_CLIENT_ID = "hermes-service"
_HERMES_TRANSPORT_CLIENT_IDS = frozenset({"static-key", _HERMES_SERVICE_CLIENT_ID})


def _is_hermes_transport(client_id):
    """Both credentials may carry provenance; only the dedicated one is trusted."""
    return client_id in _HERMES_TRANSPORT_CLIENT_IDS


def _is_trusted_hermes_transport(client_id):
    return client_id == _HERMES_SERVICE_CLIENT_ID


def _session_pg_role(sub=None):
    """In pg auth mode (Burrow) the authenticated subject IS a Postgres role —
    return it for SET ROLE execution; None means service identity (shared/
    stdio modes, or a malformed subject)."""
    try:
        import auth
        if getattr(auth, "AUTH_MODE", "shared") != "pg":
            return None
    except Exception:  # noqa: BLE001 — auth module absent in some harnesses
        return None
    s = sub if sub is not None else (_SESSION_SUB.get() or _caller()[0])
    return s if s and _BURROW_ROLE_RE.fullmatch(str(s)) else None


def _bg_conn(read_only: bool = False, role: str | None = None):
    """_conn for background workers: their reads are not acceleration demand."""
    return _conn(read_only=read_only, role=role, count_reads=False)


def _ro():
    """An autocommit, read-only connection for grounding lookups (samples/stats/
    freshness) — autocommit so one failed probe can't poison the rest of the loop.
    Discovery samples are not reads anyone asked for, so they are not counted."""
    c = psycopg.connect(_uncounted_dsn(DSN), row_factory=dict_row, autocommit=True)
    _set_request_tracking_user(c)
    c.execute("SET default_transaction_read_only = on")
    c.execute(f"SET statement_timeout = {STMT_TIMEOUT_MS}")
    return c


def _normalize_as_of(as_of):
    """Return one safe, UTC timestamp for the statement directive.

    The value ultimately appears in a leading SQL comment, so accepting arbitrary
    text here would let a newline escape the directive.  Keep the public contract
    deliberately narrow: ISO-8601 timestamps (a date alone means midnight UTC).
    """
    if as_of is None:
        return None
    if isinstance(as_of, datetime):
        parsed = as_of
    else:
        raw = str(as_of).strip()
        if not raw:
            return None
        if len(raw) > 80 or "\n" in raw or "\r" in raw or "\x00" in raw:
            raise ValueError("as_of must be one ISO-8601 timestamp")
        candidate = raw[:-1] + "+00:00" if raw.lower().endswith("z") else raw
        try:
            parsed = datetime.fromisoformat(candidate)
        except ValueError as exc:
            raise ValueError("as_of must be one ISO-8601 timestamp") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _with_as_of(sql: str, as_of):
    """Time-travel: the engine reads a leading `-- rvbbit: as_of <ts>` directive."""
    normalized = _normalize_as_of(as_of)
    return f"-- rvbbit: as_of {normalized}\n{sql}" if normalized else sql


def _split(table: str):
    parts = table.split(".", 1)
    return ("public", parts[0]) if len(parts) == 1 else (parts[0], parts[1])


def _schema_allowed(schema: str) -> bool:
    """Hide the appliance's own schemas; honor the optional allowlist."""
    if schema in _DENY_SCHEMAS or schema.startswith(_DENY_SCHEMA_PREFIXES):
        return False
    return schema in {"calliope", "calliope_apps"} or (not _ALLOW_SCHEMAS) or (schema in _ALLOW_SCHEMAS)


def _samples(cur, schema: str, rel: str, n: int = 5):
    try:
        cur.execute(pgsql.SQL("SELECT * FROM {}.{} LIMIT %s").format(
            pgsql.Identifier(schema), pgsql.Identifier(rel)), (n,))
        return cur.fetchall()
    except Exception as e:  # noqa: BLE001
        return {"error": str(e)}


def _fmt_ndv(nd):
    """pg_stats n_distinct → friendly: positive=absolute count, negative=distinct/row ratio."""
    if nd is None or nd == 0:
        return None
    if nd > 0:
        return int(nd)
    if nd == -1:
        return "unique"
    return f"~{round(-nd * 100)}% distinct"


def _col_stats(cur, schema: str, rel: str, max_cols: int = 16, top_vals: int = 6):
    """Cheap per-column profile from the planner's ANALYZE stats (pg_stats): distinct
    count, null %, most-common values — what keeps Claude from inventing columns."""
    try:
        rows = cur.execute(
            "SELECT attname, n_distinct, round((null_frac*100)::numeric, 1) AS null_pct, "
            "(most_common_vals::text::text[])[1:%s] AS top_vals "
            "FROM pg_stats WHERE schemaname=%s AND tablename=%s ORDER BY attname LIMIT %s",
            (int(top_vals), schema, rel, max_cols),
        ).fetchall()
    except Exception:  # noqa: BLE001
        return None
    out = {}
    for r in rows:
        col = {}
        ndv = _fmt_ndv(r["n_distinct"])
        if ndv is not None:
            col["ndv"] = ndv
        if r["null_pct"] is not None and float(r["null_pct"]) > 0:
            col["null_pct"] = float(r["null_pct"])
        if r["top_vals"]:
            col["top"] = r["top_vals"]
        if col:
            out[r["attname"]] = col
    return out or None


def _freshness(cur, schema: str, rel: str):
    """rvbbit's superpower, surfaced in the grounding: rows, last sync, staleness/drift."""
    try:
        r = cur.execute(
            "SELECT parquet_rows, row_groups, parquet_bytes, last_refresh_at, "
            "round(seconds_since_refresh) AS secs, drift_rows, shadow_heap_dirty "
            "FROM rvbbit.accel_freshness WHERE table_oid = to_regclass(%s)::oid LIMIT 1",
            (f"{schema}.{rel}",),
        ).fetchone()
    except Exception:  # noqa: BLE001
        return None
    if not r:
        return None
    drift = int(r["drift_rows"] or 0)
    return {
        "rows": r["parquet_rows"],
        "row_groups": r["row_groups"],
        "bytes": r["parquet_bytes"],
        "last_synced": r["last_refresh_at"],
        "seconds_since_refresh": float(r["secs"]) if r["secs"] is not None else None,
        "drift_rows": drift,
        "stale": bool(r["shadow_heap_dirty"]) or drift > 0,
    }


# ── tools ───────────────────────────────────────────────────────────────────

def _capability_search_match(row, index=(), *, include_schema=True) -> dict:
    import capability_discovery
    match = {
        "kind": row["kind"],
        "name": row["name"],
        "score": round(float(row["score"] or 0), 3),
        "doc": capability_discovery.clean_doc(row["doc"]),
    }
    for key in ('suggested_arguments', 'match_reason', 'sql_availability'):
        if key in row:
            match[key] = row[key]
    if match['kind'] == 'cap_business_logic':
        match.update(row.get('contract') or {})
    elif match['kind'] == 'cap_mcp_tool':
        capability_discovery.tool_contract(match, index, include_schema=include_schema)
    elif match["kind"] == "cap_operator":
        # Operator names are catalog identities, while their callable SQL
        # surface lives in the rvbbit schema. Return both explicitly and make
        # the displayed signature executable as shown; an unqualified name
        # depends on search_path and fails in the hosted warehouse.
        sql_name = str(match["name"])
        if "." not in sql_name:
            sql_name = f"rvbbit.{sql_name}"
        match["sql_name"] = sql_name
        signature = f"signature: {match['name']}("
        qualified_signature = f"signature: {sql_name}("
        if isinstance(match["doc"], str) and signature in match["doc"]:
            match["doc"] = match["doc"].replace(
                signature, qualified_signature, 1
            )
    elif match["kind"] == "cap_skill":
        match["load_with"] = {
            "tool": "skill_view",
            "name": str(match["name"]),
        }
    elif match["kind"] == "cap_playbook":
        # Retired Desktop Lab Procedures read like any other method now.
        match["doc"] = re.sub(
            r"\n?(signature: run_calliope_procedure\([^\n]*\)|An approved executable Procedure\. Call run_calliope_procedure[^\n]*)",
            "", str(match.get("doc") or ""))
        match["load_with"] = {
            "tool": "read_calliope_playbook",
            "playbook_ref": str(match["name"]),
        }
    return match


def _refresh_runtime_pack_matches(conn, rows):
    names = [row["name"] for row in rows if row.get("kind") == "cap_pack"]
    if not names:
        return rows
    import calliope
    facts = calliope._capability_runtime_facts(conn, names)
    result = []
    for raw in rows:
        row = dict(raw)
        fact = facts.get(row.get("name")) if row.get("kind") == "cap_pack" else None
        if fact:
            state = "installed" if fact["installed"] else "available"
            doc = re.sub(r"status: (?:available|installed)", "status: " + state, str(row.get("doc") or ""))
            doc = doc.replace(" NOT currently installed — suggest installation to the user; never install autonomously.", "")
            doc += (f"\nCurrent runtime registration: {state}; runtime: {fact['runtime_name']}; "
                    f"registry status: {fact['runtime_status'] or 'unregistered'}. "
                    "Installation, live health and configured jobs are separate facts.")
            if fact["runtime_name"] == "dlt_mirror":
                doc += " Use mirror_status(session_id) for live DLT health, connections and jobs; add job_name or run_id for details."
            row["doc"] = doc
        result.append(row)
    return result


def _capability_tool_summaries(index) -> list[dict]:
    """[{name, summary}] for the capability index: a tool's first paragraph, one line."""
    out = []
    for t in index or []:
        name = str((t or {}).get("name") or "").strip()
        if not name:
            continue
        text = str((t or {}).get("description") or "").strip()
        first = text.split("\n\n", 1)[0] if text else ""
        summary = " ".join(first.split())[:1200].rstrip()
        # The crawler appends the MCP invocation contract after this summary.
        if summary and summary[-1] not in ".!?":
            summary += "."
        out.append({"name": name, "summary": summary})
    return out


def _sync_capability_mcp_tools(index) -> dict | None:
    """Upsert the live tool list into rvbbit.capability_mcp_tools and re-crawl the
    capability index when anything changed. None when the function is not installed."""
    tools = _capability_tool_summaries(index)
    if len(tools) < 20:
        return None
    with _conn() as c:
        probe = c.execute("SELECT to_regprocedure('rvbbit.capability_mcp_tools_sync(jsonb)') IS NOT NULL AS ok").fetchone()
        if not probe or not probe.get("ok"):
            return None
        row = c.execute("SELECT rvbbit.capability_mcp_tools_sync(%s::jsonb) AS r", (json.dumps(tools),)).fetchone()
        result = _meaning_json((row or {}).get("r")) or {}
        if result.get("changed"):
            try:
                c.execute("SELECT rvbbit.capability_crawl(false)")
                result["crawled"] = True
            except Exception as e:  # noqa: BLE001 — staleness will rebuild it on the next search
                result["crawled"] = False
                result["crawl_error"] = str(e)[:200]
        # The crawl only upserts, and capability_crawl(false) writes docs without vectors:
        # forget what is gone, then embed what is bare (migration 0456). Off the boot path,
        # so an embedder that is slow costs nothing here but time in this thread.
        for fn, key in (("rvbbit.capability_prune_stale()", "pruned"), ("rvbbit.capability_embed_missing(1000)", "embedded")):
            try:
                probe = c.execute(f"SELECT to_regprocedure('{fn.split('(')[0]}({'int' if 'embed' in fn else ''})') IS NOT NULL AS ok").fetchone()
                if probe and probe.get("ok"):
                    r = c.execute(f"SELECT {fn} AS r").fetchone()
                    result[key] = _meaning_json((r or {}).get("r")) or {}
            except Exception as e:  # noqa: BLE001
                result[key] = {"error": str(e)[:200]}
    import logging as _logging
    _logging.getLogger(__name__).info("capability tool sync: %s", result)
    return result


def _capability_query_looks_like_object(query) -> bool:
    """One identifier-shaped token (`aa_ads`, `leads`, `sales.orders`): the pilot sent
    such queries to capability_search 50+ times in a fortnight. They name data, not
    abilities, and find is the door for data."""
    import re as _re
    q = str(query or "").strip()
    return 0 < len(q) <= 64 and bool(_re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)?", q))


def _capability_data_hits(query: str, limit: int = 5) -> dict | None:
    """find's top hits for an object-shaped capability query, compact, with the reason."""
    try:
        res = tool_find(query, limit=limit, rerank=False)
    except Exception:  # noqa: BLE001 — discovery must not fail because find did
        return None
    hits = []
    for h in (res or {}).get("matches") or []:
        if not isinstance(h, dict) or not h.get("object"):
            continue
        meaning = h.get("meaning") if isinstance(h.get("meaning"), dict) else {}
        hits.append({k: v for k, v in {"object": h.get("object"), "kind": h.get("kind"), "score": h.get("score"),
                                       "what": meaning.get("what")}.items() if v is not None})
    if not hits:
        return None
    return {"hits": hits[:limit],
            "note": f"'{query}' looks like a data object, not an ability; find answered it here. "
                    "Use find for tables, columns, metrics and business terms; capability_search is for what the warehouse can do."}


def tool_capability_search(
    query: str, limit: int = 8, kinds=None, _caller_override=None, _tool_index=None
) -> dict:
    """Search WHAT THIS WAREHOUSE CAN DO — the same just-in-time discovery the
    built-in assistant uses: semantic SQL operators (means()/about()/extract/
    classify/forecast/...), installed MCP servers and their tools, installable
    capability packs, SQL syntax patterns, models and providers. Ask in plain
    language ("extract entities from text", "search the web", "forecast this
    series") and get callable names + signatures back — operators are directly
    usable inside run_sql and approved Playbooks can be loaded as reusable
    methods. Hermes procedural skills are compact cap_skill stubs; load the
    exact body with skill_view only after one is relevant. Complements
    search_data (which finds DATA: tables, metrics, cubes); this finds
    ABILITIES. kinds filter (optional): cap_playbook | cap_skill | cap_operator
    | cap_business_logic | cap_mcp_tool | cap_pack | cap_syntax | model | provider. A query that is one
    identifier-shaped token (a table, a term) is answered by find as well, under
    `data` — ask find directly for data."""
    import capability_discovery
    index = _tool_index or []
    limit = max(1, min(int(limit or 8), 25))
    ks = None
    if kinds:
        ks = [str(k).strip() for k in (kinds if isinstance(kinds, list) else str(kinds).split(",")) if str(k).strip()]
        ks = ks or None
    candidates = (capability_discovery.local_candidates(index, query)
                  if index and (not ks or 'cap_mcp_tool' in ks) else [])
    if candidates:
        visible = _capability_visible_names('cap_mcp_tool', [r['name'] for r in candidates],
                                            caller_override=_caller_override)
        candidates = [r for r in candidates if r['name'] in visible]
        exact = [r for r in candidates if r['match_reason'] == 'exact_name']
        if exact:
            matches = [_capability_search_match(exact[0], index)]
            return {'discovery_version': 1, 'query': query, 'matches': matches,
                    'groups': capability_discovery.grouped_indices(matches),
                    'hint': capability_discovery.HINT, 'lookup': 'exact_registry_name'}
    only_skills = bool(ks) and set(ks) == {"cap_skill"}
    skills_possible = not ks or "cap_skill" in ks
    # Skills share the Library, but must not become a second crowding vector.
    # Over-fetch mixed searches and retain at most two skill procedures; an
    # explicit cap_skill search remains unrestricted.
    fetch_limit = (
        min(100, max(32, limit * 4))
        if skills_possible and not only_skills
        else limit
    )
    rebuilt = False
    skill_projection = None
    with _conn() as c:
        # Hermes and Warehouse share the durable /opt/data volume. Reconcile
        # only compact frontmatter stubs into the capability graph when its
        # manifest changes; SKILL.md bodies never enter the prompt or Brain.
        try:
            skill_projection = hermes_skills.sync_skill_capabilities(c)
        except psycopg.errors.UndefinedFunction:
            pass  # rolling upgrade: the server image can lead migration 0314
        except Exception:  # noqa: BLE001
            pass  # discovery must still work during volume/embedder trouble
        # Self-heal FIRST: the capabilities graph only updates when
        # capability_crawl() runs (e.g. after installing an MCP server), and
        # a stale-but-populated index returns confident results that simply
        # omit new tools — invisible to a zero-match check. The staleness
        # probe is one cheap query and a full re-crawl measures ~2s, so when
        # stale we just rebuild before searching.
        try:
            probe = c.execute(
                "SELECT to_regprocedure('rvbbit.capability_search_stale()') IS NOT NULL AS ok"
            ).fetchone()
            if probe and probe["ok"] and bool(
                c.execute("SELECT rvbbit.capability_search_stale() AS s").fetchone()["s"]
            ):
                c.execute("SELECT rvbbit.capability_crawl()")
                try:
                    if (c.execute("SELECT to_regprocedure('rvbbit.capability_prune_stale()') IS NOT NULL AS ok").fetchone() or {}).get("ok"):
                        c.execute("SELECT rvbbit.capability_prune_stale()")
                except Exception:  # noqa: BLE001 — a rebuild that could not forget is still a rebuild
                    pass
                rebuilt = True
        except Exception:  # noqa: BLE001
            pass  # search whatever index exists; never fail discovery on upkeep
        # Approved Playbooks are projected independently of the installation
        # catalog crawler.  Revisions leave the former approved version live
        # until approval moves the pointer, and this cheap probe repairs any
        # interrupted approval/archive projection before discovery.
        try:
            probe = c.execute(
                "SELECT to_regprocedure('rvbbit.capability_playbook_search_stale()') IS NOT NULL AS ok"
            ).fetchone()
            if probe and probe["ok"] and bool(
                c.execute(
                    "SELECT rvbbit.capability_playbook_search_stale() AS s"
                ).fetchone()["s"]
            ):
                c.execute("SELECT rvbbit.sync_calliope_playbook_capabilities()")
                rebuilt = True
        except Exception:  # noqa: BLE001
            pass
        # The human subject comes from Warehouse's frozen request context, not
        # from the public tool schema. Scheduled Assignment/Workflow calls may
        # recover it only from their Warehouse-owned job ledger.
        subject = _capability_discovery_subject(
            c, caller_override=_caller_override
        )
        try:
            rows = c.execute(
                "SELECT kind,name,score,doc FROM "
                "rvbbit.capability_search_for(%s,%s,%s,%s)",
                (subject, query, fetch_limit, ks),
            ).fetchall()
        except psycopg.errors.UndefinedFunction:
            # A Warehouse image can briefly lead its pg_rvbbit image during a
            # rolling upgrade. The old database cannot contain access policies,
            # so its historical unscoped search is the compatible fallback.
            rows = c.execute(
                "SELECT kind,name,score,doc FROM "
                "rvbbit.capability_search(%s,%s,%s)",
                (query, fetch_limit, ks),
            ).fetchall()
        rows = _refresh_runtime_pack_matches(c, rows)
        import system_checks
        rows = system_checks.discovery(c, rows)
        # The graph supplies ranking; the authoritative registry supplies the
        # active revision and callable contract. Recheck access/publication so
        # a stale index cannot advertise a withdrawn rule.
        import business_logic_runtime
        enriched = []
        for row in rows:
            if row['kind'] == business_logic_runtime.KIND:
                revisions = business_logic_runtime.published(c, subject, row['name'])
                active = next((r for r in revisions if r['version'] == r['published_version']), None)
                if active is None:
                    continue
                row = {**row, 'contract': business_logic_runtime.capability(active)}
            enriched.append(row)
        rows = enriched
    rows = candidates + rows
    selected_rows = capability_discovery.select_rows(rows, query, limit, ks)
    matches, schema_count = [], 0
    for row in selected_rows:
        match = _capability_search_match(row, index, include_schema=schema_count < 3)
        schema_count += int('parameters' in match)
        matches.append(match)
    out = {
        "discovery_version": 1,
        "query": query,
        "matches": matches,
        "groups": capability_discovery.grouped_indices(matches),
        "hint": capability_discovery.HINT,
    }
    if skill_projection and skill_projection.get("changed"):
        out["skill_index_reconciled"] = {
            "skills": skill_projection.get("skills", 0),
            "removed": skill_projection.get("removed", 0),
        }
    if rebuilt:
        out["index_rebuilt"] = "capability index was stale — rebuilt automatically before this search"
    if _capability_query_looks_like_object(query):
        data = _capability_data_hits(query)
        if data:
            out["data"] = data
    return out


# Business Context search scores are rank-normalized (the best hit of ANY query
# is 1.0), and the dense ranker's floor is permissive on purpose. Blending that
# into search_data by a fixed tier order meant six "1.0" business metrics
# outranked public.traffic_violations for "traffic stops police citations".
# Below this absolute cosine (measured on the hosted appliance: related business
# nodes 0.33-0.42, unrelated 0.15-0.26) a business hit only earns the top tier
# when the lexical ranker matched the query too; otherwise it sorts after tables.
_BUSINESS_CONTEXT_MATCH_FLOOR = float(os.environ.get("CALLIOPE_BUSINESS_CONTEXT_MATCH_FLOOR", "0.30"))
_BUSINESS_CONTEXT_KINDS = {"business_value_system", "business_metric", "business_object"}


def _business_context_relevance(c, query: str) -> dict | None:
    """Absolute relevance per Business Context node: best dense cosine + lexical hit.

    Reuses the content-addressed embedding cache (data_search embedded the same
    query moments earlier), so this is one cheap KNN over a small graph. Returns
    None when the appliance cannot answer, and callers keep the legacy ordering.
    """
    try:
        rows = c.execute(
            "WITH q AS (SELECT rvbbit.embed("
            "  COALESCE(current_setting('rvbbit.search_query_prefix', true), '') || %s, '', 'query') AS v) "
            "SELECT k.node_id, k.score::float8 AS cosine, false AS lexical "
            "  FROM q, rvbbit.dense_knn_tiered(q.v, 'business_context', NULL, 200, 0.0) k "
            "UNION ALL "
            "SELECT l.node_id, NULL::float8, true "
            "  FROM rvbbit.catalog_lexical_knn(%s, 'business_context', NULL, 200) l",
            (query, query),
        ).fetchall()
    except Exception:  # noqa: BLE001 - mixed-version appliance / no embedder
        return None
    out: dict = {}
    for r in rows:
        entry = out.setdefault(int(r["node_id"]), {"cosine": None, "lexical": False})
        if r["cosine"] is not None:
            entry["cosine"] = max(entry["cosine"] or 0.0, float(r["cosine"]))
        if r["lexical"]:
            entry["lexical"] = True
    return out


def _business_context_match(relevance: dict | None, node_id) -> dict:
    """Classify one business hit: {'cosine','lexical','strong'} (strong=None when unknown)."""
    if relevance is None:
        return {"cosine": None, "lexical": None, "strong": None}
    entry = relevance.get(int(node_id)) if node_id is not None else None
    cosine = entry["cosine"] if entry else None
    lexical = bool(entry and entry["lexical"])
    strong = lexical or (cosine is not None and cosine >= _BUSINESS_CONTEXT_MATCH_FLOOR)
    return {"cosine": None if cosine is None else round(cosine, 3), "lexical": lexical, "strong": strong}


def tool_search_data(query: str, limit: int = 8, schema=None) -> dict:
    """Semantic search over the catalog KG/data-KG.

    Catalog metrics, cubes, tables, and columns retain usage-weighted discovery.
    Table hits include live samples, stats, and freshness; internal schemas stay
    hidden. Business Context retrieval is separate while that system is rebuilt.
    """
    limit = max(1, min(int(limit), 25))
    with _conn() as c:
        # usage-weighted: objects employees actually query climb (boosted_score folds in
        # mcp_popular_objects). Falls back to pure relevance when nothing is logged yet.
        hits = c.execute(
            "SELECT node_id, kind, schema_name, rel_name, col_name, score, boosted_score, doc, usage_touches "
            "FROM rvbbit.search_data_weighted(%s, %s, %s, %s, 0.5)",
            (query, min(limit * 4, 100), None, GRAPH),   # over-fetch; internals get filtered out
        ).fetchall()
    # Keep ordinary data discovery independent of the Business Context rebuild,
    # including its refresh/embedding work and evolving schema-less node kinds.
    matches = _blend_search_hits(hits, None, limit=limit, schema=schema)
    # A table outranks its own parts here too (Callie: "video games catalog" led with a
    # 500-row label view and the master was a later column). A table the index left out
    # of the top hits is conjured at the first part's position and grounded like any other.
    matches = _find_fold_under_tables(matches, _find_label_bases([m.get("object") or "" for m in matches]))[:limit]
    for m in matches:
        if m.get("folded") and "samples" not in m:
            _search_data_ground(m)
    return {"matches": matches,
            "note": None if matches else "no strong matches; try broader terms"}


def _shorten_url(url: str) -> str:
    """A URL as a shape, not a link: scheme, host, and the file at the end."""
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(url)
    except ValueError:
        return url[:60]
    tail = (parts.path.rsplit("/", 1)[-1] or "")[:28]
    if parts.path.count("/") > 1:
        return f"{parts.scheme}://{parts.netloc}/…/{tail}"
    return f"{parts.scheme}://{parts.netloc}/{tail}".rstrip("/")


def _looks_like_url(value) -> bool:
    import re as _re
    return isinstance(value, str) and bool(_re.fullmatch(r"https?://[^\s\"'<>]+", value.strip()))


def _clip_text(value: str, str_limit: int) -> str:
    import re as _re
    url_re = _re.compile(r"https?://[^\s\"'<>\]\)]+")
    if url_re.fullmatch(value.strip()):
        return _shorten_url(value.strip())
    value = url_re.sub(lambda m: _shorten_url(m.group(0)), value)
    if len(value) <= str_limit:
        return value
    head = value[:str_limit]
    sentence = head.rfind(". ")
    if sentence >= 10:                                   # a whole sentence, however early, beats a fragment
        return head[: sentence + 1] + " …"
    word = head.rfind(" ")
    return (head[:word] if word >= str_limit // 3 else head).rstrip() + " …"


def _clip_payload(value, *, str_limit: int = 160, depth: int = 0):
    """Grounding for a SEARCH hit is a taste of the table, not the row. Callie, on
    the catalog tables: a title, a store, a price that is often null, a rating count
    of 1 beside one of 223 and a features list that is marketing copy teach the
    columns; the same pricing paragraph three times, ten image objects and a video
    URL are the dump. So: text ends at a sentence or a word with an ellipsis; a URL
    becomes host/…/file; a list of scalars shows three and a count; a list of
    objects or links shows ONE and a count; an object nested in a row shows its
    keys; a modest flat object (≤8 keys, every value short: a cube dimension, a {v, n} pair) keeps its values."""
    if isinstance(value, str):
        return _clip_text(value, str_limit)
    if isinstance(value, dict):
        items = list(value.items())
        # modest and flat keeps its values (a cube's dimension object, a {v, n} pair).
        # Modest is about the VALUES, not the key count: Callie on the sales-order cube —
        # a five-key dimension object collapsing to keys was "too aggressive"; then on
        # the catalog — a seven-key details object with a strikethrough-pricing
        # sentence in it "let that boilerplate back in". Short values stay; a
        # paragraph in any value makes the object a shape.
        # "short" is judged on the value as it would be shown: a raw image URL is long, but
        # as a shape (host/…/file) it is one short line, and one image present is the taste
        def short(v) -> bool:
            if not isinstance(v, str):
                return True
            shown = _clip_text(v, str_limit)
            return len(shown) <= 48 or "/…/" in shown or _looks_like_url(v)     # a link is a shape already, whatever its length
        flat = len(items) <= 8 and all(not isinstance(v, (dict, list)) and short(v) for _, v in items)
        if depth >= 2 and not flat:
            keys = [str(k) for k, _ in items[:8]]
            return {"keys": keys + ([f"… +{len(items) - 8} more"] if len(items) > 8 else []), "n_keys": len(items)}
        # a row (or a stats map) keeps EVERY key: the taste of each column is the point,
        # and a wide table lost its 25th column onward before this was said out loud
        return {str(k): _clip_payload(v, str_limit=str_limit, depth=depth + 1) for k, v in items}
    if isinstance(value, (list, tuple)):
        members = list(value)
        if not members:
            return []
        import re as _re
        linkish = all(isinstance(m, dict) or (isinstance(m, str) and _re.search(r"https?://", m)) for m in members)
        keep = 1 if linkish else 3
        out = [_clip_payload(m, str_limit=str_limit, depth=depth + 1) for m in members[:keep]]
        if len(members) > keep:
            out.append(f"… +{len(members) - keep} more")
        return out
    return value


def _clip_sample_rows(rows):
    """Three clipped rows, and a value a later row repeats verbatim says so instead."""
    if not isinstance(rows, list):
        return _clip_payload(rows)
    clipped = [_clip_payload(r, depth=1) if isinstance(r, dict) else _clip_payload(r) for r in rows]
    seen: dict = {}
    for i, row in enumerate(clipped):
        if not isinstance(row, dict):
            continue
        for k, v in list(row.items()):
            if isinstance(v, (str, list, dict)) and len(json.dumps(v, default=str)) > 40:
                key = (k, json.dumps(v, sort_keys=True, default=str))
                if key in seen:
                    row[k] = f"= row {seen[key] + 1}"
                else:
                    seen[key] = i
    return clipped


def _search_data_ground(m: dict) -> None:
    """Samples, column stats and freshness for a table hit the fold conjured."""
    parts = str(m.get("object") or "").split(".")
    if len(parts) != 2:
        return
    schema, rel = parts
    try:
        # the same read-only cursor the blend grounds with (the helpers take a cursor)
        with _ro() as rc, rc.cursor() as cur:
            m["samples"] = _clip_sample_rows(_samples(cur, schema, rel, 3))
            st = _col_stats(cur, schema, rel, max_cols=12, top_vals=4)
            if st:
                m["column_stats"] = _clip_payload(st)
            fr = _freshness(cur, schema, rel)
            if fr:
                m["freshness"] = fr
    except Exception:  # noqa: BLE001 — the hit stands without grounding
        pass


_FIND_KINDS = ("db_table", "db_column", "cube")


def _find_label_bases(objects) -> dict[str, dict]:
    """meaning_labels.<view> → {base, keys, sample_n}: the enrichment each label view
    was made from (migration 0449), so find can fold the view under its table."""
    views = sorted({o.split(".", 1)[1].split(".")[0] for o in objects or [] if str(o).startswith("meaning_labels.")})
    if not views:
        return {}
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regclass('rvbbit.meaning_enrichments') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return {}
            rows = c.execute(
                "SELECT view_name, relation, key_columns, sample_n FROM rvbbit.meaning_enrichments "
                " WHERE view_name = ANY(%s) OR 'meaning_labels.' || view_name = ANY(%s)",
                ([f"meaning_labels.{v}" for v in views], [f"meaning_labels.{v}" for v in views]),
            ).fetchall()
    except Exception:  # noqa: BLE001 — without the map the hits simply stay where the index put them
        return {}
    out = {}
    for r in rows:
        name = str(r.get("view_name") or "")
        key = name if name.startswith("meaning_labels.") else f"meaning_labels.{name}"
        out[key] = {"base": str(r.get("relation") or ""), "keys": list(r.get("key_columns") or []), "sample_n": r.get("sample_n")}
    return out


def _find_fold_under_tables(matches: list, label_bases: dict) -> list:
    """A table outranks its own parts. On the test box "video games catalog" led with
    five columns of store.meta_video_games and a 500-row label view keyed by title,
    and the master table was not in the top six. Column hits and enrichment label
    views that matched by meaning are folded under their base table: the table
    takes the first such position, carrying `via`; the table's own columns follow it,
    while a label view and its columns leave the list once recorded under `via` (with
    their key and sample size) — a 500-row sample keyed by title must not stand beside
    the table it describes. A hit that matched a literal value is left alone — the
    column that holds "Coast Dental" IS the answer, not its table."""
    def base_of(m: dict):
        obj = str(m.get("object") or "")
        if m.get("kind") == "db_column":
            parts = obj.split(".")
            if len(parts) < 3:
                return None
            parent = ".".join(parts[:2])
            info = label_bases.get(parent)          # a column of a label view belongs to the view's base table
            return (info.get("base") or parent) if info else parent
        if m.get("kind") == "db_table" and obj.startswith("meaning_labels."):
            info = label_bases.get(obj)
            return (info.get("base") or None) if info else None
        return None

    tables = {str(m.get("object")): i for i, m in enumerate(matches)
              if m.get("kind") == "db_table" and not str(m.get("object") or "").startswith("meaning_labels.")}
    folds: dict = {}
    for i, m in enumerate(matches):
        b = base_of(m)
        if not b or m.get("matched_values"):
            continue
        folds.setdefault(b, {"first": i, "members": []})["members"].append(m)
    for b in list(folds):
        if b in tables and tables[b] < folds[b]["first"]:
            del folds[b]                       # the table already leads its parts
    if not folds:
        return matches
    moved = {tables[b] for b in folds if b in tables}
    out, emitted = [], set()
    for i, m in enumerate(matches):
        if i in moved:
            continue
        b = base_of(m)
        if b in folds and b not in emitted and not m.get("matched_values"):
            t = dict(matches[tables[b]]) if b in tables else {
                "object": b, "kind": "db_table", "score": m.get("score"), "seams": {}, "folded": True}
            via = []
            for x in folds[b]["members"][:6]:
                entry = {"object": x.get("object"), "kind": x.get("kind")}
                info = label_bases.get(str(x.get("object"))) or label_bases.get(".".join(str(x.get("object")).split(".")[:2]))
                if info:
                    entry.update({"label": str(x.get("object")).rsplit("__", 1)[-1], "keyed_by": info.get("keys") or None,
                                  "sample_rows": info.get("sample_n")})
                via.append({k: v for k, v in entry.items() if v is not None})
            t["via"] = via
            out.append(t)
            emitted.add(b)
        obj = str(m.get("object") or "")
        parent = ".".join(obj.split(".")[:2])
        if b in emitted and not m.get("matched_values") and (label_bases.get(obj) or label_bases.get(parent)):
            continue                          # a folded label view (or its column) lives under the table's via now
        out.append(m)
    return out


def _find_hit_out(h: dict) -> dict:
    """Shape one rvbbit.find_json hit for the tool result: stable keys, the
    envelope sections verbatim, internal bookkeeping (node ids, raw rrf) dropped."""
    schema = h.get("schema") or ""
    rel = h.get("rel") or ""
    col = h.get("col")
    obj = f"{schema}.{rel}" + (f".{col}" if col else "")
    out = {
        "object": obj,
        "kind": h.get("kind"),
        "score": h.get("score"),
        "seams": h.get("seams") or {},
    }
    for key in ("why", "confidence", "rerank", "answers_ask", "matched_values", "snippet",
                "lineage", "fresh", "usage", "meaning", "ask"):
        if h.get(key) is not None:
            out[key] = h[key]
    obj_meta = h.get("object") or {}
    for key in ("data_type", "n_rows", "n_columns", "ndv", "null_frac", "is_pk",
                "fk_target", "example_values", "comment", "exists"):
        if obj_meta.get(key) is not None:
            out.setdefault("about", {})[key] = obj_meta[key]
    return out


def tool_find(query: str, limit: int = 8, schema=None, kinds=None,
              rerank: bool = True, judge: bool = False) -> dict:
    """One door into the data (rvbbit.find_json): dense + lexical + literal-value
    seams fused by rank, optional cross-encoder rerank and Jev judge, and a
    lineage / freshness / usage / meaning envelope on every hit. Internal
    schemas stay hidden, as in search_data."""
    limit = max(1, min(int(limit or 8), 25))
    opts: dict = {"rerank": bool(rerank), "judge": bool(judge)}
    if schema:
        opts["schemas"] = [str(schema)]
    if kinds:
        # accept the words people use for kinds, not only the catalog's node kinds
        aliases = {"table": "db_table", "tables": "db_table", "relation": "db_table",
                   "column": "db_column", "columns": "db_column", "field": "db_column", "fields": "db_column",
                   "cubes": "cube", "mart": "cube"}
        raw = kinds if isinstance(kinds, (list, tuple)) else str(kinds).split(",")
        wanted = []
        for k in raw:
            name = aliases.get(str(k).strip().lower(), str(k).strip().lower())
            if name in _FIND_KINDS and name not in wanted:
                wanted.append(name)
        if wanted:
            opts["kinds"] = wanted
    pool = min(limit * 2, 40)   # over-fetch so hidden schemas can be dropped without starving the answer
    try:
        with _conn() as c:
            row = c.execute(
                "SELECT rvbbit.find_json(%s, %s, %s::jsonb) AS j",
                (query, pool, json.dumps(opts)),
            ).fetchone()
    except psycopg.errors.UndefinedFunction:
        return {"error": {"code": "NOT_AVAILABLE",
                          "message": "rvbbit.find is not installed on this warehouse (migration 0437)"}}
    res = (row["j"] if row and row.get("j") else {}) or {}
    matches = []
    for h in res.get("hits") or []:
        if h.get("kind") != "cube" and not _schema_allowed(h.get("schema") or ""):
            continue
        matches.append(_find_hit_out(h))
        if len(matches) >= limit:
            break
    degraded = list(res.get("degraded") or [])
    matches = _find_fold_under_tables(matches, _find_label_bases([m.get("object") or "" for m in matches]))
    matches = _attach_meaning_to_hits(matches)
    governed = _governed_terms_for(query)
    confirmed = [g for g in governed if g.get("status") != "implied"]
    if governed:
        matches = governed + matches
        # An exact governed binding is the strongest answer find can give; the index's own
        # confidence (which may be "none" when no table matched) must not hide it. An implied
        # metric (registered by the meaning layer, unconfirmed) is a real answer, not a certain one.
        res["confidence"] = "high" if confirmed else "medium"
        res.setdefault("gates", {})
        if isinstance(res.get("gates"), dict):
            res["gates"]["governed_terms"] = len(governed)
    matches, trimmed = _find_fit_budget(matches)
    out = {
        "query": res.get("query", query),
        "matches": matches,
        "confidence": res.get("confidence"),
        "degraded": degraded,
        "gates": res.get("gates") or {},
        "elapsed_ms": res.get("elapsed_ms"),
        "seams": res.get("seams") or {},
    }
    # judged below judge_min; shown so the cut is visible — as one line each, not as full hits
    # (a full suppressed list was 17 KB beside a 12 KB budgeted match list on the pilot)
    suppressed = [{k: v for k, v in {"object": h.get("object"), "kind": h.get("kind"), "score": h.get("score"),
                                     "why": str(h.get("why") or "")[:160]}.items() if v is not None}
                  for h in (res.get("suppressed") or [])][:12]
    if suppressed:
        out["suppressed"] = suppressed
    notes = []
    if not matches and suppressed:
        notes.append(f"no matches: the judge scored all {len(suppressed)} candidates below judge_min; "
                     "see suppressed, or retry with judge=false")
    elif not matches:
        notes.append("no matches" + ("; a seam was degraded: " + "; ".join(degraded) if degraded else "; try broader terms"))
    elif degraded:
        notes.append("partial search: " + "; ".join(degraded))
    answered_by = "the governed vocabulary answered this" if confirmed else \
        "an implied metric answered this (registered by the meaning layer from a dossier candidate; no person has confirmed it)"
    if governed and len(matches) == len(governed):
        notes.append(answered_by + "; the ordinary index found nothing further")
    elif governed and res.get("weak"):
        notes.append(answered_by + "; the table hits below it are weak matches")
    elif matches and res.get("weak"):
        notes.append("weak match: nothing matched by name, by value, or with a strong embedding; "
                     "treat these as nearest neighbours, not answers")
    if trimmed:
        notes.append(trimmed)
    if notes:
        out["note"] = "; ".join(notes)
    return out


def _blend_search_hits(hits, relevance, *, limit: int, schema=None) -> list:
    # discovery gradient: business meaning and governed objects outrank raw tables —
    # when they actually match. Weak business hits (below the absolute floor and no
    # lexical overlap) drop to the bottom so tables are never crowded out.
    _tier = {
        "business_value_system": 0,
        "business_metric": 0,
        "metric": 0,
        "cube": 1,
        "business_object": 1,
        "db_table": 2,
        "db_column": 2,
    }
    _WEAK_TIER = 4

    def _rank(h):
        tier = _tier.get(h["kind"], 3)
        if h["kind"] in _BUSINESS_CONTEXT_KINDS:
            if _business_context_match(relevance, h.get("node_id"))["strong"] is False:
                tier = _WEAK_TIER
        return (tier, -float(h["boosted_score"] or h["score"] or 0))

    hits = sorted(hits, key=_rank)
    matches = []
    with _ro() as rc, rc.cursor() as cur:
        for h in hits:
            if len(matches) >= limit:
                break
            business_context = h["kind"] in _BUSINESS_CONTEXT_KINDS
            curated = h["kind"] in ("metric", "cube") or business_context
            if not curated and not _schema_allowed(h["schema_name"]):
                continue
            if schema and h["schema_name"] != schema:
                continue
            object_name = (
                h["rel_name"] if business_context else
                f'{h["schema_name"]}.{h["rel_name"]}'
                + (f'.{h["col_name"]}' if h["col_name"] else "")
            )
            m = {
                "object": object_name,
                "kind": h["kind"],
                "score": round(float(h["score"]), 3),
                "doc": h["doc"],
            }
            if business_context:
                m["business_context"] = h.get("properties") or {}
                match = _business_context_match(relevance, h.get("node_id"))
                if match["strong"] is not None:
                    m["match"] = {
                        "cosine": match["cosine"],
                        "lexical": match["lexical"],
                        "strength": "strong" if match["strong"] else "weak",
                    }
            if h["usage_touches"]:
                m["usage_touches"] = int(h["usage_touches"])   # how often employees query it
            if not business_context and not h["col_name"]:  # table/cube hit -> ground it
                # Grounding is re-read on every later agent step; three rows and a
                # bounded stats profile carry the shape without the bulk.
                m["samples"] = _clip_sample_rows(_samples(cur, h["schema_name"], h["rel_name"], 3))
                st = _col_stats(cur, h["schema_name"], h["rel_name"], max_cols=12, top_vals=4)
                if st:
                    m["column_stats"] = _clip_payload(st)
                fr = _freshness(cur, h["schema_name"], h["rel_name"])
                if fr:
                    m["freshness"] = fr
            matches.append(m)
    return matches


_BUSINESS_CONTEXT_STATUSES = {
    "proposed", "approved", "promoted", "needs_revision"
}


def _ensure_business_context_fresh(c) -> bool:
    """Repair the rebuildable Business Context projection on first stale read.

    Two independent repairs: a structurally stale projection is rebuilt with
    embeddings, and a projection whose documents were pre-warmed lexically by
    the cheap cron lane (``business_context_crawl(false)``) but never embedded
    gets its missing vectors filled in. Without the second repair a fresh-but-
    unembedded projection makes semantic retrieval silently return nothing.
    """
    probe = c.execute(
        "SELECT to_regprocedure('rvbbit.business_context_search_stale()') IS NOT NULL AS stale_ok, "
        "to_regprocedure('rvbbit.business_context_embed_pending()') IS NOT NULL AS embed_ok"
    ).fetchone()
    if not probe or not probe["stale_ok"]:
        return False
    repaired = False
    if bool(c.execute("SELECT rvbbit.business_context_search_stale() AS stale").fetchone()["stale"]):
        c.execute("SELECT rvbbit.business_context_crawl(true)")
        repaired = True
    if probe["embed_ok"] and bool(
        c.execute("SELECT rvbbit.business_context_embed_pending() AS pending").fetchone()["pending"]
    ):
        c.execute("SELECT rvbbit.business_context_embed_missing(200)")
        repaired = True
    return repaired


def tool_search_business_context(
    query: str, limit: int = 8, statuses=None
) -> dict:
    """Search the company's interpreted business meaning, not raw schema.

    Results are compact projections of reconciled Value Systems, their metrics,
    and validated contributors/dimensions. Promoted results identify their
    governed metric and cube handles; proposals are labeled as proposals.
    """
    limit = max(1, min(int(limit or 8), 25))
    requested = statuses
    if requested is None:
        requested = ["promoted", "approved", "proposed"]
    elif isinstance(requested, str):
        requested = [value.strip() for value in requested.split(",") if value.strip()]
    else:
        requested = [str(value).strip() for value in requested if str(value).strip()]
    # Agents guess status words (review, reconciled, observed…); a quarter of calls on the
    # pilot failed on vocabulary. Unknown values are dropped and reported, never fatal.
    invalid = sorted(set(requested) - _BUSINESS_CONTEXT_STATUSES)
    requested = [value for value in requested if value in _BUSINESS_CONTEXT_STATUSES]
    if not requested:
        requested = ["promoted", "approved", "proposed"]
    rebuilt = False
    try:
        with _conn() as c:
            rebuilt = _ensure_business_context_fresh(c)
            rows = c.execute(
                "SELECT node_id,kind,handle,score,doc,properties "
                "FROM rvbbit.business_context_search(%s,%s,%s)",
                (query, limit, requested or None),
            ).fetchall()
            state = c.execute(
                "SELECT crawled_at,node_count,embedded_count,last_error "
                "FROM rvbbit.business_context_state WHERE singleton"
            ).fetchone()
            relevance = _business_context_relevance(c, query) if rows else None
    except psycopg.errors.UndefinedFunction:
        return {"error": {"code": "NOT_AVAILABLE", "message": "Business Context retrieval is not installed yet"}}
    # `score` is rank-normalized (best hit of any query = 1.0); `match` carries the
    # absolute signal so a caller can tell "closest thing we have" from a real hit.
    matches = []
    strong_count = 0
    for row in rows:
        m = dict(row)
        match = _business_context_match(relevance, row.get("node_id"))
        if match["strong"] is not None:
            m["match"] = {
                "cosine": match["cosine"],
                "lexical": match["lexical"],
                "strength": "strong" if match["strong"] else "weak",
            }
            strong_count += 1 if match["strong"] else 0
        matches.append(m)
    out = {
        "query": query,
        "matches": matches,
        "projection": state,
        "hint": (
            "Open a value_system handle with get_business_value_system. "
            "For promoted business_metric hits, use metric() for the canonical total "
            "and business_metric_change for contributor attribution."
        ),
    }
    if matches and relevance is not None and strong_count == 0:
        out["note"] = (
            "No business context matches this query strongly; these are the nearest "
            "neighbours only. The subject is probably not modelled yet — try search_data "
            "for raw tables."
        )
    if rebuilt:
        out["index_rebuilt"] = "Business Context was stale and rebuilt before this search"
    if invalid:
        out["ignored_statuses"] = invalid
        out["valid_statuses"] = sorted(_BUSINESS_CONTEXT_STATUSES)
    return out


def tool_business_context_for_question(question: str) -> dict:
    """Return the same compact promoted-context packet ordinary chats receive.

    The packet is question-ranked when retrieval finds a useful handle and
    ambient otherwise, so unfamiliar business meaning remains discoverable.
    It contains no retained event SQL and never treats pending proposals as
    canonical. This is useful for explicit inspection or a mid-turn reframing;
    the Calliope notebook already performs it automatically before each chat.
    """
    try:
        import calliope

        packet = calliope._business_context_question_packet(_conn, question)
    except Exception as exc:  # noqa: BLE001 - mixed-version appliance fallback
        return {"error": {"code": "CONTEXT_PACKET_FAILED", "message": str(exc)}}
    if not packet:
        return {
            "available": False,
            "mode": "none",
            "value_systems": [],
            "hint": "No promoted Business Value System is available yet.",
        }
    visible_systems = [
        system for system in packet.get("value_systems") or []
        if isinstance(system, dict) and _schema_allowed(str(system.get("domain_key") or ""))
    ]
    visible_graphs = {str(system.get("graph_id")) for system in visible_systems}
    return {
        **packet,
        "value_systems": visible_systems,
        "matches": [
            match for match in packet.get("matches") or []
            if not match.get("graph_id") or str(match.get("graph_id")) in visible_graphs
        ],
        "available": bool(visible_systems),
        "hint": (
            "The web notebook supplies this automatically. Use promoted governed handles for "
            "calculation; ambient systems are navigation only."
        ),
    }


def _meaning_compact_succession(value) -> dict | None:
    """Succession as an agent should read it: what this object replaced (or what replaced it),
    since when, and the comparability warning that comes with it."""
    if not isinstance(value, dict):
        return None
    out = {}
    succeeds = value.get("succeeds") if isinstance(value.get("succeeds"), dict) else None
    if succeeds:
        out["supersedes"] = list(succeeds.get("supersedes") or [])[:6]
        out["since"] = succeeds.get("effective_from")
        out["federation"] = succeeds.get("federation")
        if succeeds.get("note"):
            out["note"] = str(succeeds["note"])[:400]
    by = [b for b in (value.get("superseded_by") or []) if isinstance(b, dict)]
    if by:
        out["superseded_by"] = [{k: v for k, v in {"by": b.get("by"), "since": b.get("effective_from"),
                                                    "note": str(b.get("note") or "")[:400] or None}.items() if v} for b in by[:3]]
    return out or None


def _meaning_compact_vocabulary(value) -> dict | None:
    if not isinstance(value, dict):
        return None
    out = {}
    if value.get("bound_terms"):
        out["bound_terms"] = [{"term": t.get("term"), "gloss": str(t.get("gloss") or "")[:240]} for t in value["bound_terms"] if isinstance(t, dict)][:4]
    if value.get("term_collisions"):
        out["term_collisions"] = [{"term": t.get("term"), "means": t.get("means"), "gloss": str(t.get("gloss") or "")[:240]}
                                  for t in value["term_collisions"] if isinstance(t, dict)][:4]
    if value.get("governed_metrics"):
        out["governed_metrics"] = [{k: v for k, v in {"metric": g.get("metric"), "version": g.get("version"),
                                                     "canonical_for": g.get("canonical_for")}.items() if v}
                                   for g in value["governed_metrics"] if isinstance(g, dict)][:6]
    return out or None


def _clip_statement(text, limit: int) -> tuple[str, bool]:
    """Shorten a stated line for a compact reading and say so: whole when it fits,
    otherwise at the last sentence end before the limit (failing that, a word), always
    ending in an ellipsis so the reader knows there is more and can ask for it."""
    flat = " ".join(str(text or "").split())
    if len(flat) <= limit:
        return flat, False
    head = flat[:limit]
    for sep in (". ", "; ", ": "):
        i = head.rfind(sep)
        if i >= limit // 3:
            return head[: i + 1].rstrip() + " …", True
    i = head.rfind(" ")
    return (head[:i] if i >= limit // 3 else head).rstrip() + " …", True


def _meaning_json(value: Any) -> dict | None:
    """A jsonb column as a dict, whether the driver handed back text or a mapping."""
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return None
    return value if isinstance(value, dict) else None


def _meaning_stated_only(extras: Any, *, full: bool) -> dict | None:
    """The meaning block for a relation with no card: only what people stated about it
    (caveats, succession, vocabulary) and the lenses over it. It says so in `card` and
    `note`, so a reader does not take a statement for a judgement. None when nothing
    was stated either."""
    extras = _meaning_json(extras)
    if not extras:
        return None
    caveats_all = [c for c in (extras.get("caveats") or []) if isinstance(c, dict) and c.get("text")]
    caveats_shown = caveats_all if full else caveats_all[:4]
    out = {
        "card": "none",
        "note": "no Meaning card yet (not registered, or the sweep has not reached it): this is only what people stated",
        "succession": _meaning_compact_succession(extras.get("succession")),
        "caveats": [_meaning_caveat_entry(c, full=full) for c in caveats_shown] or None,
        "caveats_more": (len(caveats_all) - len(caveats_shown)) or None,
        "vocabulary": _meaning_compact_vocabulary(extras.get("vocabulary")),
        "measured_through": _meaning_compact_measured_through(extras.get("measured_through")),
        "lens": _meaning_compact_lens(extras.get("lens")),
        "provisional": True,
    }
    out = {k: v for k, v in out.items() if v is not None}
    return out if any(k in out for k in ("succession", "caveats", "vocabulary", "measured_through", "lens")) else None


def _meaning_compact_lens(lens: Any) -> dict | None:
    """A cube's lens (migration 0454) as describe_table hands it over: grain, what it
    derives from, which subjects it spans, the metrics that read it, refresh state, use."""
    if not isinstance(lens, dict):
        return None
    refresh = lens.get("refresh") if isinstance(lens.get("refresh"), dict) else {}
    usage = lens.get("usage") if isinstance(lens.get("usage"), dict) else {}
    out = {
        "grain": lens.get("grain"),
        "derives_from": [d.get("relation") for d in (lens.get("derives_from") or []) if isinstance(d, dict) and d.get("relation")] or None,
        "spans": [d.get("name") for d in (lens.get("spans") or []) if isinstance(d, dict) and d.get("name")] or None,
        "dimensions": list(lens.get("dimensions") or [])[:12] or None,
        "measures": list(lens.get("measures") or [])[:12] or None,
        "time": lens.get("time"),
        "metrics": [m.get("name") for m in (lens.get("metrics") or []) if isinstance(m, dict) and m.get("name")][:12] or None,
        "refreshed_at": refresh.get("at"),
        "refresh_cron": refresh.get("cron"),
        "dirty": refresh.get("dirty"),
        "touches_30d": usage.get("touches_30d"),
    }
    return {k: v for k, v in out.items() if v is not None} or None


def _meaning_compact_measured_through(items: Any) -> list[str] | None:
    """source → lens → metrics, one line per lens: 'cubes.x (3 metrics: a, b, c)'."""
    if not isinstance(items, list):
        return None
    out = []
    for t in items:
        if not isinstance(t, dict) or not t.get("lens"):
            continue
        metrics = [str(m) for m in (t.get("metrics") or [])]
        out.append(f"{t['lens']} ({len(metrics)} metric{'' if len(metrics) == 1 else 's'}"
                   + (": " + ", ".join(metrics[:6]) + (", …" if len(metrics) > 6 else "") if metrics else "") + ")")
    return out[:6] or None


def _meaning_caveat_entry(c: dict, *, full: bool, limit: int = 240) -> dict:
    """One stated caveat as describe_table hands it over: the id retire_caveat takes,
    the text (whole on a full reading, cut at a sentence otherwise), the as-of date."""
    text, cut = (str(c.get("text") or ""), False) if full else _clip_statement(c.get("text"), limit)
    entry = {"id": c.get("id"), "text": text, "as_of": c.get("as_of"), "cut": True if cut else None}
    return {k: v for k, v in entry.items() if v is not None}


def _meaning_summary(schema: str, rel: str, *, full: bool = False) -> dict | None:
    """Compact Meaning card (docs/MEANING_PLAN.md) for one relation: what it is, how it
    relates, whether it deserves metrics, whether it drifts — provisional, with provenance.
    `full` returns every caveat whole; otherwise at most four, each cut at a sentence.
    A relation with no card (never registered, or the sweep has not reached it) still
    gets a block when people stated something about it — see _meaning_stated_only.
    None when the layer is absent, or nothing is judged and nothing is stated."""
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regprocedure('rvbbit.meaning_card(text,text)') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return None
            row = c.execute("SELECT rvbbit.meaning_card(%s, %s) AS card", (schema, rel)).fetchone()
            card = _meaning_json((row or {}).get("card"))
            if card is None:
                probe = c.execute("SELECT to_regprocedure('rvbbit.meaning_card_extras(text)') IS NOT NULL AS ok").fetchone()
                if not probe or not probe.get("ok"):
                    return None
                row = c.execute("SELECT rvbbit.meaning_card_extras(%s) AS extras", (f"{schema}.{rel}".lower(),)).fetchone()
                return _meaning_stated_only((row or {}).get("extras"), full=full)
    except Exception:
        return None
    if not isinstance(card, dict):
        return None
    relates = card.get("relates") if isinstance(card.get("relates"), dict) else {}
    joins = [f"{j.get('via')} → {j.get('to')}" + (f" ({j.get('state')})" if j.get("state") != "verified" else "")
             for j in (relates.get("joins_to") or [])[:6] if isinstance(j, dict)]
    joined_by = [f"{j.get('from')}.{j.get('via')}" for j in (relates.get("joined_by") or [])[:4] if isinstance(j, dict)]
    measured = card.get("measured_by") if isinstance(card.get("measured_by"), dict) else {}
    drift = card.get("drift") if isinstance(card.get("drift"), dict) else {}
    provenance = card.get("provenance") if isinstance(card.get("provenance"), dict) else {}
    domain = card.get("domain") if isinstance(card.get("domain"), dict) else {}
    subject = None
    if domain.get("name"):
        subject = {k: v for k, v in {
            "name": domain.get("name"),
            "role": domain.get("role"),
            "about": str(domain.get("about") or "")[:280] or None,
            "areas": [a.get("name") for a in (domain.get("areas") or []) if isinstance(a, dict) and a.get("name")][:2] or None,
            "usable": domain.get("usable"),
        }.items() if v is not None}
    caveats_all = [c for c in (card.get("caveats") or []) if isinstance(c, dict) and c.get("text")]
    caveats_shown = caveats_all if full else caveats_all[:4]
    out = {
        "what": str(card.get("what") or "")[:400],
        "kind": card.get("kind"),
        "name": card.get("name"),
        "keys": card.get("keys"),
        "time": card.get("time"),
        "joins_to": joins or None,
        "joined_by": joined_by or None,
        "measured_by": {k: v for k, v in measured.items() if k in ("metrics", "cubes") and v} or None,
        "measured_through": _meaning_compact_measured_through(card.get("measured_through")),
        "lens": _meaning_compact_lens(card.get("lens")),
        "deserves_metrics": card.get("deserves_metrics"),
        "personal_data": (card.get("personal_data") or [])[:6] or None,
        "drift": {k: drift.get(k) for k in ("flags", "severity", "rows_pct") if drift.get(k)} or None,
        "subject": subject,
        "succession": _meaning_compact_succession(card.get("succession")),
        "caveats": [_meaning_caveat_entry(c, full=full) for c in caveats_shown] or None,
        "caveats_more": (len(caveats_all) - len(caveats_shown)) or None,
        "vocabulary": _meaning_compact_vocabulary(card.get("vocabulary")),
        "confidence": card.get("confidence"),
        "provisional": "stated_by_people" not in provenance,
        "note": provenance.get("note"),
    }
    return {k: v for k, v in out.items() if v is not None}


def _meaning_column_roles(schema: str, rel: str) -> dict[str, dict]:
    """Per-column role / join target / personal-data score from the Meaning layer."""
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regclass('rvbbit.meaning_columns') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return {}
            rows = c.execute(
                "SELECT col_name, role, ref_target, pii FROM rvbbit.meaning_columns "
                "WHERE relation = %s AND role IS NOT NULL", (f"{schema}.{rel}".lower(),)
            ).fetchall()
    except Exception:
        return {}
    out: dict[str, dict] = {}
    for r in rows:
        entry = {"role": r.get("role")}
        if r.get("ref_target"):
            entry["refers_to"] = r["ref_target"]
        if r.get("pii") is not None and float(r["pii"]) >= 0.6:
            entry["personal_data"] = True
        out[str(r.get("col_name"))] = entry
    return out


_FIND_RESULT_BUDGET_CHARS = 14_000


def _find_fit_budget(matches: list[dict], budget: int = _FIND_RESULT_BUDGET_CHARS) -> tuple[list[dict], str | None]:
    """Keep a find result readable in one glance. One result on the pilot ran to 48 KB
    (matched values and example values on every hit); the budget trims the heavy fields
    first, then the tail of the list, and says what it dropped."""
    def size(items):
        return len(json.dumps(items, default=str))
    if size(matches) <= budget:
        return matches, None
    steps = []
    for m in matches:
        about = m.get("about") if isinstance(m.get("about"), dict) else None
        if about and isinstance(about.get("example_values"), list) and len(about["example_values"]) > 4:
            about["example_values"] = about["example_values"][:4]
        if isinstance(m.get("matched_values"), list) and len(m["matched_values"]) > 4:
            m["matched_values"] = m["matched_values"][:4]
        if isinstance(m.get("snippet"), str) and len(m["snippet"]) > 240:
            m["snippet"] = m["snippet"][:240] + "…"
    steps.append("trimmed example/matched values")
    if size(matches) > budget:
        for m in matches:
            for key in ("lineage", "usage", "seams", "rerank"):
                m.pop(key, None)
        steps.append("dropped lineage/usage detail")
    dropped = 0
    while size(matches) > budget and len(matches) > 3:
        matches.pop()
        dropped += 1
    if dropped:
        steps.append(f"dropped the last {dropped} hits")
    return matches, "result trimmed to fit: " + ", ".join(steps) + " (narrow the query or pass a smaller limit)"


def _governed_terms_for(query: str) -> list[dict]:
    """Governed vocabulary the query mentions — Resolution Ledger bindings and metric
    names/aliases — as hits above the tables, so "leads" answers with the governed metric
    (and what it excludes) before any column that happens to be named leads."""
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regprocedure('rvbbit.meaning_governed_terms(text,int)') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return []
            row = c.execute("SELECT rvbbit.meaning_governed_terms(%s, 4) AS j", (str(query or "")[:400],)).fetchone()
    except Exception:
        return []
    value = (row or {}).get("j")
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            value = None
    out = []
    for g in value or []:
        if not isinstance(g, dict):
            continue
        referent = g.get("referent") if isinstance(g.get("referent"), dict) else {}
        metric = g.get("metric") if isinstance(g.get("metric"), dict) else {}
        target = (f"metric {metric.get('name') or referent.get('name')}" + (f" v{metric['version']}" if metric.get("version") else "")
                  if referent.get("kind") == "metric" else
                  f"table {str(referent.get('schema') or 'public')}.{referent.get('relation')}" if referent.get("kind") == "relation" else
                  f"{referent.get('kind')} {referent.get('slug') or ''}")
        hit = {
            "object": target, "kind": "governed_term", "score": 1.0, "seams": {"vocabulary": g.get("via")},
            "term": g.get("term"), "status": g.get("status"), "taught_by": g.get("taught_by"),
            "why": f"the business term \"{g.get('term')}\" is bound to {target}",
            "gloss": str(g.get("gloss") or "")[:400],
        }
        if metric:
            hit["metric"] = {k: v for k, v in {"name": metric.get("name"), "version": metric.get("version"), "grain": metric.get("grain"),
                                                 "canonical_for": metric.get("canonical_for"), "not": metric.get("not"),
                                                 "source_objects": metric.get("source_objects"),
                                                 "status": metric.get("status"), "subject": metric.get("subject")}.items() if v}
            if metric.get("status") == "implied":
                # registered by the meaning layer from a dossier candidate; nobody has confirmed it
                source = ", ".join(str(s) for s in (metric.get("source_objects") or [])) or "its source"
                hit["use"] = (f"metric(name={metric.get('name')!r}) for the number; it is an implied metric the meaning layer "
                              f"registered from {source} and no person has confirmed it — say so once when the number matters, "
                              "never call it governed")
            else:
                hit["use"] = f"metric(name={metric.get('name')!r}) for the governed number; describe_table on its source objects for the shape"
        out.append(hit)
    return out


def _attach_meaning_to_hits(matches: list[dict]) -> list[dict]:
    """Add the Meaning card's one-line `what`, kind and confidence to find hits (by relation)."""
    relations = sorted({".".join(str(m.get("object") or "").split(".")[:2]) for m in matches
                        if m.get("kind") in ("db_table", "db_column", "cube")})
    if not relations:
        return matches
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regclass('rvbbit.meaning_relations') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return matches
            rows = c.execute(
                "SELECT relation, what, kind, confidence, coalesce(business_name, rel_name) AS name "
                "FROM rvbbit.meaning_relations WHERE status IN ('judged', 'derived') AND relation = ANY(%s)", (relations,)
            ).fetchall()
    except Exception:
        return matches
    by_rel = {str(r["relation"]): r for r in rows}
    extras = _meaning_extras_for(list(by_rel))
    for m in matches:
        rel = ".".join(str(m.get("object") or "").split(".")[:2])
        r = by_rel.get(rel)
        if not r:
            continue
        meaning = m.get("meaning") if isinstance(m.get("meaning"), dict) else {}
        meaning.update({"what": str(r.get("what") or "")[:300], "relation_kind": r.get("kind"),
                        "name": r.get("name"), "card_confidence": r.get("confidence"), "provisional": True})
        extra = extras.get(rel) or {}
        succession = _meaning_compact_succession(extra.get("succession"))
        if succession:
            meaning["succession"] = succession
        vocabulary = _meaning_compact_vocabulary(extra.get("vocabulary"))
        if vocabulary and vocabulary.get("term_collisions"):
            meaning["term_collisions"] = vocabulary["term_collisions"]
        stated = [c for c in (extra.get("caveats") or []) if isinstance(c, dict) and c.get("text")]
        if stated:
            meaning["caveats"] = [_clip_statement(c.get("text"), 200)[0] for c in stated[:3]]
            if len(stated) > 3:
                meaning["caveats_more"] = len(stated) - 3
        m["meaning"] = meaning
    return matches


def _meaning_extras_for(relations: list[str]) -> dict[str, dict]:
    """Succession, caveats and vocabulary per relation (migration 0443), or nothing."""
    if not relations:
        return {}
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regprocedure('rvbbit.meaning_card_extras(text)') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return {}
            rows = c.execute(
                "SELECT r AS relation, rvbbit.meaning_card_extras(r) AS extras FROM unnest(%s::text[]) r", (relations[:16],)
            ).fetchall()
    except Exception:
        return {}
    out = {}
    for row in rows:
        value = row.get("extras")
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except ValueError:
                value = None
        if isinstance(value, dict) and value:
            out[str(row.get("relation"))] = value
    return out


_MEANING_TREE_COMPACT_NOUNS = 24


def _meaning_concept_compact(c: dict) -> dict:
    """A concept (nouns folded into one thing at several grains and layers) as the agent
    sees it: the canonical table to read, the members as one line each, its metrics once."""
    out = {k: c.get(k) for k in ("name", "family", "canonical", "count", "kind", "tables") if c.get(k) is not None}
    members = []
    for m in (c.get("members") or [])[:8]:
        line = f"{m.get('relation')} ({m.get('layer')}"
        if m.get("same_rows_as"):
            line += f", same rows as {m['same_rows_as']}"
        members.append(line + ")")
    if members:
        out["members"] = members
    if c.get("metrics"):
        out["metrics"] = [m.get("metric") or m.get("name") for m in c["metrics"] if m.get("name")][:6]
    if c.get("derived_metrics"):
        out["derived_metrics"] = [m.get("name") for m in c["derived_metrics"] if m.get("name")][:5]
    return out


def _meaning_tree_compact(tree: dict) -> dict:
    """The tree with each noun cut to what an agent needs to orient: name, count, kind,
    three dimensions with value counts, what hangs off it (four edges with fan-out), what
    it points at, and the names of its metrics; the first 24 nouns in full, the rest by
    name under `more_nouns`. Measured on the pilot at ~18 KB for a 40-noun subject with its
    questions, candidate metrics and gaps (the untrimmed tree is ~100 KB). Full detail per noun comes from meaning_tree(table=...)."""
    def noun(n: dict) -> dict:
        out = {k: n.get(k) for k in ("name", "relation", "count", "kind", "role", "time") if n.get(k) is not None}
        dims = [f"{d.get('name')} ({d.get('values')})" if d.get("values") else str(d.get("name")) for d in (n.get("dimensions") or [])[:3]]
        if dims:
            out["dimensions"] = dims
        has = [{k: h.get(k) for k in ("name", "count", "per_parent") if h.get(k) is not None} for h in (n.get("has") or [])[:4]]
        if has:
            out["has"] = has
        pts = [f"{p.get('name')} via {p.get('via')}" for p in (n.get("points_at") or [])[:3]]
        if pts:
            out["points_at"] = pts
        if n.get("metrics"):
            out["metrics"] = [m.get("name") for m in n["metrics"] if m.get("name")][:6]
        if n.get("derived_metrics"):
            out["derived_metrics"] = [m.get("name") for m in n["derived_metrics"] if m.get("name")][:5]
        if n.get("measured_by"):
            out["measured_by"] = list(n["measured_by"])[:4]
        if n.get("measured_through"):
            out["measured_through"] = _meaning_compact_measured_through(n["measured_through"])
        if n.get("lens"):
            out["lens"] = _meaning_compact_lens(n["lens"])
        if n.get("drift"):
            out["drift"] = n["drift"]
        return out
    # the fold: a noun that is a non-canonical member of a concept says so and leaves its
    # derived metrics to the concept (the same "Total spend" was on every member's tile)
    part_of: dict[str, str] = {}
    for c in tree.get("concepts") or []:
        for m in c.get("members") or []:
            if m.get("relation") and m.get("relation") != c.get("canonical"):
                part_of[m["relation"]] = c.get("name") or c.get("canonical") or ""
    areas, more, shown = [], [], 0
    for a in tree.get("areas") or []:
        nouns = []
        for n in a.get("nouns") or []:
            if shown < _MEANING_TREE_COMPACT_NOUNS:
                compact = noun(n)
                if n.get("relation") in part_of:
                    compact["part_of"] = part_of[n["relation"]]
                    compact.pop("derived_metrics", None)
                nouns.append(compact)
                shown += 1
            else:
                more.append(f"{n.get('name')} ({n.get('relation')})")
        areas.append({k: v for k, v in {
            "name": a.get("name"), "about": a.get("about"),
            "nouns": nouns,
            "other_tables": a.get("other_tables"),
        }.items() if v is not None})
    out = {k: tree.get(k) for k in ("subject", "key", "about", "tables", "nouns", "roles", "usable") if tree.get(k) is not None}
    if tree.get("concepts"):
        out["concepts"] = [_meaning_concept_compact(c) for c in tree["concepts"]][:12]
        if tree.get("folded"):
            out["folded_tables"] = tree["folded"]
    out["areas"] = areas
    if more:
        out["more_nouns"] = more
    if tree.get("derived"):
        out["repeated_derived"] = [{k: d.get(k) for k in ("name", "sources", "canonical") if d.get(k)} for d in tree["derived"]][:10]
    if tree.get("lenses"):
        out["lenses"] = [dict({k: l.get(k) for k in ("name", "relation", "what") if l.get(k)}, **(_meaning_compact_lens(l) or {}))
                         for l in tree["lenses"] if isinstance(l, dict)][:12]
    if tree.get("metrics"):
        out["candidate_metrics"] = [{k: m.get(k) for k in ("name", "formula", "grain", "metric", "status") if m.get(k)} for m in tree["metrics"]][:12]
    if tree.get("breakdowns"):
        out["candidate_breakdowns"] = [{k: b.get(k) for k in ("name", "purpose", "measures", "dimensions", "grain", "caveats")
                                        if b.get(k)} for b in tree["breakdowns"]][:12]
    if tree.get("questions"):
        out["questions"] = list(tree["questions"])[:8]
    if tree.get("gaps"):
        out["gaps"] = list(tree["gaps"])[:6]
    return out


_TEACH_MEANING_FIELDS = ("business_name", "what", "kind", "domain_key", "ignore", "keys", "succession", "caveat", "retire_caveat")
# with column= set, only these fields make sense (0457): a column can be ignored, re-roled, marked personal
# or pointed at what it references; everything else is a statement about the relation as a whole
_TEACH_MEANING_COLUMN_FIELDS = ("ignore", "role", "pii", "ref_target")


def _teach_meaning_card_value(card: Any) -> dict:
    card_value = (card or {}).get("card") if isinstance(card, dict) else None
    if isinstance(card_value, str):
        try:
            card_value = json.loads(card_value)
        except ValueError:
            card_value = {}
    return card_value if isinstance(card_value, dict) else {}


def _teach_meaning_card_now(card: Any) -> dict | None:
    """What the card says after the write. Caveats carry their ids so a wrong
    line can be retired from chat; None when the relation has no card."""
    card_value = _teach_meaning_card_value(card)
    if not card_value:
        return None
    caveats = [
        {"id": x.get("id"), "text": str(x.get("text") or "")[:300]}
        for x in (card_value.get("caveats") or []) if isinstance(x, dict)
    ][:8]
    return {k: v for k, v in {
        "name": card_value.get("name"), "what": str(card_value.get("what") or "")[:300], "kind": card_value.get("kind"),
        "succession": _meaning_compact_succession(card_value.get("succession")),
        "caveats": caveats or None,
    }.items() if v is not None}


def _teach_meaning_no_card(card: Any, target: str) -> dict | None:
    """Say plainly when a fact landed on a relation with no card. The appliance's
    own schemas (rvbbit, seeds, hindsight, …) are not carded by Meaning, and a table
    the sweep has not reached has no card yet; the statement is still read —
    describe_table shows it under `meaning` as stated-only (`card: none`) — but
    nothing judged sits beside it. A cube has a derived card (its lens, migration
    0454) once it is built."""
    if _teach_meaning_card_value(card):
        return None
    return {
        "relation": target,
        "reason": "this relation has no Meaning card (its schema is not carded, it is a cube not built yet, or the sweep has not reached it); "
                  "the statement is stored and describe_table shows it under meaning as stated-only (card: none), "
                  "but nothing judged sits beside it",
    }


def tool_teach_meaning(relation: str, field: str, value, reason: str | None = None, column: str | None = None) -> dict:
    """Bank a fact a person told you about a table so every later reader has it: its business
    name, what one row is, its kind, its subject, that it should be ignored, a dated caveat
    ({text, as_of}), its keys (the columns that identify one row, e.g. ["parent_asin"] — the
    next enrichment keys its labels by them instead of guessing a text column), or a succession
    ({supersedes: [schema.table, …], effective_from: YYYY-MM-DD, federation: switch|union|mapped,
    note}) when an object replaced another — the Person cutover kind of knowledge. The statement is an override: it wins over the appliance's own judgement,
    is attributed to Calliope on the person's word, shows on the card, on find hits, in the tree
    and in the turn packet, and a person can retire a wrong caveat with field='retire_caveat' and its id, or in DataRabbit.
    With column= set, the fact is about one column: field='ignore' (value true) keeps it out of suggested
    metrics, breakdowns and classification candidates; 'role' (measure|category|identifier|free_text|…),
    'pii' (0-1) and 'ref_target' (schema.table) correct what the sweep judged. Caveats and column ignores
    reach the Meaning worker's dossier and enrichment packets as `stated`, and a stated subject moves the
    table between subjects."""
    schema, rel = _split(relation)
    if not _schema_allowed(schema):
        return {"error": {"code": "NOT_AUTHORIZED", "message": f"schema '{schema}' is not exposed"}}
    field = str(field or "").strip().lower()
    column = str(column or "").strip() or None
    if column is not None:
        if field not in _TEACH_MEANING_COLUMN_FIELDS:
            return {"error": {"code": "BAD_FIELD", "message": f"with column= set, field must be one of {', '.join(_TEACH_MEANING_COLUMN_FIELDS)}"}}
        if field == "pii":
            try:
                value = min(max(float(value), 0.0), 1.0)
            except (TypeError, ValueError):
                return {"error": {"code": "BAD_VALUE", "message": "pii is a number from 0 to 1"}}
    elif field not in _TEACH_MEANING_FIELDS:
        return {"error": {"code": "BAD_FIELD", "message": f"field must be one of {', '.join(_TEACH_MEANING_FIELDS)}"}}
    if isinstance(value, str):
        text = value.strip()
        if field in ("succession", "caveat") and text.startswith("{"):
            try:
                value = json.loads(text)
            except ValueError:
                return {"error": {"code": "BAD_VALUE", "message": "value must be JSON for this field"}}
        elif field == "caveat":
            value = {"text": text}
        elif field == "ignore":
            value = text.lower() in {"1", "true", "yes"}
        elif field == "keys":
            import re as _re
            value = [v.strip("\"' ") for v in _re.split(r"[,\s]+", text.strip("[] ")) if v.strip("\"' ")]
        else:
            value = text
    if field == "keys":
        value = [str(v).strip() for v in (value if isinstance(value, (list, tuple)) else [value]) if str(v).strip()]
        if not value:
            return {"error": {"code": "BAD_VALUE", "message": "keys needs one or more column names, in order"}}
    if not str(reason or "").strip():
        return {"error": {"code": "REASON_REQUIRED", "message": "say who stated this and why, in one sentence"}}
    target = f"{schema}.{rel}".lower()
    if field == "retire_caveat":
        # A correction is itself a receipt: the wrong line is retired with who and why,
        # never edited or deleted. Ids are the ones card_now.caveats hands back.
        try:
            caveat_id = int(str(value.get("text") if isinstance(value, dict) else value).strip())
        except (TypeError, ValueError, AttributeError):
            return {"error": {"code": "BAD_VALUE", "message": "value must be the caveat id shown in card_now.caveats"}}
        try:
            with _conn() as c:
                owned = c.execute(
                    "SELECT override_id FROM rvbbit.meaning_overrides WHERE override_id=%s AND relation=%s "
                    "AND field='caveat' AND retired_at IS NULL",
                    (caveat_id, target),
                ).fetchone()
                if not owned:
                    return {"error": {"code": "NOT_FOUND", "message": f"no live caveat {caveat_id} on {target}"}}
                c.execute("SELECT rvbbit.meaning_retire_statement(%s, %s)", (caveat_id, f"calliope: {str(reason).strip()[:4000]}"))
                card = c.execute("SELECT rvbbit.meaning_card(%s, %s) AS card", (schema, rel)).fetchone()
        except Exception as e:
            return {"error": {"code": "TEACH_FAILED", "message": str(e).split("\n")[0][:300]}}
        return {"retired": {"relation": target, "caveat_id": caveat_id, "actor": "calliope"},
                "card_now": _teach_meaning_card_now(card), "no_card": _teach_meaning_no_card(card, target)}
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regprocedure('rvbbit.meaning_state(text,text,jsonb,text,text,text)') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return {"error": {"code": "MEANING_ABSENT", "message": "the Meaning layer is not installed"}}
            row = c.execute(
                "SELECT rvbbit.meaning_state(%s, %s, %s::jsonb, %s, %s, %s) AS id",
                (target, field, json.dumps(value), str(reason).strip()[:4000], column, "calliope"),
            ).fetchone()
            card = c.execute("SELECT rvbbit.meaning_card(%s, %s) AS card", (schema, rel)).fetchone()
    except Exception as e:
        return {"error": {"code": "TEACH_FAILED", "message": str(e).split("\n")[0][:300]}}
    reply = {
        "stated": {k: v for k, v in {"relation": target, "column": column, "field": field, "value": value,
                                     "statement_id": (row or {}).get("id"), "actor": "calliope"}.items() if v is not None},
        "card_now": _teach_meaning_card_now(card),
        "no_card": _teach_meaning_no_card(card, target),
        "note": "an override: it wins over the appliance's judgement and is attributed to Calliope on the person's word; retire it in DataRabbit's Meaning window if it turns out wrong",
    }
    if field == "keys":
        reply["note"] = ("entity keys stated: the card, the tree and the next enrichment read them; label views this "
                         "relation already has keep their old key until they are re-enriched. " + str(reply.get("note") or ""))
    elif field == "ignore" and column is not None:
        reply["note"] = (f"{column} is left out of suggested metrics, breakdown dimensions and classification candidates from "
                         "now on; metrics already registered over it are untouched. " + str(reply.get("note") or ""))
    elif field == "domain_key":
        reply["note"] = ("the table now belongs to the stated subject: it left every other subject's member list and "
                         "joined this one; both subjects' dossiers are queued for a rewrite. " + str(reply.get("note") or ""))
    elif field == "caveat":
        reply["note"] = ("the Meaning worker reads live caveats when it writes the subject's dossier and proposes "
                         "classifications, and a caveat that names a measure column withholds its auto-aggregate. "
                         + str(reply.get("note") or ""))
    return reply


def tool_meaning_tree(subject: str | None = None, table: str | None = None, detail: str = "compact") -> dict:
    """The meaning tree: the company's data as business nouns with counts, not as tables.
    No arguments → the subjects (Admissions & lead pipeline, Paid media, ...) with their
    sizes and top nouns. subject=<key or name fragment> → that subject's areas, each a list of
    nouns: what it is, how many, its dimensions (with value counts), measures, what hangs off
    it (`has`: events per entity, e.g. ≈20 SMS messages per lead), what it points at, the
    dossier metrics on it and the derived metrics its columns imply (counts over time, totals
    of amounts, averages of rates, breakdowns by dimension, events per entity). `lenses` are
    the cubes over the subject: each says what it derives from, its grain, the metrics that
    read it and when it was refreshed; a noun's `measured_through` is the same path from the
    source side. A cube is never a noun — ask table=cubes.<name> for its lens in full.
    table=<schema.table> → one noun in full (every dimension with its top values, every
    derived metric with its formula and grain). detail='full' on a subject returns every noun
    in full (large, ~100 KB); the default compact tree is ~18 KB (24 nouns in full, the
    rest by name under more_nouns, plus the subject's questions, metrics and gaps). Everything here is a
    projection over the provisional Meaning cards. candidate_metrics are scalar proposals;
    candidate_breakdowns are named grouped analyses with purpose, measures and dimensions,
    to explore as queries or cubes. Say 'working assumption' when you lean on
    it, and verify counts with metric() or run_sql before asserting them."""
    try:
        with _conn() as c:
            probe = c.execute("SELECT to_regprocedure('rvbbit.meaning_tree(text,int)') IS NOT NULL AS ok").fetchone()
            if not probe or not probe.get("ok"):
                return {"error": {"code": "MEANING_TREE_ABSENT", "message": "the meaning tree is not installed (migration 0442)"}}
            if table:
                schema, rel = _split(table)
                if not _schema_allowed(schema):
                    return {"error": {"code": "NOT_AUTHORIZED", "message": f"schema '{schema}' is not exposed"}}
                row = c.execute("SELECT rvbbit.meaning_noun(%s) AS noun", (f"{schema}.{rel}".lower(),)).fetchone()
                noun = (row or {}).get("noun")
                if isinstance(noun, str):
                    noun = json.loads(noun)
                if not noun:
                    return {"error": {"code": "NOT_JUDGED", "message": f"{table} has no Meaning card yet"}}
                return {"noun": noun, "provisional": True}
            if not subject:
                row = c.execute("SELECT rvbbit.meaning_subjects() AS subjects").fetchone()
                subjects = (row or {}).get("subjects")
                if isinstance(subjects, str):
                    subjects = json.loads(subjects)
                return {"subjects": subjects or [], "provisional": True,
                        "hint": "call meaning_tree(subject=<key>) for a subject's nouns, meaning_tree(table=<schema.table>) for one noun in full"}
            key_row = c.execute(
                "SELECT domain_key, name FROM rvbbit.meaning_domains "
                " WHERE origin = 'map' AND status = 'done' "
                "   AND (domain_key = %s OR domain_key = 'subject:' || %s OR name ILIKE '%%' || %s || '%%') "
                " ORDER BY (domain_key = %s) DESC, cardinality(members) DESC LIMIT 1",
                (subject, subject, subject, subject),
            ).fetchone()
            if not key_row:
                return {"error": {"code": "SUBJECT_NOT_FOUND", "message": f"no subject matches '{subject}'",
                                  "hint": "call meaning_tree() with no arguments to list subjects"}}
            row = c.execute("SELECT rvbbit.meaning_tree(%s) AS tree", (key_row["domain_key"],)).fetchone()
            tree = (row or {}).get("tree")
            if isinstance(tree, str):
                tree = json.loads(tree)
    except Exception as e:
        return {"error": {"code": "MEANING_TREE_FAILED", "message": str(e)[:300]}}
    if not tree:
        return {"error": {"code": "SUBJECT_NOT_FOUND", "message": f"no tree for '{subject}'"}}
    if str(detail or "").lower() == "full":
        tree["provisional"] = True
        return tree
    out = _meaning_tree_compact(tree)
    out["provisional"] = True
    return out


_DESCRIBE_AUTO_LEAN_COLUMNS = 80


def _describe_detail(detail, lean) -> bool | None:
    """Resolve the requested view. `detail` wins: auto (lean past 80 columns), lean, full.
    Legacy `lean` is accepted, including the strings models actually send ("false")."""
    choice = str(detail or "").strip().lower()
    if choice in ("lean", "compact"):
        return True
    if choice in ("full", "samples", "verbose"):
        return False
    if choice in ("", "auto", "none", "null"):
        if lean is None:
            return None
        if isinstance(lean, str):
            text = lean.strip().lower()
            if text in ("", "none", "null", "auto"):
                return None
            return text in ("1", "true", "yes", "lean")
        return bool(lean)
    return None


def tool_describe_table(table: str, lean: bool | None = None, detail: str | None = None) -> dict:
    """Full profile of one table: columns, live samples, AND per-column stats — null %, distinct
    count, and the actual most-common values (the enum/value dictionary, so you never guess a
    status/type literal) — plus freshness, and its Meaning card when the appliance has judged it:
    what the table is, its keys and time column, verified joins, the metrics/cubes that read it,
    whether it deserves metrics, personal-data columns and drift. Column stats carry the judged
    `role` (identifier/reference/time/measure/category/flag/free_text/unused). Meaning is
    provisional unless stated by a person. Pass lean=true for a compact view (columns +
    null%/distinct + freshness, no samples or top-values) on wide tables to stay under the token budget.
    detail: auto (default) serves tables wider than 80 columns lean and narrow tables in
    full; 'full' forces samples and top values (a Salesforce object with 300 custom fields is
    50 KB in full, so ask for it only when you need the value dictionary); 'lean' forces the
    compact view. The legacy lean flag is still honoured. Under `meaning`, what people stated
    about the table: `caveats` come cut at a sentence in lean/auto (`cut: true`, with
    `caveats_more` for the ones not shown) and whole under 'full', each with the id that
    teach_meaning's retire_caveat takes. A cube's meaning is its `lens` (grain, what it
    derives from, the metrics that read it, refresh state); a source table's
    `measured_through` lists the lenses over it. A table with no card still gets a
    `meaning` block when people stated something about it, marked `card: none`."""
    schema, rel = _split(table)
    lean = _describe_detail(detail, lean)
    auto_lean = lean is None
    if not _schema_allowed(schema):
        return {"error": {"code": "NOT_AUTHORIZED",
                          "message": f"schema '{schema}' is not exposed"}}
    with _ro() as rc, rc.cursor() as cur:
        cols = cur.execute(
            "SELECT column_name AS name, data_type AS type FROM information_schema.columns "
            "WHERE table_schema=%s AND table_name=%s ORDER BY ordinal_position",
            (schema, rel),
        ).fetchall()
        if not cols:
            return {"error": {"code": "TABLE_NOT_FOUND", "message": table}}
        if auto_lean:
            lean = len(cols) > _DESCRIBE_AUTO_LEAN_COLUMNS
        out = {"table": f"{schema}.{rel}", "columns": cols}
        if auto_lean and lean:
            out["note"] = (f"{len(cols)} columns: served lean (no samples or top values). "
                           "Pass lean=false if you need the value dictionary, or ask for specific columns with run_sql.")
        if not lean:
            out["samples"] = _samples(cur, schema, rel, 5)
        st = _col_stats(cur, schema, rel, max_cols=128)
        if st:
            # lean: drop the (potentially long) top-values, keep ndv/null%.
            # NB: _col_stats returns a dict keyed by column name (not a row list) —
            # iterating it as rows was the "string indices must be integers" crash.
            out["column_stats"] = (
                {name: {k: v for k, v in s.items() if k != "top"} for name, s in st.items()}
                if lean else st
            )
        fr = _freshness(cur, schema, rel)
        if fr:
            out["freshness"] = fr
    meaning = _meaning_summary(schema, rel, full=lean is False)
    if meaning:
        out["meaning"] = meaning
        roles = _meaning_column_roles(schema, rel)
        if roles and isinstance(out.get("column_stats"), dict):
            for name, extra in roles.items():
                stats = out["column_stats"].get(name)
                if isinstance(stats, dict):
                    stats.update(extra)
        elif roles:
            out["column_roles"] = roles
    return out


def tool_profile_schema(schema=None) -> dict:
    """A fast overview of every (allowed) table: estimated row count + column count — to see which
    tables are populated WITHOUT running count(*) probes. Optionally scope to one schema. Row counts
    are planner estimates (pg_class.reltuples, ~0 if never analyzed); use describe_table for a full
    per-column profile of one table."""
    with _ro() as rc, rc.cursor() as cur:
        rows = cur.execute(
            "SELECT n.nspname AS schema, c.relname AS \"table\", "
            "       greatest(c.reltuples, 0)::bigint AS est_rows, "
            "       (SELECT count(*) FROM information_schema.columns ic "
            "          WHERE ic.table_schema = n.nspname AND ic.table_name = c.relname) AS columns "
            "FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace "
            "WHERE c.relkind IN ('r','p','f') "
            "  AND n.nspname NOT LIKE 'pg_%%' AND n.nspname <> 'information_schema' "
            "  AND (%s::text IS NULL OR n.nspname = %s::text) "
            "ORDER BY n.nspname, c.relname",
            (schema, schema),
        ).fetchall()
    rows = [r for r in rows if _schema_allowed(r["schema"])]
    return {"tables": rows, "note": "est_rows are planner estimates; 0 may mean empty OR never-analyzed"}


def tool_list_metrics(category=None, search=None) -> dict:
    """The blessed, governed metric catalog (latest version per metric), with its category. Read
    from metric_catalog (not metric_defs) so the shared category/subcategory taxonomy is included —
    use the optional `category` filter to scope to one subject area."""
    with _conn() as c:
        rows = c.execute(
            "SELECT name, description, params, grain, check_sql IS NOT NULL AS has_check, version, "
            "category, subcategory "
            "FROM rvbbit.metric_catalog "
            "WHERE (%s::text IS NULL OR description ILIKE '%%'||%s::text||'%%' OR name ILIKE '%%'||%s::text||'%%') "
            "  AND (%s::text IS NULL OR category = %s::text) "
            "ORDER BY name",
            (search, search, search, category, category),
        ).fetchall()
    return {"metrics": rows}


def tool_get_metric(name: str) -> dict:
    """One metric's definition, history, and attached Business Context."""
    with _conn() as c:
        d = c.execute(
            "SELECT name, description, params, grain, sql AS definition_sql, check_sql, "
            "category, subcategory, version, labels "
            "FROM rvbbit.metric_catalog WHERE name=%s", (name,)
        ).fetchone()
        if not d:
            return {"error": {"code": "METRIC_NOT_FOUND", "message": name}}
        d["versions"] = c.execute(
            "SELECT version, created_at FROM rvbbit.metric_defs WHERE name=%s ORDER BY version DESC",
            (name,)).fetchall()
        labels = dict(d.get("labels")) if isinstance(d.get("labels"), dict) else {}
        retained_source_sql = labels.pop("source_event_sql", None)
        if retained_source_sql:
            labels["source_event_sql_retained"] = True
            labels["source_event_sql_sha256"] = hashlib.sha256(
                str(retained_source_sql).encode("utf-8")
            ).hexdigest()
        d["labels"] = labels
        graph_id = str(labels.get("business_value_graph_id") or "").strip()
        metric_key = str(labels.get("business_value_metric_key") or "").strip()
        if graph_id and metric_key:
            try:
                context = c.execute(
                    "SELECT catalog.graph_id,catalog.domain_key,catalog.domain_name,"
                    "catalog.status,catalog.metric_key,catalog.metric_name,"
                    "catalog.metric_kind,catalog.unit,catalog.formula,catalog.grain,"
                    "catalog.time_semantics,catalog.dimensions,catalog.confidence,"
                    "catalog.is_primary,catalog.evaluation,summary.cube_name,"
                    "summary.cube_version,summary.materialization_grain,"
                    "summary.reconciled,summary.promotion_receipt "
                    "FROM rvbbit.business_value_metric_catalog catalog "
                    "JOIN rvbbit.business_value_graph_summary summary USING (graph_id) "
                    "WHERE catalog.graph_id=%s::uuid AND catalog.metric_key=%s",
                    (graph_id, metric_key),
                ).fetchone()
                if context:
                    d["business_context"] = context
                    d["business_context"]["value_system_handle"] = f"value_system:{graph_id}"
                    d["business_context"]["change_tool"] = "business_metric_change"
            except (psycopg.errors.UndefinedTable, psycopg.errors.UndefinedColumn):
                pass
    return d


def _business_context_handle_value(handle: str) -> str:
    value = str(handle or "").strip()
    for prefix in ("value_system:", "business_metric:", "business_object:", "cubes."):
        if value.startswith(prefix):
            return value[len(prefix):]
    return value


def tool_get_business_value_system(handle: str, include_sql: bool = False) -> dict:
    """Open one receipt-backed Value System by handle, UUID, domain, cube, or metric.

    Returns its business meaning, formulas, relationships, validated dimensions,
    source lineage, governance state, and reconciliation evidence. This is the
    explanation surface; use metric() and business_metric_change to calculate.
    """
    requested = _business_context_handle_value(handle)
    metric_requested = requested.rsplit(":", 1)[-1] if ":" in requested else requested
    try:
        with _conn() as c:
            _ensure_business_context_fresh(c)
            row = c.execute(
                "SELECT summary.* FROM rvbbit.business_value_graph_summary summary "
                "WHERE summary.graph_id::text=%s OR summary.domain_key=%s "
                "OR lower(summary.name)=lower(%s) OR summary.cube_name=%s "
                "OR EXISTS ("
                "  SELECT 1 FROM jsonb_each_text(coalesce(summary.metric_versions,'{}'::jsonb)) version "
                "  WHERE version.key=%s"
                ") OR EXISTS ("
                "  SELECT 1 FROM rvbbit.business_value_metric_catalog metric "
                "  WHERE metric.graph_id=summary.graph_id "
                "    AND metric.metric_key=%s"
                ") "
                "ORDER BY CASE WHEN summary.graph_id::text=%s THEN 0 "
                "WHEN summary.graph_id=summary.active_graph_id THEN 1 "
                "WHEN summary.status='promoted' THEN 2 WHEN summary.status='approved' THEN 3 ELSE 4 END,"
                "summary.updated_at DESC LIMIT 1",
                (
                    requested, requested, requested, requested, requested,
                    metric_requested, requested,
                ),
            ).fetchone()
            if not row:
                return {"error": {"code": "VALUE_SYSTEM_NOT_FOUND", "message": handle}}
            graph_id = str(row["graph_id"])
            metrics = c.execute(
                "SELECT catalog.metric_key,catalog.metric_name,catalog.description,"
                "catalog.metric_kind,catalog.unit,catalog.formula,catalog.grain,"
                "catalog.time_semantics,catalog.dimensions,catalog.primary_dimension_key,"
                "catalog.confidence,catalog.is_primary,catalog.evaluation,"
                "catalog.event_sql AS source_event_sql,governed.name AS governed_metric_name,"
                "governed.version AS governed_metric_version "
                "FROM rvbbit.business_value_metric_catalog catalog "
                "LEFT JOIN LATERAL ("
                "  SELECT metric.name,metric.version FROM rvbbit.metric_catalog metric "
                "  WHERE metric.labels->>'business_value_graph_id'=catalog.graph_id::text "
                "    AND metric.labels->>'business_value_metric_key'=catalog.metric_key "
                "  ORDER BY metric.version DESC LIMIT 1"
                ") governed ON true "
                "WHERE catalog.graph_id=%s::uuid "
                "ORDER BY CASE WHEN catalog.is_primary THEN 0 ELSE 1 END,catalog.metric_key",
                (graph_id,),
            ).fetchall()
            if not include_sql:
                for metric in metrics:
                    retained_sql = metric.pop("source_event_sql", None)
                    if retained_sql:
                        metric["source_event_sql_retained"] = True
                        metric["source_event_sql_sha256"] = hashlib.sha256(
                            str(retained_sql).encode("utf-8")
                        ).hexdigest()
            graph = row.get("graph") if isinstance(row.get("graph"), dict) else {}
            receipt = row.get("receipt") if isinstance(row.get("receipt"), dict) else {}
            return {
                "handle": f"value_system:{graph_id}",
                "graph_id": graph_id,
                "domain_key": row["domain_key"],
                "name": row["name"],
                "summary": row["summary"],
                "status": row["status"],
                "lifecycle": row.get("lifecycle") or row["status"],
                "usable": bool(row.get("usable")),
                "family_id": str(row["family_id"]) if row.get("family_id") else None,
                "family_revision": row.get("family_revision"),
                "family_review_state": row.get("family_review_state"),
                "canonical_graph_id": str(row["canonical_graph_id"]) if row.get("canonical_graph_id") else None,
                "pending_graph_id": str(row["pending_graph_id"]) if row.get("pending_graph_id") else None,
                "source_relations": row["source_relations"],
                "primary_metric_key": row["primary_metric_key"],
                "metrics": metrics,
                "relationships": graph.get("edges", []),
                "open_questions": graph.get("open_questions", []),
                "reconciliation": receipt.get("evaluation", {}),
                "promotion": None if not row.get("promotion_id") else {
                    "promotion_id": row["promotion_id"],
                    "cube_name": row["cube_name"],
                    "cube_version": row["cube_version"],
                    "materialization_grain": row["materialization_grain"],
                    "metric_versions": row["metric_versions"],
                    "receipt": row["promotion_receipt"],
                    "promoted_at": row["promoted_at"],
                    "last_refreshed_at": row["last_refreshed_at"],
                },
                "guidance": (
                    "Use each governed_metric_name with metric() for canonical totals. "
                    "Use business_metric_change with one listed dimension key to explain movement."
                    if row["status"] == "promoted" else
                    (
                        "This reconciled Value System is provisionally usable for exploration and explanation. "
                        "Label it provisional, preserve its lineage, and do not present it as the canonical "
                        "governed metric or cube."
                        if row.get("usable") else
                        "This is a historical excavation receipt, not active company logic."
                    )
                ),
            }
    except (psycopg.errors.UndefinedTable, psycopg.errors.UndefinedFunction):
        return {"error": {"code": "NOT_AVAILABLE", "message": "Business Context retrieval is not installed yet"}}


def tool_business_metric_change(
    name: str,
    dimension: str,
    prior_start: str,
    prior_end: str,
    current_start: str,
    current_end: str,
    limit: int = 25,
) -> dict:
    """Attribute movement in a promoted business metric to a validated dimension.

    `name` is the governed metric returned by search_business_context/get_metric.
    The two periods are half-open [start,end) timestamps. Results are computed
    from the promoted compact cube and retain the Value Graph's proven logic.
    """
    limit = max(1, min(int(limit or 25), 100))
    try:
        with _conn(read_only=True, role=_session_pg_role()) as c:
            definition = c.execute(
                "SELECT labels FROM rvbbit.metric_catalog WHERE name=%s",
                (name,),
            ).fetchone()
            labels = definition.get("labels") if definition and isinstance(definition.get("labels"), dict) else {}
            graph_id = str(labels.get("business_value_graph_id") or "").strip()
            metric_key = str(labels.get("business_value_metric_key") or "").strip()
            if not graph_id or not metric_key:
                return {"error": {
                    "code": "NOT_A_BUSINESS_VALUE_METRIC",
                    "message": f"{name} is not linked to a promoted Business Value Graph",
                }}
            rows = c.execute(
                "SELECT dimension_value,prior_value,current_value,change,share_of_change "
                "FROM rvbbit.business_value_metric_change("
                "%s::uuid,%s,%s,%s::timestamptz,%s::timestamptz,"
                "%s::timestamptz,%s::timestamptz,%s)",
                (
                    graph_id, metric_key, dimension,
                    prior_start, prior_end, current_start, current_end, limit,
                ),
            ).fetchall()
            context = c.execute(
                "SELECT domain_name,metric_name,formula,unit,dimensions "
                "FROM rvbbit.business_value_metric_catalog "
                "WHERE graph_id=%s::uuid AND metric_key=%s",
                (graph_id, metric_key),
            ).fetchone()
        return {
            "metric": name,
            "value_system_handle": f"value_system:{graph_id}",
            "dimension": dimension,
            "periods": {
                "prior": {"start": prior_start, "end": prior_end},
                "current": {"start": current_start, "end": current_end},
            },
            "metric_context": context,
            "contributors": rows,
            "note": "share_of_change is signed; contributors can offset one another.",
        }
    except (psycopg.errors.UndefinedTable, psycopg.errors.UndefinedFunction):
        return {"error": {"code": "NOT_AVAILABLE", "message": "Business Value change analysis is not installed yet"}}
    except psycopg.Error as exc:
        return {"error": {"code": "INVALID_CHANGE_REQUEST", "message": str(exc)}}


def tool_business_context_status(domain: str | None = None) -> dict:
    """Inspect freshness and steward work for the interpreted business model.

    Shows the live structural fingerprint versus the version last semantically
    excavated, why a domain became dirty, any queued/running topology workflow,
    and its newest business-level Change Graph receipt. This is operational
    Business Context state, not Company Brain or Hermes memory.
    """
    requested = str(domain or "").strip() or None
    if requested and not _schema_allowed(requested):
        return {"error": {"code": "NOT_AUTHORIZED", "message": f"schema '{requested}' is not exposed"}}
    try:
        with _conn() as c:
            rows = c.execute(
                "SELECT domain.domain_key,domain.status,domain.modeled_fingerprint,"
                "domain.observed_fingerprint,"
                "domain.modeled_fingerprint IS DISTINCT FROM domain.observed_fingerprint AS structurally_stale,"
                "domain.dirty_reasons,domain.dirty_since,domain.last_observed_at,"
                "domain.last_modeled_at,domain.last_error,"
                "domain.pending_workflow_run_id,workflow.status AS workflow_status,"
                "workflow.phase AS workflow_phase,workflow.progress AS workflow_progress,"
                "change.change_id,change.change_kind,change.severity AS change_severity,"
                "change.status AS change_status,change.headline AS change_headline,"
                "change.created_at AS change_created_at "
                "FROM rvbbit.business_context_domains domain "
                "LEFT JOIN rvbbit.business_topology_workflow_runs workflow "
                "  ON workflow.run_id=domain.pending_workflow_run_id "
                "LEFT JOIN rvbbit.business_context_changes change "
                "  ON change.change_id=domain.last_change_id "
                "WHERE (%s::text IS NULL OR domain.domain_key=%s::text) "
                "ORDER BY domain.domain_key",
                (requested, requested),
            ).fetchall()
    except psycopg.errors.UndefinedTable:
        return {"error": {"code": "NOT_AVAILABLE", "message": "Business Context steward is not installed yet"}}
    visible = [row for row in rows if _schema_allowed(str(row["domain_key"]))]
    return {
        "domains": visible,
        "summary": {
            "domains": len(visible),
            "clean": sum(row["status"] == "clean" for row in visible),
            "needs_attention": sum(row["status"] in {"dirty", "review", "error"} for row in visible),
            "active": sum(row["status"] in {"queued", "running"} for row in visible),
        },
        "hint": (
            "Use business_context_changes for the business-level diff. "
            "Use refresh_business_context only when a fresh observation or forced excavation is needed."
        ),
    }


def tool_refresh_business_context(domain: str, force: bool = False) -> dict:
    """Observe and, when warranted, refresh one Business Context domain.

    The default is cheap and drift-aware: it queues semantic excavation only
    when the structural fingerprint differs from the last modeled version.
    Set force=true only when the structure is unchanged but its meaning needs
    to be reconsidered. The durable topology worker runs asynchronously.
    """
    requested = str(domain or "").strip()
    if not requested:
        return {"error": {"code": "DOMAIN_REQUIRED", "message": "domain is required"}}
    if not _schema_allowed(requested):
        return {"error": {"code": "NOT_AUTHORIZED", "message": f"schema '{requested}' is not exposed"}}
    try:
        with _conn() as c:
            row = c.execute(
                "SELECT rvbbit.refresh_business_context(%s,%s) AS result",
                (requested, bool(force)),
            ).fetchone()
        return row["result"] if row else {"error": {"code": "NO_RESULT", "message": requested}}
    except psycopg.errors.UndefinedFunction:
        return {"error": {"code": "NOT_AVAILABLE", "message": "Business Context steward is not installed yet"}}
    except psycopg.Error as exc:
        return {"error": {"code": "REFRESH_FAILED", "message": str(exc)}}


def tool_business_context_changes(
    domain: str | None = None,
    since: str | None = None,
    limit: int = 20,
) -> dict:
    """Read versioned business-level changes in company-data meaning.

    Results compare a newly excavated Value System with the promoted version:
    source-boundary, metric, formula, grain, time, dimension, and relationship
    changes. Retained source SQL is never returned. `since` is an optional ISO
    timestamp and `domain` is an optional company-data schema.
    """
    requested = str(domain or "").strip() or None
    if requested and not _schema_allowed(requested):
        return {"error": {"code": "NOT_AUTHORIZED", "message": f"schema '{requested}' is not exposed"}}
    limit = max(1, min(int(limit or 20), 100))
    try:
        with _conn(read_only=True, role=_session_pg_role()) as c:
            rows = c.execute(
                "SELECT change.change_id,change.domain_key,change.workflow_run_id,"
                "change.from_graph_id,prior.name AS from_value_system,"
                "change.to_graph_id,current.name AS to_value_system,"
                "change.change_kind,change.severity,change.status,change.headline,"
                "change.diff,change.created_at,change.reviewed_by,change.reviewed_at "
                "FROM rvbbit.business_context_changes change "
                "LEFT JOIN rvbbit.business_value_graph_proposals prior "
                "  ON prior.graph_id=change.from_graph_id "
                "JOIN rvbbit.business_value_graph_proposals current "
                "  ON current.graph_id=change.to_graph_id "
                "WHERE (%s::text IS NULL OR change.domain_key=%s::text) "
                "  AND (%s::text IS NULL OR change.created_at>=%s::timestamptz) "
                "ORDER BY change.created_at DESC LIMIT %s",
                (requested, requested, since, since, limit),
            ).fetchall()
    except psycopg.errors.UndefinedTable:
        return {"error": {"code": "NOT_AVAILABLE", "message": "Business Context Change Graph is not installed yet"}}
    except psycopg.Error as exc:
        return {"error": {"code": "INVALID_CHANGE_QUERY", "message": str(exc)}}
    visible = [row for row in rows if _schema_allowed(str(row["domain_key"]))]
    return {
        "changes": visible,
        "review_required": sum(row["status"] == "pending_review" for row in visible),
        "hint": (
            "A pending_review change is a candidate interpretation; the promoted metric and cube remain canonical "
            "until the candidate is explicitly reviewed and promoted."
        ),
    }


def tool_list_cubes(category=None) -> dict:
    """Curated subject-area tables (cubes) — wide, documented, accelerated, with their category. The
    agent's entry point: look here (and at metrics) before raw tables. Optional `category` filter."""
    with _conn() as c:
        rows = c.execute(
            "SELECT name, grain, description, category, version, refreshed_at::text AS refreshed_at, rows "
            "FROM rvbbit.cubes() WHERE (%s::text IS NULL OR category = %s::text)",
            (category, category)).fetchall()
    return {"cubes": rows}


def tool_set_category(kind, name, category=None, subcategory=None) -> dict:
    """Categorize a cube or metric (kind = 'cube' | 'metric') in the shared taxonomy — lightweight
    and mutable (no new version). Pass category=null to clear it. Use this to organize the catalog;
    read it back via list_cubes / list_metrics."""
    with _conn() as c:
        try:
            c.execute("SELECT rvbbit.set_category(%s, %s, %s, %s)", (kind, name, category, subcategory))
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "SET_CATEGORY_FAILED", "message": str(e)}}
    return {"kind": kind, "name": name, "category": category, "subcategory": subcategory}


def _compact_cube_health(health):
    """The few health facts an agent acts on; the full autopilot/usage blob stays behind detail='full'."""
    if not isinstance(health, dict):
        return health
    drift = health.get("drift") if isinstance(health.get("drift"), dict) else {}
    sources = health.get("sources") if isinstance(health.get("sources"), dict) else {}
    autopilot = health.get("autopilot") if isinstance(health.get("autopilot"), dict) else {}
    out = {
        "refreshed_at": autopilot.get("refreshed_at") or health.get("refreshed_at"),
        "refresh_mode": autopilot.get("refresh_mode"),
        "source_tables": sources.get("tables"),
        "dirty_sources": sources.get("dirty_count"),
        "drift_rows": drift.get("drift_rows"),
        "recommendation": drift.get("recommendation"),
        "last_error": autopilot.get("last_error"),
    }
    return {k: v for k, v in out.items() if v not in (None, [], "")}


def _compact_cube_description(value: dict, *, sample_rows: int = 3) -> dict:
    """describe_cube summary: keep the grounding an agent needs to query the cube
    (grain, columns, a few sample rows, freshness) and leave the definition SQL and
    the raw health blob to detail='full'. Measured on the pilot: full payloads
    averaged 45k chars and were re-read on every later step of the turn."""
    out = dict(value)
    sql = out.pop("sql", None)
    if sql:
        out["sql_chars"] = len(str(sql))
    if isinstance(out.get("sample"), list) and len(out["sample"]) > sample_rows:
        out["sample"] = out["sample"][:sample_rows]
    if isinstance(out.get("columns"), list):
        out["columns"] = [
            {k: v for k, v in col.items() if v is not None} if isinstance(col, dict) else col
            for col in out["columns"]
        ]
    out["health"] = _compact_cube_health(out.get("health"))
    out["hint"] = (
        "Query it as SELECT ... FROM cubes.<name>. detail='full' returns the definition SQL "
        "and the complete health/autopilot record."
    )
    return out


def tool_describe_cube(name: str, detail: str = "summary") -> dict:
    """A cube's grain, columns, sample rows, freshness (the agent's grounding to query it).
    detail='summary' (default) omits the definition SQL and the raw health blob; detail='full'
    returns everything."""
    # Read the mode up front: the column loop below reuses the name `detail`
    # for per-column dimension detail.
    full = str(detail or "summary").strip().lower() == "full"
    with _conn(read_only=True, role=_session_pg_role()) as c:
        d = c.execute("SELECT rvbbit.describe_cube(%s) AS d", (name,)).fetchone()
        value = d["d"] if (d and d["d"] is not None) else None
        if value:
            dimensions = c.execute(
                "SELECT column_name,data_type,kind,groupable,distinct_est,semantics "
                "FROM rvbbit.cube_dimensions(%s)",
                (name,),
            ).fetchall()
            by_name = {str(row["column_name"]): dict(row) for row in dimensions}
            columns = value.get("columns")
            if isinstance(columns, list):
                enriched = []
                for column in columns:
                    if not isinstance(column, dict):
                        enriched.append(column)
                        continue
                    column_name = str(column.get("name") or "")
                    data_type = str(
                        column.get("type") or column.get("data_type") or ""
                    ).lower()
                    detail = by_name.get(column_name, {})
                    numeric = data_type in _CUBE_NUMERIC_TYPES
                    fallback_kind = _cube_fallback_kind(column_name, data_type)
                    enriched.append({
                        **column,
                        **detail,
                        "kind": detail.get("kind") or fallback_kind,
                        "groupable": detail.get("groupable")
                        if detail.get("groupable") is not None
                        else fallback_kind != "measure",
                        "numeric": numeric,
                    })
                value["columns"] = enriched
    if value is None:
        return {"error": {"code": "CUBE_NOT_FOUND", "message": name}}
    if not full:
        return _compact_cube_description(value)
    return value


def tool_propose_cube(subject: str, seed_tables=None, schema=None) -> dict:
    """Draft a candidate cube for a subject — a documented join over your tables. Returns a DRAFT
    only (name, sql, grain, description, source_tables, join_rationale, confidence + the FK edges
    it reasoned from); NOTHING is created. The draft is LOGGED to an optional proposal queue
    (returns its proposal_id). Call accept_proposal to publish a sound draft immediately, or use
    create_cube when you already have validated SQL; no separate UI approval is required. Pass seed_tables
    (schema.table list) to pin the join, or a schema to scope discovery."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.propose_cube(%s, %s::text[], %s) AS d",
                (subject, seed_tables, schema)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "PROPOSE_FAILED", "message": str(e)}}
        draft = row["d"] if row else None
        if not draft:
            return {"error": {"code": "PROPOSE_FAILED", "message": "no draft"}}
        # self-validate (dry-run) so a hallucinated column never reaches the user
        ok_v, samp, verr = _validate_draft(c, draft["sql"])
        draft = {**draft, "subject": subject, "validated": ok_v}
        if ok_v:
            draft["sample"] = samp
        else:
            draft["validation_error"] = verr
        # Log the draft to the review queue (best-effort: a read-only mirror just skips it).
        try:
            pid = c.execute(
                "SELECT rvbbit.record_proposal('cube', %s::jsonb, 'mcp', 'mcp') AS id",
                (json.dumps(draft),)).fetchone()
            if pid and pid["id"] is not None:
                draft = {**draft, "proposal_id": pid["id"]}
        except Exception:  # noqa: BLE001
            pass
    return draft


def _validate_draft(c, sql) -> tuple:
    """Dry-run a draft SELECT (LIMIT 3): proves it executes against the real schema (catching
    hallucinated columns) and returns a small sample. Autocommit conn → a failure doesn't poison it."""
    try:
        rows = c.execute(f"SELECT to_jsonb(_v) AS r FROM ({sql}) _v LIMIT 3").fetchall()
        return True, [r["r"] for r in rows], None
    except Exception as e:  # noqa: BLE001
        return False, None, str(e)


def tool_propose_metric(subject: str, seed_sources=None, schema=None) -> dict:
    """Draft a candidate metric for a subject — a small, governed aggregation, PREFERRING a cube as
    its source. Returns a DRAFT only (name, sql, grain, description, params, optional KPI check_sql,
    source, confidence) plus validated/sample from a dry-run; NOTHING is created. The draft is LOGGED
    to an optional proposal queue (returns its proposal_id). Call accept_proposal to publish it
    immediately, or use create_metric for already validated SQL; no separate UI approval is required.
    Pass seed_sources (cubes.x / schema.table list) or a schema."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.propose_metric(%s, %s::text[], %s) AS d",
                (subject, seed_sources, schema)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "PROPOSE_FAILED", "message": str(e)}}
        draft = row["d"] if row else None
        if not draft:
            return {"error": {"code": "PROPOSE_FAILED", "message": "no draft"}}
        # self-validate: resolve {param} then dry-run, so a hallucinated column is caught here
        try:
            resolved = c.execute("SELECT rvbbit.preview_metric_sql(%s, %s::jsonb) AS s",
                                 (draft["sql"], json.dumps(draft.get("params") or {}))).fetchone()["s"]
        except Exception:  # noqa: BLE001
            resolved = draft["sql"]
        ok_v, samp, verr = _validate_draft(c, resolved or draft["sql"])
        draft = {**draft, "subject": subject, "validated": ok_v}
        if ok_v:
            draft["sample"] = samp
        else:
            draft["validation_error"] = verr
        try:
            pid = c.execute(
                "SELECT rvbbit.record_proposal('metric', %s::jsonb, 'mcp', 'mcp') AS id",
                (json.dumps(draft),)).fetchone()
            if pid and pid["id"] is not None:
                draft = {**draft, "proposal_id": pid["id"]}
        except Exception:  # noqa: BLE001
            pass
    return draft


# ── proposal queue: see your drafts' fate + iterate on pending ones ──────────

def tool_list_proposals(status=None, kind=None, proposed_by=None, limit=20) -> dict:
    """See the proposal queue — drafts (yours or others') and their fate. Filter by status
    (pending/accepted/rejected/withdrawn), kind (cube/metric), or proposed_by. ACCEPTED proposals
    carry result_name (the object created); REJECTED/WITHDRAWN carry notes (the reason). Use this to
    LEARN from feedback before proposing again — don't re-propose something already rejected, and
    refine_proposal a pending draft instead of submitting a duplicate."""
    lim = max(1, min(int(limit or 20), 100))
    with _conn() as c:
        rows = c.execute(
            "SELECT proposal_id, kind, name, subject, status, confidence, "
            "       created_at::text AS created_at, reviewed_at::text AS reviewed_at, result_name, notes "
            "FROM rvbbit.proposals(%s, %s) "
            "WHERE (%s IS NULL OR proposed_by = %s) LIMIT %s",
            (status, kind, proposed_by, proposed_by, lim)).fetchall()
    return {"proposals": rows}


def tool_get_proposal(proposal_id) -> dict:
    """Full detail of one proposal — sql, grain, source_tables, params, check_sql, join_rationale,
    confidence, status, result_name. Use after list_proposals to inspect a specific draft."""
    with _conn() as c:
        row = c.execute(
            "SELECT proposal_id, kind, status, name, subject, sql, grain, description, source_tables, "
            "       fk_edges, join_rationale, confidence, params, check_sql, proposed_by, proposed_via, "
            "       result_name, notes, created_at::text AS created_at, reviewed_at::text AS reviewed_at "
            "FROM rvbbit.proposals WHERE proposal_id = %s", (proposal_id,)).fetchone()
    return row or {"error": {"code": "PROPOSAL_NOT_FOUND", "message": str(proposal_id)}}


def tool_refine_proposal(proposal_id, name=None, sql=None, grain=None, description=None,
                         params=None, check_sql=None, join_rationale=None, confidence=None,
                         category=None, subcategory=None) -> dict:
    """Edit a PENDING proposal in place after seeing feedback — instead of submitting a duplicate.
    Only the fields you pass change. (Cube SQL is plain; metric SQL may use {param} tokens.) Pass
    category/subcategory to (re)file it under a folder before review."""
    # EVERY arg is cast explicitly: psycopg sends a Python int as the narrowest int type (smallint)
    # and a Python float as double precision — neither implicitly casts to the declared bigint/real,
    # which otherwise yields AmbiguousFunction / UndefinedFunction at resolution time.
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.refine_proposal("
                "%s::bigint, %s::text, %s::text, %s::text, %s::text, %s::jsonb, "
                "%s::text, %s::text, %s::real, %s::text, %s::text) AS r",
                (proposal_id, name, sql, grain, description,
                 json.dumps(params) if params is not None else None,
                 check_sql, join_rationale, confidence, category, subcategory)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "REFINE_FAILED", "message": str(e)}}
    return row["r"] if (row and row["r"] is not None) else {"error": {"code": "REFINE_FAILED", "message": "no result"}}


def tool_withdraw_proposal(proposal_id, reason=None) -> dict:
    """Retract a PENDING proposal you no longer want reviewed (status -> withdrawn)."""
    with _conn() as c:
        try:
            c.execute("SELECT rvbbit.withdraw_proposal(%s, %s)", (proposal_id, reason))
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "WITHDRAW_FAILED", "message": str(e)}}
    return {"status": "withdrawn", "proposal_id": proposal_id}


def _refresh_capability_catalog(c) -> None:
    """Best-effort discovery refresh after defining a governed object."""
    try:
        # Nested transaction becomes a savepoint when the caller is already in
        # its atomic definition transaction, so an optional crawl failure does
        # not poison the object creation itself.
        with c.transaction():
            c.execute("SELECT rvbbit.capability_crawl(false)")
    except Exception:  # noqa: BLE001
        pass


def tool_accept_proposal(proposal_id, name=None, sql=None, grain=None,
                         description=None, enrich=False, metric_contract=None, reuse=None) -> dict:
    """Accept a pending cube/metric proposal directly and publish it now.

    The proposal queue is useful evidence and version history, not an approval
    gate. Optional fields refine the final object at acceptance time.
    """
    with _conn() as c:
        try:
            with c.transaction():
                from semantic_contracts import metric_contract as validate_contract, prove_metric, cube_reuse_check
                proposal = c.execute('SELECT * FROM rvbbit.proposals WHERE proposal_id=%s FOR UPDATE', (proposal_id,)).fetchone()
                if not proposal or proposal['status'] != 'pending':
                    raise ValueError('The proposal is no longer pending')
                final_name, final_sql = name or proposal['name'], sql or proposal['sql']
                if proposal['kind'] == 'metric':
                    contract = validate_contract(metric_contract, proposal.get('params') or {})
                    prove_metric(c, final_sql, proposal.get('params') or {})
                    publication_labels = {'metric_contract': contract, 'time_zone': contract['time_zone']}
                else:
                    review = cube_reuse_check(c, final_name, final_sql, grain or proposal['grain'], description or proposal['description'], reuse)
                    if 'error' in review:
                        return review
                    publication_labels = {'reuse_review': review}
                row = c.execute(
                    "SELECT rvbbit.accept_proposal(%s::bigint,%s,%s,%s,%s,%s) AS result",
                    (proposal_id, name, sql, grain, description, bool(enrich)),
                ).fetchone()
                registry = 'metric_defs' if proposal['kind'] == 'metric' else 'cube_defs'
                c.execute(f"UPDATE rvbbit.{registry} SET labels=coalesce(labels,'{{}}'::jsonb)||%s::jsonb "
                          f"WHERE name=%s AND version=(SELECT max(version) FROM rvbbit.{registry} WHERE name=%s)",
                          (json.dumps(publication_labels),final_name,final_name))
                _refresh_capability_catalog(c)
        except Exception as exc:  # noqa: BLE001
            return {"error": {"code": "ACCEPT_FAILED", "message": str(exc)}}
    return (row or {}).get("result") or {
        "error": {"code": "ACCEPT_FAILED", "message": "no result"}
    }


def tool_create_cube(name: str, sql: str, grain=None, description=None,
                     category=None, labels=None, reuse=None) -> dict:
    """Create and materialize a governed cube directly from validated SELECT SQL.

    This is append-versioned and reversible; use edit_cube for later versions.
    No DataRabbit approval ceremony is required.
    """
    clean_name = str(name or "").strip().lower()
    if not re.fullmatch(r"[a-z_][a-z0-9_]{0,62}", clean_name):
        return {"error": {"code": "INVALID_NAME", "message":
                          "name must be a lowercase SQL identifier up to 63 characters"}}
    owner = _caller()[0] or _SESSION_SUB.get() or "calliope"
    with _conn() as c:
        from semantic_contracts import cube_reuse_check
        try:
            review = cube_reuse_check(c, clean_name, sql, grain, description, reuse)
        except ValueError as exc:
            return {"error": {"code": "CUBE_DEFINITION_REQUIRED", "message": str(exc)}}
        if 'error' in review:
            return review
        labels = dict(labels or {}, reuse_review=review)
        valid, sample, validation_error = _validate_draft(c, sql)
        if not valid:
            return {"error": {"code": "VALIDATION_FAILED", "message": validation_error}}
        try:
            with c.transaction():
                row = c.execute(
                    "SELECT rvbbit.define_cube(%s,%s,%s,%s,%s,NULL,%s,%s::jsonb) AS version",
                    (clean_name, sql, grain, description, owner, category,
                     json.dumps(labels or {}, default=str)),
                ).fetchone()
                _refresh_capability_catalog(c)
        except Exception as exc:  # noqa: BLE001
            return {"error": {"code": "CREATE_CUBE_FAILED", "message": str(exc)}}
    _enrich_cube_async(clean_name)
    return {"status": "created", "cube": clean_name, "version": (row or {}).get("version"),
            "sample": sample, "enrichment": "queued", "reversible": True}


def _enrich_cube_async(name: str) -> None:
    """Fire-and-forget the cube semantic layer (rvbbit.enrich_cube: LLM
    column docs + grain + richer embedding). Without this, cubes created by
    agents or the topology land findable-but-not-understood and the catalog
    quality quietly degrades. Best-effort: enrichment failure never blocks
    or fails the cube itself."""
    def work() -> None:
        try:
            with _conn() as c:
                c.execute("SELECT rvbbit.enrich_cube(%s)", (name,))
        except Exception as exc:  # noqa: BLE001 — enrichment is a bonus pass
            print(f"cube enrichment failed for {name}: {type(exc).__name__}: {exc}",
                  file=sys.stderr)
    threading.Thread(target=work, name=f"cube-enrich-{name}", daemon=True).start()


def tool_create_metric(name: str, sql: str, params=None, grain=None, description=None,
                       labels=None, check_sql=None, materialize=True, metric_contract=None) -> dict:
    """Create a governed scalar metric directly after executing a bounded proof.

    The resolved SQL must return exactly one row. Definitions are append-versioned;
    a first observation is materialized by default. No UI approval is required.
    """
    clean_name = str(name or "").strip().lower()
    if not re.fullmatch(r"[a-z_][a-z0-9_]{0,62}", clean_name):
        return {"error": {"code": "INVALID_NAME", "message":
                          "name must be a lowercase SQL identifier up to 63 characters"}}
    metric_params = params if isinstance(params, dict) else {}
    from semantic_contracts import metric_contract as validate_contract
    try:
        contract = validate_contract(metric_contract or (labels or {}).get('metric_contract'), metric_params)
        if not isinstance(grain, str) or not grain.strip():
            raise ValueError('Define the scalar default grain explicitly.')
    except ValueError as exc:
        return {"error": {"code": "METRIC_DEFINITION_REQUIRED", "message": str(exc)}}
    labels = dict(labels or {}, metric_contract=contract, time_zone=contract['time_zone'])
    owner = _caller()[0] or _SESSION_SUB.get() or "calliope"
    with _conn() as c:
        try:
            from semantic_contracts import prove_metric
            sample = prove_metric(c, sql, metric_params)
            with c.transaction():
                row = c.execute(
                    "SELECT rvbbit.define_metric(%s,%s,%s::jsonb,%s,%s,%s,%s::jsonb,%s) AS version",
                    (clean_name, sql, json.dumps(metric_params, default=str), grain,
                     description, owner, json.dumps(labels or {}, default=str), check_sql),
                ).fetchone()
                _refresh_capability_catalog(c)
        except Exception as exc:  # noqa: BLE001
            return {"error": {"code": "CREATE_METRIC_FAILED", "message": str(exc)}}
        observation_id = None
        observation_error = None
        if bool(materialize):
            try:
                with c.transaction():
                    observed = c.execute(
                        "SELECT rvbbit.materialize_metric(%s,%s::jsonb,now(),NULL,NULL,'mcp-create') AS id",
                        (clean_name, "{}"),
                    ).fetchone()
                    observation_id = (observed or {}).get("id")
            except Exception as exc:  # noqa: BLE001
                # The governed definition remains useful even when a source's
                # current-only history policy prevents an immediate temporal
                # observation. Return the exact limitation rather than rolling
                # back the already-proven, versioned definition.
                observation_error = str(exc)
    result = {"status": "created", "metric": clean_name,
              "version": (row or {}).get("version"), "observation_id": observation_id,
              "sample": sample, "reversible": True}
    if observation_error:
        result["observation_warning"] = observation_error
    return result


# ── direct edits (versioned, so reversible) ──────────────────────────────────

def tool_edit_metric(name, sql=None, grain=None, description=None, params=None,
                     check_sql=None, category=None, subcategory=None, metric_contract=None) -> dict:
    """Edit an existing metric IN PLACE — appends a new version (old versions are kept, so it's
    reversible) that goes LIVE immediately. Only the fields you pass change. check_sql: omit to keep
    the current check, pass "" to remove it. Use this to fix/improve a metric you (or someone) defined."""
    with _conn() as c:
        try:
            updated_labels = None
            if metric_contract is not None or sql is not None or grain is not None or params is not None:
                from semantic_contracts import metric_contract as validate_contract, prove_metric
                current = c.execute('SELECT sql,params,labels FROM rvbbit.metric_defs WHERE name=%s ORDER BY version DESC LIMIT 1', (name,)).fetchone()
                if not current:
                    raise ValueError('No such metric')
                defaults = params if params is not None else current['params'] or {}
                contract = validate_contract(metric_contract, defaults)
                prove_metric(c, sql or current['sql'], defaults)
                updated_labels = dict(current['labels'] or {}, metric_contract=contract, time_zone=contract['time_zone'])
            row = c.execute(
                "SELECT rvbbit.revise_metric(%s, p_sql=>%s, p_grain=>%s, p_description=>%s, "
                "p_params=>%s::jsonb, p_check_sql=>%s, p_category=>%s, p_subcategory=>%s, p_labels=>%s::jsonb) AS v",
                (name, sql, grain, description,
                 json.dumps(params) if params is not None else None,
                 check_sql, category, subcategory, json.dumps(updated_labels) if updated_labels is not None else None)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "EDIT_FAILED", "message": str(e)}}
    return {"metric": name, "version": row["v"] if row else None}


def tool_edit_cube(name, sql, grain=None, description=None, category=None, subcategory=None) -> dict:
    """Edit an existing cube's DEFINITION in place — appends a new version (revert via the prior
    version) that goes LIVE immediately. Shape-aware: a column change rebuilds the cube table, a
    filter-only change preserves its AS-OF history. sql is required (the full new SELECT)."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.redefine_cube(%s, %s, p_grain=>%s, p_description=>%s, "
                "p_category=>%s, p_subcategory=>%s) AS v",
                (name, sql, grain, description, category, subcategory)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "EDIT_FAILED", "message": str(e)}}
    # A redefinition can change columns; re-draft the semantic layer so
    # describe_cube and the embedding track the new shape.
    _enrich_cube_async(str(name))
    return {"cube": name, "version": row["v"] if row else None, "enrichment": "queued"}


# ── hosted acceleration stewardship: typed evidence + reversible actions ────

def _acceleration_steward_row(row) -> dict:
    return dict(row) if row else {}


def _acceleration_steward_json_object(value, *, label: str) -> dict:
    """Keep the receipt ledger object-shaped without discarding agent evidence.

    MCP clients are not perfectly consistent about structured arguments: a
    model may send an object, a JSON-encoded object, or a useful list/scalar.
    The ledger intentionally requires JSON objects so its System Learning
    projection remains queryable. Normalize at the tool boundary instead of
    rejecting a sound, reversible action after its evidence was collected.
    """
    if value is None:
        return {}
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return {}
        try:
            decoded = json.loads(stripped)
        except (TypeError, ValueError, json.JSONDecodeError):
            decoded = stripped
        if isinstance(decoded, dict):
            return decoded
        value = decoded
    if isinstance(value, (list, tuple)):
        return {"items": list(value)}
    return {label: value}


def _acceleration_steward_state(c, table: str) -> dict:
    row = c.execute(
        "SELECT cls.oid AS table_oid,cls.oid::regclass::text AS table_name,"
        "ns.nspname AS schema_name,cls.relname,cls.relkind,cls.relrowsecurity,"
        "pg_total_relation_size(cls.oid) AS table_bytes,"
        "to_jsonb(tab) AS registry,to_jsonb(fresh) AS freshness,"
        "to_jsonb(policy) AS policy,"
        "coalesce((SELECT jsonb_agg(to_jsonb(runtime) ORDER BY runtime.lane) "
        "          FROM rvbbit.accel_table_runtime_profile runtime "
        "         WHERE runtime.table_oid=cls.oid),'[]'::jsonb) AS runtime_profiles,"
        "coalesce((SELECT jsonb_agg(to_jsonb(op) ORDER BY op.started_at DESC) "
        "          FROM (SELECT * FROM rvbbit.acceleration_operations "
        "                 WHERE table_oid=cls.oid ORDER BY started_at DESC LIMIT 12) op),"
        "         '[]'::jsonb) AS recent_operations "
        "FROM pg_catalog.pg_class cls "
        "JOIN pg_catalog.pg_namespace ns ON ns.oid=cls.relnamespace "
        "LEFT JOIN rvbbit.tables tab ON tab.table_oid=cls.oid "
        "LEFT JOIN rvbbit.accel_freshness fresh ON fresh.table_oid=cls.oid "
        "LEFT JOIN rvbbit.accel_policy_effective policy ON policy.table_oid=cls.oid "
        "WHERE cls.oid=%s::regclass",
        (table,),
    ).fetchone()
    if not row:
        raise LookupError(f"Table {table} does not exist")
    state = _acceleration_steward_row(row)
    state["mirrors"] = _acceleration_steward_mirrors(c, state)
    return state


def _acceleration_steward_mirrors(c, state: dict) -> list[dict]:
    """Return hosted mirror cadence when that optional control plane exists."""
    installed = c.execute(
        "SELECT to_regclass('rvbbit.mirror_tables') IS NOT NULL "
        "AND to_regclass('rvbbit.mirror_jobs') IS NOT NULL AS installed"
    ).fetchone()
    if not installed or not installed.get("installed"):
        return []
    rows = c.execute(
        "SELECT job.job_name,mirror.load_mode,job.schedule_seconds,job.last_run_at,"
        "mirror.enabled,mirror.primary_key,mirror.cursor_column "
        "FROM rvbbit.mirror_tables mirror JOIN rvbbit.mirror_jobs job USING (job_name) "
        "WHERE job.destination_schema=%s AND mirror.destination_table=%s",
        (state.get("schema_name"), state.get("relname")),
    ).fetchall()
    return [_acceleration_steward_row(row) for row in rows]


def _acceleration_steward_validate_table(state: dict) -> None:
    schema = str(state.get("schema_name") or "")
    if schema in {"rvbbit", "pg_catalog", "information_schema", "pg_toast"} or schema.startswith(("pg_", "cubes")):
        raise ValueError("Atalanta (Acceleration Steward) may act only on local user or mirrored tables")
    if str(state.get("relkind") or "") not in {"r", "p"}:
        raise ValueError("Acceleration trials require an ordinary or partitioned local table")
    if bool(state.get("relrowsecurity")):
        raise ValueError("Atalanta (Acceleration Steward) does not autonomously enroll RLS tables")


def _acceleration_steward_receipt(
    c,
    *,
    table_state: dict,
    action: str,
    status: str,
    rationale: str,
    evidence=None,
    state_before=None,
    state_after=None,
    trial_days=None,
    outcome=None,
) -> dict:
    evidence_object = _acceleration_steward_json_object(evidence, label="value")
    before_object = _acceleration_steward_json_object(state_before, label="state")
    after_object = _acceleration_steward_json_object(state_after, label="state")
    outcome_object = _acceleration_steward_json_object(outcome, label="value")
    row = c.execute(
        "INSERT INTO rvbbit.acceleration_steward_decisions "
        "(table_oid,table_name,action,status,rationale,evidence,state_before,state_after,"
        " trial_started_at,trial_expires_at,outcome_at,outcome,actor) "
        "VALUES (%s::oid,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s::jsonb,"
        " CASE WHEN %s::int IS NULL THEN NULL ELSE clock_timestamp() END,"
        " CASE WHEN %s::int IS NULL THEN NULL ELSE clock_timestamp()+make_interval(days=>%s::int) END,"
        " CASE WHEN %s::jsonb='{}'::jsonb THEN NULL ELSE clock_timestamp() END,"
        " %s::jsonb,%s) RETURNING *",
        (
            table_state.get("table_oid"), table_state.get("table_name"), action, status,
            str(rationale or "").strip()[:8_000], json.dumps(evidence_object, default=str),
            json.dumps(before_object, default=str), json.dumps(after_object, default=str),
            trial_days, trial_days, trial_days,
            json.dumps(outcome_object, default=str), json.dumps(outcome_object, default=str),
            _caller()[0] or _SESSION_SUB.get() or "calliope-warehouse-steward",
        ),
    ).fetchone()
    return _acceleration_steward_row(row)


def tool_acceleration_steward_snapshot(limit: int = 12) -> dict:
    """Return the bounded canonical packet for acceleration judgment.

    This refreshes the autopilot's read-based classification (which tables
    clients read, on how many of the last 7 days), then combines its
    candidates with mirror load mode/cadence, freshness, policy, runtime cost,
    recent operations, derived-layout recommendations, open trials, and prior
    receipts. It never enables or rebuilds a table.
    """
    bounded = max(5, min(int(limit or 12), 40))
    with _conn() as c:
        observer = c.execute(
            "SELECT rvbbit.accel_autopilot_observe('warehouse-steward') AS result"
        ).fetchone()
        candidates = c.execute(
            "SELECT candidate.table_name,candidate.status,"
            "candidate.table_oid,candidate.reasons,candidate.read_days,candidate.last_read_at,"
            "candidate.row_estimate,"
            "candidate.table_bytes,candidate.registered,candidate.acceleration_enabled,"
            "to_jsonb(fresh) AS freshness,to_jsonb(policy) AS policy,"
            "coalesce((SELECT jsonb_agg(to_jsonb(runtime) ORDER BY runtime.lane) "
            "          FROM rvbbit.accel_table_runtime_profile runtime "
            "         WHERE runtime.table_oid=candidate.table_oid),'[]'::jsonb) AS runtime_profiles "
            "FROM rvbbit.accel_autopilot_candidates candidate "
            "LEFT JOIN rvbbit.accel_freshness fresh ON fresh.table_oid=candidate.table_oid "
            "LEFT JOIN rvbbit.accel_policy_effective policy ON policy.table_oid=candidate.table_oid "
            "ORDER BY (candidate.status='ready') DESC,candidate.read_days DESC,"
            "candidate.last_read_at DESC NULLS LAST LIMIT %s",
            (bounded,),
        ).fetchall()
        candidate_rows = [_acceleration_steward_row(row) for row in candidates]
        for candidate in candidate_rows:
            table_state = c.execute(
                "SELECT ns.nspname AS schema_name,cls.relname "
                "FROM pg_catalog.pg_class cls JOIN pg_catalog.pg_namespace ns "
                "ON ns.oid=cls.relnamespace WHERE cls.oid=%s::oid",
                (candidate.get("table_oid"),),
            ).fetchone() or {}
            candidate["mirrors"] = _acceleration_steward_mirrors(c, table_state)
        trials = c.execute(
            "SELECT trial.id,trial.table_oid,trial.table_name,trial.action,trial.status,"
            "trial.rationale,trial.evidence,trial.trial_started_at,trial.trial_expires_at,"
            "trial.outcome_at,trial.outcome,trial.decided_at,trial.review_due,"
            "to_jsonb(fresh) AS current_freshness,"
            "to_jsonb(policy) AS current_policy "
            "FROM rvbbit.acceleration_steward_open_trials trial "
            "LEFT JOIN rvbbit.accel_freshness fresh ON fresh.table_oid=trial.table_oid "
            "LEFT JOIN rvbbit.accel_policy_effective policy ON policy.table_oid=trial.table_oid "
            "ORDER BY trial.review_due DESC,trial.trial_expires_at LIMIT %s",
            (bounded,),
        ).fetchall()
        layouts = c.execute(
            "SELECT * FROM rvbbit.workload_layout_recommendation_status "
            "WHERE status='candidate' ORDER BY score DESC,weighted_ms DESC LIMIT %s",
            (bounded,),
        ).fetchall()
        decisions = c.execute(
            "SELECT id,table_oid,table_name,action,status,rationale,evidence,"
            "trial_started_at,trial_expires_at,outcome_at,outcome,actor,decided_at "
            "FROM rvbbit.acceleration_steward_decisions "
            "ORDER BY decided_at DESC LIMIT %s",
            (bounded,),
        ).fetchall()
        learning = c.execute(
            "SELECT object_type,items,last_seen_at FROM rvbbit.system_learning_item_summary "
            "ORDER BY items DESC,object_type"
        ).fetchall()
    return {
        "observer": _acceleration_steward_row(observer).get("result"),
        "candidates": candidate_rows,
        "open_trials": [_acceleration_steward_row(row) for row in trials],
        "layout_candidates": [_acceleration_steward_row(row) for row in layouts],
        "recent_decisions": [_acceleration_steward_row(row) for row in decisions],
        "system_learning": [_acceleration_steward_row(row) for row in learning],
        "contract": {
            "heap_authoritative": True,
            "vortex_automatic": True,
            "mutations_are_reversible": True,
            "candidate_evidence_is_select_backed": True,
        },
    }


def tool_start_acceleration_trial(
    table: str,
    rationale: str,
    evidence: dict | None = None,
    trial_days: int = 7,
    freshness_target_seconds: int = 900,
    min_interval_seconds: int = 300,
    daily_refresh_budget: int = 24,
    full_rebuild_drift_ratio: float = 0.5,
) -> dict:
    """Start a reversible acceleration trial without waiting for UI approval.

    Registration and policy activation are immediate; the five-slot tick fleet
    performs the baseline/freshness work asynchronously. A receipt freezes the
    pre-trial evidence and review date.
    """
    days = max(2, min(int(trial_days or 7), 30))
    target = max(60, min(int(freshness_target_seconds or 900), 2_678_400))
    interval = max(30, min(int(min_interval_seconds or 300), target))
    budget = max(1, min(int(daily_refresh_budget or 24), 1_440))
    drift = max(0.01, min(float(full_rebuild_drift_ratio or 0.5), 1.0))
    with _conn() as c:
        with c.transaction():
            before = _acceleration_steward_state(c, table)
            _acceleration_steward_validate_table(before)
            existing = c.execute(
                "SELECT id FROM rvbbit.acceleration_steward_open_trials "
                "WHERE table_oid=%s::oid ORDER BY id DESC LIMIT 1",
                (before["table_oid"],),
            ).fetchone()
            if existing:
                raise ValueError(f"{before['table_name']} already has an open acceleration trial")
            c.execute("SELECT rvbbit.enable_table(%s::regclass)", (before["table_name"],))
            policy = c.execute(
                "SELECT rvbbit.set_accel_policy(%s::regclass,strategy=>'target',"
                "freshness_target_secs=>%s,min_interval_secs=>%s,daily_refresh_budget=>%s,"
                "full_rebuild_drift_ratio=>%s,lance_separate=>true,active=>true,"
                "note=>%s) AS result",
                (
                    before["table_name"], target, interval, budget, drift,
                    f"Atalanta acceleration {days}-day reversible trial",
                ),
            ).fetchone()
            after = _acceleration_steward_state(c, before["table_name"])
            receipt = _acceleration_steward_receipt(
                c, table_state=after, action="enroll_trial", status="observing",
                rationale=rationale, evidence=evidence, state_before=before,
                state_after=after, trial_days=days,
            )
    return {"status": "trial_started", "table": after["table_name"], "policy": _acceleration_steward_row(policy).get("result"), "receipt": receipt}


def tool_review_acceleration_trial(
    table: str,
    decision: str,
    rationale: str,
    outcome: dict | None = None,
    freshness_target_seconds: int | None = None,
    min_interval_seconds: int | None = None,
    daily_refresh_budget: int | None = None,
    extend_days: int = 7,
) -> dict:
    """Retain, adjust, or retire one measured trial and record its outcome."""
    verdict = str(decision or "").strip().lower()
    outcome_object = _acceleration_steward_json_object(outcome, label="value")
    if verdict not in {"retain", "adjust", "retire"}:
        raise ValueError("decision must be retain, adjust, or retire")
    with _conn() as c:
        with c.transaction():
            before = _acceleration_steward_state(c, table)
            trial = c.execute(
                "SELECT decision.* FROM rvbbit.acceleration_steward_decisions decision "
                "WHERE decision.action='enroll_trial' AND decision.status='observing' "
                "AND decision.table_oid=%s::oid "
                "AND NOT EXISTS (SELECT 1 FROM rvbbit.acceleration_steward_decisions later "
                " WHERE later.table_oid=decision.table_oid AND later.decided_at>decision.decided_at "
                " AND later.action IN ('retain','retire')) "
                "ORDER BY decision.id DESC LIMIT 1 FOR UPDATE",
                (before["table_oid"],),
            ).fetchone()
            if not trial:
                raise LookupError(f"{before['table_name']} has no open acceleration trial")
            if verdict == "retire":
                result = c.execute(
                    "SELECT rvbbit.retire_acceleration(%s::regclass) AS result",
                    (before["table_name"],),
                ).fetchone()
                trial_status = "reversed"
            else:
                current = before.get("policy") or {}
                target = int(freshness_target_seconds or current.get("freshness_target_secs") or 900)
                interval = int(min_interval_seconds or current.get("min_interval_secs") or 300)
                budget = int(daily_refresh_budget or current.get("daily_refresh_budget") or 24)
                result = c.execute(
                    "SELECT rvbbit.set_accel_policy(%s::regclass,strategy=>'target',"
                    "freshness_target_secs=>%s,min_interval_secs=>%s,daily_refresh_budget=>%s,"
                    "full_rebuild_drift_ratio=>coalesce(%s::double precision,0.5),"
                    "lance_separate=>true,active=>true,note=>%s) AS result",
                    (
                        before["table_name"], max(60, target), max(30, interval), max(1, budget),
                        current.get("full_rebuild_drift_ratio"),
                        "Atalanta retained acceleration trial" if verdict == "retain" else "Atalanta adjusted acceleration trial",
                    ),
                ).fetchone()
                trial_status = "successful" if verdict == "retain" else "observing"
            after = _acceleration_steward_state(c, before["table_name"])
            c.execute(
                "UPDATE rvbbit.acceleration_steward_decisions SET status=%s,"
                "outcome_at=clock_timestamp(),outcome=%s::jsonb,"
                "trial_expires_at=CASE WHEN %s='adjust' THEN clock_timestamp()+make_interval(days=>%s) ELSE trial_expires_at END "
                "WHERE id=%s",
                (trial_status, json.dumps(outcome_object, default=str), verdict, max(2, min(int(extend_days or 7), 30)), trial["id"]),
            )
            receipt = _acceleration_steward_receipt(
                c, table_state=after,
                action="adjust_policy" if verdict == "adjust" else verdict,
                status=trial_status, rationale=rationale, evidence=outcome_object,
                state_before=before, state_after=after, outcome=outcome_object,
            )
    return {"status": verdict, "table": after["table_name"], "result": _acceleration_steward_row(result).get("result"), "receipt": receipt}


def tool_decide_workload_layout(
    table: str,
    layout_kind: str,
    column_name: str,
    decision: str,
    rationale: str,
    evidence: dict | None = None,
) -> dict:
    """Accept or reject one learned cluster/Hive layout recommendation."""
    kind = str(layout_kind or "").strip().lower()
    verdict = str(decision or "").strip().lower()
    if kind not in {"cluster", "hive"}:
        raise ValueError("layout_kind must be cluster or hive")
    if verdict not in {"accept", "reject"}:
        raise ValueError("decision must be accept or reject")
    with _conn() as c:
        with c.transaction():
            before = _acceleration_steward_state(c, table)
            _acceleration_steward_validate_table(before)
            recommendation = c.execute(
                "SELECT * FROM rvbbit.workload_layout_recommendations "
                "WHERE table_oid=%s::oid AND layout_kind=%s AND column_name=%s",
                (before["table_oid"], kind, column_name),
            ).fetchone()
            if not recommendation:
                raise LookupError("That workload layout recommendation does not exist")
            function_name = "accept_workload_layout" if verdict == "accept" else "reject_workload_layout"
            result = c.execute(
                f"SELECT rvbbit.{function_name}(%s::oid,%s,%s) AS result",
                (before["table_oid"], kind, column_name),
            ).fetchone()
            after = _acceleration_steward_state(c, before["table_name"])
            combined_evidence = {"recommendation": _acceleration_steward_row(recommendation), **(evidence or {})}
            receipt = _acceleration_steward_receipt(
                c, table_state=after,
                action="accept_layout" if verdict == "accept" else "reject_layout",
                status="applied", rationale=rationale, evidence=combined_evidence,
                state_before=before, state_after=after,
            )
    return {"status": verdict + "ed", "table": after["table_name"], "layout_kind": kind, "column": column_name, "result": _acceleration_steward_row(result).get("result"), "receipt": receipt}


def tool_record_acceleration_observation(
    table: str,
    rationale: str,
    evidence: dict | None = None,
    error: bool = False,
) -> dict:
    """Persist a bounded no-change or error conclusion for later learning."""
    with _conn() as c:
        with c.transaction():
            requested = str(table or "").strip()
            if requested.lower() in {"", "warehouse", "all"}:
                state = {"table_oid": None, "table_name": "warehouse"}
            else:
                state = _acceleration_steward_state(c, requested)
            receipt = _acceleration_steward_receipt(
                c, table_state=state, action="error" if error else "no_change",
                status="failed" if error else "recorded", rationale=rationale,
                evidence=evidence, state_before=state, state_after=state,
            )
    return {"status": "recorded", "table": state["table_name"], "receipt": receipt}


# ── persistent specialist findings: autonomous feedback into System Learning ─

_SPECIALIST_FINDING_KINDS = {
    "observation", "proposal", "warning", "review", "action", "no_change",
}
_SPECIALIST_FINDING_STATUSES = {
    "open", "monitoring", "applied", "resolved", "dismissed",
}


def _specialist_finding_json(row) -> dict:
    item = _acceleration_steward_row(row)
    for key in ("id", "source_run_id", "specialist_id"):
        if item.get(key) is not None:
            item[key] = str(item[key])
    return item


def tool_record_specialist_finding(
    specialist_key: str,
    subject: str,
    summary: str,
    finding_kind: str = "observation",
    status: str = "open",
    evidence: dict | list | str | None = None,
    recommendation: str | None = None,
    dedupe_key: str | None = None,
    next_review_at: str | None = None,
) -> dict:
    """Create or update one compact, non-secret specialist finding.

    Persistent Hermes memory is private working context. This ledger is the
    durable shared feedback surface for material observations, proposals,
    warnings, reviews, and actions from delegated or autonomous specialists.
    A stable dedupe_key updates an existing open/monitoring case rather than
    producing one finding per scheduled run. Evidence must never contain
    credentials, tokens, remote DSNs, or hidden reasoning.
    """
    clean_key = str(specialist_key or "").strip().lower()
    clean_subject = re.sub(r"\s+", " ", str(subject or "")).strip()[:500]
    clean_summary = str(summary or "").strip()[:12_000]
    kind = str(finding_kind or "observation").strip().lower()
    clean_status = str(status or "open").strip().lower()
    if not clean_subject or not clean_summary:
        raise ValueError("subject and summary are required")
    if kind not in _SPECIALIST_FINDING_KINDS:
        raise ValueError("unsupported finding_kind")
    if clean_status not in _SPECIALIST_FINDING_STATUSES:
        raise ValueError("unsupported finding status")
    clean_dedupe = re.sub(r"[^a-zA-Z0-9_.:/-]+", "-", str(dedupe_key or "").strip())[:240] or None
    evidence_object = _acceleration_steward_json_object(evidence, label="value")
    envelope = _hermes_mcp_envelope() or {}
    hermes_session_id = str(envelope.get("session_id") or "").strip()
    actor = _caller()[0] or f"calliope-specialist:{clean_key}"
    with _conn() as c:
        with c.transaction():
            specialist = _active_specialist(
                c, clean_key, columns="id,specialist_key,display_name"
            )
            if not specialist:
                raise ValueError(f"Unknown or inactive Calliope specialist: {clean_key}")
            clean_key = str(specialist["specialist_key"])
            source_run = None
            if hermes_session_id:
                source_run = c.execute(
                    "SELECT id FROM rvbbit.calliope_specialist_runs "
                    "WHERE hermes_session_id=%s ORDER BY created_at DESC LIMIT 1",
                    (hermes_session_id,),
                ).fetchone()
            row = c.execute(
                "INSERT INTO rvbbit.calliope_specialist_findings "
                "(specialist_id,source_run_id,subject,finding_kind,status,summary,evidence,"
                " recommendation,dedupe_key,next_review_at,resolved_at,actor) "
                "VALUES (%s::uuid,%s::uuid,%s,%s,%s,%s,%s::jsonb,%s,%s,%s::timestamptz,"
                " CASE WHEN %s IN ('resolved','dismissed') THEN clock_timestamp() ELSE NULL END,%s) "
                "ON CONFLICT (specialist_id,dedupe_key) "
                "WHERE dedupe_key IS NOT NULL AND status IN ('open','monitoring') "
                "DO UPDATE SET source_run_id=coalesce(EXCLUDED.source_run_id,"
                " rvbbit.calliope_specialist_findings.source_run_id),"
                "subject=EXCLUDED.subject,finding_kind=EXCLUDED.finding_kind,status=EXCLUDED.status,"
                "summary=EXCLUDED.summary,evidence=EXCLUDED.evidence,"
                "recommendation=EXCLUDED.recommendation,next_review_at=EXCLUDED.next_review_at,"
                "resolved_at=EXCLUDED.resolved_at,actor=EXCLUDED.actor,updated_at=clock_timestamp() "
                "RETURNING *",
                (
                    str(specialist["id"]),
                    str(source_run["id"]) if source_run else None,
                    clean_subject, kind, clean_status, clean_summary,
                    json.dumps(evidence_object, default=str),
                    str(recommendation or "").strip()[:8_000] or None,
                    clean_dedupe, next_review_at, clean_status, actor,
                ),
            ).fetchone()
    return {
        "status": "recorded",
        "specialist": {
            "key": str(specialist["specialist_key"]),
            "name": str(specialist["display_name"]),
        },
        "finding": _specialist_finding_json(row),
        "system_learning": True,
    }


def tool_list_specialist_findings(
    specialist_key: str | None = None,
    status: str | None = "open",
    limit: int = 40,
) -> dict:
    """List compact shared findings from persistent Calliope specialists."""
    clean_key = str(specialist_key or "").strip().lower() or None
    clean_status = str(status or "").strip().lower() or None
    if clean_status and clean_status not in _SPECIALIST_FINDING_STATUSES:
        raise ValueError("unsupported finding status")
    bounded = max(1, min(int(limit or 40), 200))
    with _conn() as c:
        rows = c.execute(
            "SELECT finding.*,specialist.specialist_key,specialist.display_name "
            "FROM rvbbit.calliope_specialist_findings finding "
            "JOIN rvbbit.calliope_specialists specialist ON specialist.id=finding.specialist_id "
            "WHERE (%s::text IS NULL OR specialist.specialist_key=%s) "
            "AND (%s::text IS NULL OR finding.status=%s) "
            "ORDER BY finding.updated_at DESC LIMIT %s",
            (clean_key, clean_key, clean_status, clean_status, bounded),
        ).fetchall()
    return {"findings": [_specialist_finding_json(row) for row in rows]}


def tool_resolve_specialist_finding(
    finding_id: int,
    resolution: str,
    status: str = "resolved",
) -> dict:
    """Resolve or dismiss one specialist finding with a durable explanation."""
    clean_status = str(status or "resolved").strip().lower()
    if clean_status not in {"resolved", "dismissed"}:
        raise ValueError("status must be resolved or dismissed")
    clean_resolution = str(resolution or "").strip()[:8_000]
    if not clean_resolution:
        raise ValueError("resolution is required")
    with _conn() as c:
        row = c.execute(
            "UPDATE rvbbit.calliope_specialist_findings SET status=%s,resolution=%s,"
            "resolved_at=clock_timestamp(),updated_at=clock_timestamp(),actor=%s "
            "WHERE id=%s RETURNING *",
            (clean_status, clean_resolution, _caller()[0] or "calliope", int(finding_id)),
        ).fetchone()
    if not row:
        raise LookupError("specialist finding does not exist")
    return {"status": clean_status, "finding": _specialist_finding_json(row)}


def tool_metric(name: str, params=None, as_of=None, def_as_of=None, group_by=None) -> dict:
    """A blessed, governed scalar number — bitemporal (as_of = data-time, def_as_of = def-time). Pass
    group_by (a list of cube dimension columns) to slice a DIMENSIONAL metric — one defined over a
    cube (labels.cube_source) — into a breakdown row per group (e.g. group_by=['stage_name']). The
    metric's measures are reused verbatim; dimensions are validated against the cube's real columns.
    Call metric_dimensions(name) to discover which columns are sliceable."""
    params = params or {}
    dims = [d for d in (group_by or []) if d]
    with _conn() as c:
        if as_of:
            c.execute("SET rvbbit.as_of_timestamp = %s", (str(as_of),))
        try:
            if dims:
                rows = c.execute("SELECT rvbbit.metric_by(%s, %s::text[], %s::jsonb) AS m",
                                 (name, dims, json.dumps(params))).fetchall()
            else:
                rows = c.execute(
                    "SELECT rvbbit.metric_scalar(%s, %s::jsonb, coalesce(%s::timestamptz, now()), %s::timestamptz) AS m",
                    (name, json.dumps(params), def_as_of, as_of)).fetchall()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "METRIC_FAILED", "message": str(e)}}
    vals = [r["m"] for r in rows]
    out = {"name": name, "result": vals[0] if (len(vals) == 1 and not dims) else vals,
           "params": params, "data_as_of": as_of, "def_as_of": def_as_of}
    if dims:
        out["group_by"] = dims
    out.update(_metric_provenance(name))
    return out


def _metric_provenance(name: str) -> dict:
    """Where a metric came from, when that changes how to say it. An implied metric — one the
    meaning layer registered from a dossier candidate on its canonical source, which no person
    has confirmed — carries status, source and a note; a governed metric adds nothing."""
    try:
        with _conn() as c:
            row = c.execute("SELECT labels FROM rvbbit.metric_catalog WHERE name = %s", (name,)).fetchone()
    except Exception:  # noqa: BLE001 — older database or no catalog: say nothing
        return {}
    labels = row.get("labels") if isinstance(row, dict) else None
    if isinstance(labels, str):
        try:
            labels = json.loads(labels)
        except ValueError:
            labels = None
    if not isinstance(labels, dict) or labels.get("origin") != "meaning":
        return {}
    status = str(labels.get("status") or "governed")
    out: dict = {"status": status, "origin": "meaning"}
    sources = labels.get("source_objects") if isinstance(labels.get("source_objects"), list) else []
    if sources:
        out["source"] = sources[0]
    if labels.get("subject_name"):
        out["subject"] = labels["subject_name"]
    if status == "implied":
        out["note"] = (f"implied metric: the meaning layer registered it from {sources[0] if sources else 'its source'}"
                       + (f" as {labels['formula']}" if labels.get("formula") else "")
                       + "; no person has confirmed it. Say so once when the number matters; using it counts toward promotion.")
    return out


def tool_metric_dimensions(name: str) -> dict:
    """The cube columns a DIMENSIONAL metric can be sliced by (empty unless it declares labels.cube_source).
    Each entry: column, type, kind (dimension/time/key/measure), groupable. Feed groupable columns to
    metric(name, group_by=[...]) for a breakdown."""
    with _conn() as c:
        rows = c.execute(
            "SELECT column_name, data_type, kind, groupable, distinct_est, semantics "
            "FROM rvbbit.metric_dimensions(%s)", (name,)).fetchall()
    return {"metric": name, "dimensions": rows,
            "groupable": [r["column_name"] for r in rows if r["groupable"]]}


# ── monitoring surface: snapshot, history, breaches, lineage ─────────────────

def tool_materialize_metric(name: str, params=None, as_of=None, def_as_of=None) -> dict:
    """Snapshot a metric NOW into the durable observation log (value + KPI verdict at this instant) —
    the basis for trend history and breach monitoring. Returns the observation id."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.materialize_metric(%s, %s::jsonb, coalesce(%s::timestamptz, now()), "
                "%s::timestamptz, NULL, 'mcp') AS id",
                (name, json.dumps(params or {}), def_as_of, as_of)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "MATERIALIZE_FAILED", "message": str(e)}}
    return {"metric": name, "observation_id": row["id"] if row else None}


def tool_metric_history(name: str, limit: int = 50) -> dict:
    """The durable observation series for a metric (newest first): value, KPI verdict/status, the
    data-time it was taken at, and how it was triggered. Turns a definition into a trend."""
    with _conn() as c:
        rows = c.execute(
            "SELECT observation_id, metric_version, value, verdict, status, trigger, "
            "       data_as_of::text AS data_as_of, observed_at::text AS observed_at "
            "FROM rvbbit.metric_history(%s, %s)", (name, max(1, min(int(limit or 50), 500)))).fetchall()
    return {"metric": name, "observations": rows}


def tool_breaching_kpis() -> dict:
    """Which KPIs are FAILING their target right now — the latest observation per metric where the
    check verdict is false. A monitoring dashboard in one call (materialize metrics first to populate)."""
    with _conn() as c:
        rows = c.execute(
            "SELECT metric_name, status, value, verdict, observed_at::text AS observed_at "
            "FROM rvbbit.breaching_kpis()").fetchall()
    return {"breaching": rows, "count": len(rows)}


def tool_metric_lineage(name: str) -> dict:
    """The base tables a metric reads (for impact analysis) — resolved from its SQL via the planner.
    The metric-side mirror of dashboard_dependents."""
    with _conn() as c:
        row = c.execute("SELECT rvbbit.metric_lineage(%s) AS t", (name,)).fetchone()
    return {"metric": name, "source_tables": (row["t"] if row else None) or []}


# ── alerts: observe + operate + author-conditions (T0+T1) ────────────────────
# Read + control over the durable alert engine (edge-triggered condition->action rules, pg_cron
# sweep+worker). v1 lets an agent see what's firing, operate the controls (enable/mute/cadence/
# kill-switch, manual sweep+worker), and DRY-RUN conditions. Authoring whole rules (define_alert) is
# deferred: open-ended actions (mcp_call/flow) go through the human bless path in the lens, where the
# action form + manifest validation lives.

def tool_list_alerts(category=None, enabled=None, muted=None, tier=None, search=None, limit=50) -> dict:
    """Alert rules with live vitals: each rule's condition/action shape, on/off + mute + cadence tier,
    and current breach/entity/pending counts + last-fired. The agent's entry point for "what's firing
    and why". Filters: category, enabled (bool), muted (bool), tier (fast|normal|slow), search
    (name/description). Also returns the global alerts_enabled kill-switch state."""
    lim = max(1, min(int(limit or 50), 500))
    with _conn() as c:
        rows = c.execute(
            "SELECT c.name, c.condition_spec, c.fire_policy, c.action_spec, c.cardinality, c.fan_out_cap, "
            "c.description, c.enabled, c.muted, c.cadence_tier, c.category, c.subcategory, "
            "c.created_at::text AS created_at, "
            "(SELECT count(*) FROM rvbbit.alert_state s WHERE s.rule_name=c.name AND s.last_status='fail') AS breaching, "
            "(SELECT count(*) FROM rvbbit.alert_state s WHERE s.rule_name=c.name) AS entities, "
            "(SELECT count(*) FROM rvbbit.alert_queue q WHERE q.rule_name=c.name AND q.status='pending') AS pending, "
            "(SELECT max(s.last_fired_at)::text FROM rvbbit.alert_state s WHERE s.rule_name=c.name) AS last_fired "
            "FROM rvbbit.alert_catalog c "
            "WHERE (%s::text IS NULL OR c.category=%s::text) "
            "  AND (%s::bool IS NULL OR c.enabled=%s::bool) "
            "  AND (%s::bool IS NULL OR c.muted=%s::bool) "
            "  AND (%s::text IS NULL OR c.cadence_tier=%s::text) "
            "  AND (%s::text IS NULL OR c.name ILIKE '%%'||%s::text||'%%' OR c.description ILIKE '%%'||%s::text||'%%') "
            "ORDER BY c.name LIMIT %s",
            (category, category, enabled, enabled, muted, muted, tier, tier, search, search, search, lim)).fetchall()
        on = c.execute("SELECT rvbbit.alerts_enabled() AS on").fetchone()["on"]
    return {"alerts": rows, "alerts_enabled": on, "count": len(rows)}


def tool_get_alert(name) -> dict:
    """One alert rule in full: latest-version condition_spec/action_spec/fire_policy, cardinality,
    fan-out cap, control state (enabled/muted/cadence), category, version history, a live state
    summary (breaching/entities/pending, last fired), and its most recent firing events."""
    with _conn() as c:
        d = c.execute(
            "SELECT name, version, condition_spec, fire_policy, action_spec, cardinality, fan_out_cap, "
            "description, owner, labels, enabled, muted, muted_until::text AS muted_until, cadence_tier, "
            "category, subcategory, created_at::text AS created_at FROM rvbbit.alert_catalog WHERE name=%s",
            (name,)).fetchone()
        if not d:
            return {"error": {"code": "ALERT_NOT_FOUND", "message": name}}
        d["state"] = c.execute(
            "SELECT count(*) FILTER (WHERE last_status='fail') AS breaching, count(*) AS entities, "
            "max(last_fired_at)::text AS last_fired FROM rvbbit.alert_state WHERE rule_name=%s",
            (name,)).fetchone()
        d["pending"] = c.execute(
            "SELECT count(*) AS n FROM rvbbit.alert_queue WHERE rule_name=%s AND status='pending'",
            (name,)).fetchone()["n"]
        d["recent_events"] = c.execute(
            "SELECT entity_key, transition, status, error, ts::text AS ts FROM rvbbit.alert_events "
            "WHERE rule_name=%s ORDER BY ts DESC LIMIT 5", (name,)).fetchall()
        d["versions"] = c.execute(
            "SELECT version, created_at::text AS created_at FROM rvbbit.alert_rules WHERE name=%s "
            "ORDER BY version DESC", (name,)).fetchall()
    return d


def tool_alert_state(name, limit=200) -> dict:
    """Per-entity reconciler state for a rule: entity_key, last_status (pass|fail), score, consecutive
    fail count, and when it last changed/fired — the breakdown behind a rule's breach count."""
    lim = max(1, min(int(limit or 200), 1000))
    with _conn() as c:
        rows = c.execute(
            "SELECT entity_key, last_status, score, consecutive, last_changed_at::text AS last_changed_at, "
            "last_fired_at::text AS last_fired_at FROM rvbbit.alert_state WHERE rule_name=%s "
            "ORDER BY (score IS NULL), score DESC NULLS LAST, entity_key LIMIT %s", (name, lim)).fetchall()
    return {"alert": name, "entities": rows, "count": len(rows)}


def tool_alert_events(name=None, limit=50) -> dict:
    """The firing audit log (newest first): which rule+entity fired, the transition, fired/failed
    status, the action output or error, and when. Pass name to scope to one rule."""
    lim = max(1, min(int(limit or 50), 500))
    with _conn() as c:
        rows = c.execute(
            "SELECT rule_name, entity_key, transition, status, action_output, error, ts::text AS ts "
            "FROM rvbbit.alert_events WHERE (%s::text IS NULL OR rule_name=%s::text) "
            "ORDER BY ts DESC LIMIT %s", (name, name, lim)).fetchall()
    return {"events": rows, "count": len(rows)}


def tool_alert_sweep_runs(limit=40) -> dict:
    """The sweep heartbeat (newest first): per tick — tier, start/finish, rules evaluated,
    transitions, enqueued, errors. Use it to confirm the reconciler is alive and see its rate."""
    lim = max(1, min(int(limit or 40), 500))
    with _conn() as c:
        rows = c.execute(
            "SELECT sweep_id, tier, started_at::text AS started_at, finished_at::text AS finished_at, "
            "rules_evaluated, transitions, enqueued, errors FROM rvbbit.alert_sweep_runs "
            "ORDER BY started_at DESC LIMIT %s", (lim,)).fetchall()
    return {"sweeps": rows, "count": len(rows)}


def tool_breaching_alerts() -> dict:
    """Which alerts are FAILING right now — the scalar analog of breaching_kpis. Per rule currently in
    fail state: how many entities are breaching, the worst (max) score, when it last fired, plus its
    enabled/muted/tier so you can tell real fires from silenced ones."""
    with _conn() as c:
        rows = c.execute(
            "SELECT c.name, c.cadence_tier, c.enabled, c.muted, c.category, "
            "count(*) AS breaching_entities, max(s.score) AS worst_score, "
            "max(s.last_fired_at)::text AS last_fired "
            "FROM rvbbit.alert_state s JOIN rvbbit.alert_catalog c ON c.name=s.rule_name "
            "WHERE s.last_status='fail' "
            "GROUP BY c.name, c.cadence_tier, c.enabled, c.muted, c.category "
            "ORDER BY breaching_entities DESC, c.name").fetchall()
    return {"breaching": rows, "count": len(rows)}


def tool_set_alert_enabled(name, enabled) -> dict:
    """Enable or disable a rule (control flag; survives re-definition). Disabled rules are skipped by
    the sweep. The non-destructive on/off — use this (or mute) to silence a noisy alert, not delete."""
    fn = "enable_alert" if enabled else "disable_alert"   # fixed literals, not user input
    with _conn() as c:
        try:
            c.execute(f"SELECT rvbbit.{fn}(%s)", (name,))
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "ALERT_CONTROL_FAILED", "message": str(e)}}
    return {"alert": name, "enabled": bool(enabled)}


def tool_mute_alert(name, minutes=None) -> dict:
    """Temporarily silence a rule's ACTIONS without stopping evaluation. minutes=None mutes
    indefinitely (until unmuted); otherwise for that many minutes. Returns the muted_until."""
    with _conn() as c:
        try:
            if minutes is None:
                row = c.execute("SELECT rvbbit.mute_alert(%s)::text AS until", (name,)).fetchone()
            else:
                row = c.execute("SELECT rvbbit.mute_alert(%s, make_interval(mins => %s))::text AS until",
                                (name, int(minutes))).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "MUTE_FAILED", "message": str(e)}}
    return {"alert": name, "muted_until": row["until"] if row else None}


def tool_unmute_alert(name) -> dict:
    """Clear a rule's mute (resume its actions)."""
    with _conn() as c:
        try:
            c.execute("SELECT rvbbit.unmute_alert(%s)", (name,))
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "UNMUTE_FAILED", "message": str(e)}}
    return {"alert": name, "muted": False}


def tool_set_alert_cadence(name, tier) -> dict:
    """Move a rule to a sweep tier: 'fast' (~1m), 'normal' (~15m), or 'slow' (~hourly)."""
    if tier not in ("fast", "normal", "slow"):
        return {"error": {"code": "BAD_TIER", "message": "tier must be fast|normal|slow"}}
    with _conn() as c:
        try:
            c.execute("SELECT rvbbit.set_alert_cadence(%s, %s)", (name, tier))
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "CADENCE_FAILED", "message": str(e)}}
    return {"alert": name, "cadence_tier": tier}


def tool_set_alerts_enabled(on) -> dict:
    """The GLOBAL alerts kill-switch. on=false pauses ALL sweeps + actions at once (the circuit
    breaker); on=true resumes. Returns the new state. Pairs with the alerts_enabled flag in list_alerts."""
    with _conn() as c:
        try:
            row = c.execute("SELECT rvbbit.set_alerts_enabled(%s) AS on", (bool(on),)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "KILLSWITCH_FAILED", "message": str(e)}}
    return {"alerts_enabled": row["on"] if row else None}


def tool_run_alert_sweep(tier="normal") -> dict:
    """Run one reconciler sweep NOW for a tier (fast|normal|slow) instead of waiting for cron —
    evaluates conditions, diffs state, enqueues transitions. Returns the sweep summary. Pair with
    run_alert_worker to actually dispatch what it enqueues."""
    if tier not in ("fast", "normal", "slow"):
        return {"error": {"code": "BAD_TIER", "message": "tier must be fast|normal|slow"}}
    with _conn() as c:
        try:
            row = c.execute("SELECT rvbbit.alert_sweep(%s) AS j", (tier,)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "SWEEP_FAILED", "message": str(e)}}
    return {"tier": tier, "summary": row["j"] if row else None}


def tool_run_alert_worker(max_items=50) -> dict:
    """Drain up to max_items from the action queue NOW (dispatch pending alert actions) instead of
    waiting for cron. Fire-and-forget; results land in alert_events. Returns the drain summary."""
    n = max(1, min(int(max_items or 50), 500))
    with _conn() as c:
        try:
            row = c.execute("SELECT rvbbit.alert_worker_tick(%s) AS j", (n,)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "WORKER_FAILED", "message": str(e)}}
    return {"max": n, "summary": row["j"] if row else None}


def tool_preview_alert_condition(query, expr=None) -> dict:
    """Dry-run an alert CONDITION read-only — the observable feedback for authoring a rule before any
    rule exists. Runs the query (LIMIT 500) and returns its (entity_key, score, status) rows + counts.
    If expr is given, wraps the query in the same CASE the sweep uses (status='fail' when expr true)
    so a bad boolean expr surfaces as an error here. A condition query should return an entity_key
    column plus EITHER a status ('pass'/'fail') OR a numeric score. Read-only: writes are blocked."""
    trimmed = (query or "").strip().rstrip(";").strip()
    if not trimmed:
        return {"error": {"code": "EMPTY_QUERY", "message": "query is required"}}
    e = (expr or "").strip()
    inner = (f"SELECT q2.*, CASE WHEN ({e}) THEN 'fail' ELSE 'pass' END AS _alert_status FROM ({trimmed}) q2"
             if e else trimmed)
    try:
        with _ro() as c:   # read-only txn + statement timeout: agent-supplied SQL cannot write
            rows = c.execute(f"SELECT to_jsonb(q) AS j FROM ({inner}) q LIMIT 500").fetchall()
    except Exception as ex:  # noqa: BLE001
        return {"valid": False, "error": str(ex)}
    out = []
    for r in rows:
        j = r["j"] or {}
        out.append({
            "entity_key": j["entity_key"] if j.get("entity_key") is not None else "",
            "score": j.get("score"),
            "status": (j.get("_alert_status") if e else j.get("status")),
        })
    breaching = sum(1 for x in out if str(x["status"]).lower() == "fail")
    return {"valid": True, "rows": out, "count": len(out), "breaching": breaching,
            "columns": list((rows[0]["j"] or {}).keys()) if rows else []}


def tool_preview_metric_observation(metric) -> dict:
    """The latest materialized observation for a metric — exactly what a metric-kind condition reads
    (status pass/fail, value, verdict, data-time). Check this before wiring an alert onto a metric."""
    with _ro() as c:
        row = c.execute(
            "SELECT status, data_as_of::text AS data_as_of, value, verdict FROM rvbbit.metric_observations "
            "WHERE metric_name=%s ORDER BY data_as_of DESC NULLS LAST, observed_at DESC LIMIT 1",
            (metric,)).fetchone()
    if not row:
        return {"metric": metric, "observation": None,
                "note": "no materialized observation yet — run materialize_metric first"}
    return {"metric": metric, "observation": row}


# ── consumer verbs: opinionated, pre-shaped business views ────────────────────
# The MCP can't render UI, so these return data ALREADY shaped (rows/cols/totals) plus an explicit
# `render` instruction the agent follows — a "pre-baked opinion" on how to look at the numbers, not a
# raw crosstab. All thin compositions over the blessed metric / metric_by / observation log.

_GRAINS = {"day", "week", "month", "quarter", "year"}


def _isnum(v):
    """A real number (int/float/Decimal) — NOT a bool (which is an int subclass in Python)."""
    return isinstance(v, (int, float, Decimal)) and not isinstance(v, bool)


def _metric_scalar(v, prefer=None):
    """Pull a representative number out of a metric row (dict), a stored value ([{...}] list), or a
    bare number. Prefers `prefer`, then a 'value' key, then the first numeric field."""
    if v is None or isinstance(v, bool):
        return None
    if _isnum(v):
        return float(v)
    if isinstance(v, list):
        v = v[0] if v else None
    if isinstance(v, dict):
        for k in ([prefer] if prefer else []) + ["value"]:
            if k and _isnum(v.get(k)):
                return float(v[k])
        for val in v.values():
            if _isnum(val):
                return float(val)
    return None


def _measure_order(c, metric):
    """The metric's measure aliases in DEFINITION order (its select-list) — the first is the headline
    measure. jsonb reorders keys by (length, alpha), so without this the 'first numeric' would be
    arbitrary; this restores the author's intended order."""
    row = c.execute(
        "SELECT sql FROM rvbbit.metric_defs WHERE name=%s ORDER BY created_at DESC, version DESC LIMIT 1",
        (metric,)).fetchone()
    if not row or not row.get("sql"):
        return []
    mobj = re.match(r"(?is)^\s*select\s+(.*?)\s+from\s", row["sql"])
    if not mobj:
        return []
    parts, depth, cur = [], 0, ""
    for ch in mobj.group(1):
        if ch == "(":
            depth += 1; cur += ch
        elif ch == ")":
            depth -= 1; cur += ch
        elif ch == "," and depth == 0:
            parts.append(cur); cur = ""
        else:
            cur += ch
    if cur.strip():
        parts.append(cur)
    out = []
    for p in parts:
        p = p.strip()
        am = re.search(r'(?is)\bas\s+"?([a-z_][a-z0-9_]*)"?\s*$', p) or re.search(r"([a-z_][a-z0-9_]*)\s*$", p, re.I)
        if am:
            out.append(am.group(1).lower())
    return out


def _pick_measures(c, metric, sample, exclude):
    """Numeric measure columns of a metric row, ranked by the metric's definition order (headline first)."""
    numeric = [k for k, v in sample.items() if k not in exclude and _isnum(v)]
    order = _measure_order(c, metric)
    return sorted(numeric, key=lambda k: (order.index(k) if k in order else 999, k))


def tool_scoreboard(category=None, grain="month", periods=6, as_of=None) -> dict:
    """The executive KPI matrix: every blessed metric laid out as category › subcategory (left axis) ×
    time periods (top axis), each cell = the metric's value that period, with its latest target verdict
    and a trend. Reads the materialized observation log (the governed history — no recompute). Filter by
    category; grain = day|week|month|quarter|year; periods = how many columns back. The 'how are we
    doing?' view — render it as one opinionated matrix, not a flat list."""
    if grain not in _GRAINS:
        return {"error": {"code": "BAD_GRAIN", "message": f"grain must be one of {sorted(_GRAINS)}"}}
    n = max(1, min(int(periods or 6), 36))
    step = f"1 {grain}"
    with _ro() as c:
        axis = [r["period"] for r in c.execute(
            "SELECT to_char(b,'YYYY-MM-DD') AS period FROM generate_series("
            "date_trunc(%s, coalesce(%s::timestamptz, now())) - ((%s - 1) * (%s)::interval), "
            "date_trunc(%s, coalesce(%s::timestamptz, now())), (%s)::interval) b ORDER BY b",
            (grain, as_of, n, step, grain, as_of, step)).fetchall()]
        long = c.execute(
            "WITH obs AS (SELECT o.metric_name, "
            "  to_char(date_trunc(%s, coalesce(o.data_as_of,o.observed_at)),'YYYY-MM-DD') AS bucket, "
            "  o.value, o.status, row_number() OVER (PARTITION BY o.metric_name, "
            "    date_trunc(%s, coalesce(o.data_as_of,o.observed_at)) ORDER BY o.observed_at DESC) AS rn "
            "  FROM rvbbit.metric_observations o) "
            "SELECT m.name, m.category, m.subcategory, m.description, m.grain AS metric_grain, "
            "       obs.bucket, obs.value, obs.status "
            "FROM rvbbit.metric_catalog m LEFT JOIN obs ON obs.metric_name=m.name AND obs.rn=1 "
            "WHERE (%s::text IS NULL OR m.category=%s::text) "
            "ORDER BY m.category NULLS LAST, m.subcategory NULLS LAST, m.name",
            (grain, grain, category, category)).fetchall()
    axis_set = set(axis)
    metrics, order = {}, []
    for r in long:
        nm = r["name"]
        if nm not in metrics:
            metrics[nm] = {"category": r["category"], "subcategory": r["subcategory"],
                           "description": r["description"], "metric_grain": r["metric_grain"], "cells": {}}
            order.append(nm)
        b = r["bucket"]
        if b and b in axis_set:
            metrics[nm]["cells"][b] = {"value": _metric_scalar(r["value"]), "status": r["status"]}
    groups = {}
    for nm in order:
        md = metrics[nm]
        series = [(md["cells"].get(p) or {}).get("value") for p in axis]
        present = [md["cells"][p] for p in axis if p in md["cells"]]
        latest = present[-1] if present else {}
        nn = [v for v in series if v is not None]
        trend = None
        if len(nn) >= 2:
            trend = "up" if nn[-1] > nn[0] else ("down" if nn[-1] < nn[0] else "flat")
        key = (md["category"] or "Uncategorized", md["subcategory"] or "")
        groups.setdefault(key, []).append({
            "name": nm, "description": md["description"], "metric_grain": md["metric_grain"],
            "cells": series, "latest": latest.get("value"), "status": latest.get("status"), "trend": trend})
    out_groups = [{"category": k[0], "subcategory": k[1], "metrics": v}
                  for k, v in sorted(groups.items())]
    return {"grain": grain, "periods": axis, "groups": out_groups,
            "render": {"as": "kpi_matrix",
                       "note": "Render as ONE matrix: left axis = category › subcategory › metric (grouped with "
                               "subcategory subheaders, indented), top axis = the periods (oldest left → newest "
                               "right), each cell = the value. On the latest cell append a ▲/▼/– from trend and a "
                               "✓/✗ from status. Right-align numbers. This is an executive scoreboard, not a list."}}


def tool_pivot(metric, rows, cols, measure=None, params=None, as_of=None) -> dict:
    """A governed crosstab of a DIMENSIONAL metric: rows (a cube dimension) × cols (a cube dimension) ×
    one measure, with row/column/grand totals. Reshapes metric_by into a matrix — values are the blessed
    metric's, dimensions are validated against the cube — so it's a repeatable pivot table, not hand-rolled
    SQL. measure defaults to the metric's first numeric measure. Call metric_dimensions(metric) to see
    the sliceable columns. Render as a matrix."""
    if not rows or not cols:
        return {"error": {"code": "BAD_AXES", "message": "rows and cols are required cube dimensions"}}
    available = []
    with _conn() as c:
        try:
            recs = c.execute(
                "SELECT rvbbit.metric_by(%s, %s::text[], %s::jsonb, now(), %s::timestamptz) AS m",
                (metric, [rows, cols], json.dumps(params or {}), as_of)).fetchall()
            longrows = [r["m"] for r in recs if r["m"] is not None]
            if longrows:
                available = _pick_measures(c, metric, longrows[0], {rows, cols})
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "PIVOT_FAILED", "message": str(e)}}
    if not longrows:
        return {"metric": metric, "rows_dim": rows, "cols_dim": cols, "matrix": [], "note": "no rows"}
    if measure is None:
        measure = available[0] if available else None        # headline measure (definition order)
    elif measure not in available:
        return {"error": {"code": "BAD_MEASURE",
                          "message": f"'{measure}' is not a numeric measure; available: {available}"}}
    if measure is None:
        return {"error": {"code": "NO_MEASURE",
                          "message": f"no numeric measure found in {sorted(longrows[0].keys())}; pass measure="}}
    cells, row_vals, col_vals = {}, [], []
    for rec in longrows:
        rv = "" if rec.get(rows) is None else str(rec.get(rows))
        cv = "" if rec.get(cols) is None else str(rec.get(cols))
        if rv not in cells:
            cells[rv] = {}
            row_vals.append(rv)
        if cv not in col_vals:
            col_vals.append(cv)
        cells[rv][cv] = rec.get(measure)
    row_vals.sort()
    col_vals.sort()
    col_tot = {cv: 0.0 for cv in col_vals}
    grand = 0.0
    matrix = []
    for rv in row_vals:
        rc = {cv: cells[rv].get(cv) for cv in col_vals}
        rtot = 0.0
        for cv in col_vals:
            x = rc[cv]
            if _isnum(x):
                rtot += x
                col_tot[cv] += x
        grand += rtot
        matrix.append({"row": rv, "cells": rc, "total": rtot})
    return {"metric": metric, "rows_dim": rows, "cols_dim": cols, "measure": measure,
            "available_measures": available, "columns": col_vals, "matrix": matrix,
            "col_totals": col_tot, "grand_total": grand,
            "render": {"as": "pivot",
                       "note": f"Render as a matrix: '{rows}' down the left, '{cols}' across the top, cell = "
                               f"{measure}. Right-align numbers; add the per-row 'total' column and the col_totals "
                               f"row (with grand_total in the corner); bold totals. Other measures available: "
                               f"{[a for a in available if a != measure]} (re-call pivot with measure= to switch)."}}


_CUBE_NUMERIC_TYPES = {
    "bigint",
    "decimal",
    "double precision",
    "integer",
    "money",
    "numeric",
    "real",
    "smallint",
}
_CUBE_PIVOT_AGGREGATES = ("sum", "avg", "min", "max", "count", "count_distinct")


def _cube_fallback_kind(name: str, data_type: str) -> str:
    lowered = str(name or "").lower()
    if lowered == "id" or lowered.endswith("_id"):
        return "key"
    if data_type in {
        "date",
        "time without time zone",
        "timestamp with time zone",
        "timestamp without time zone",
    }:
        return "time"
    return "measure" if data_type in _CUBE_NUMERIC_TYPES else "dimension"


def _cube_pivot_aggregate(aggregate: str, measure: str | None):
    """Build an aggregate expression from a fixed verb allowlist + validated identifier."""
    if aggregate == "count" and measure is None:
        return pgsql.SQL("count(*)")
    if measure is None:
        raise ValueError(f"{aggregate} requires a numeric measure")
    ident = pgsql.Identifier(measure)
    if aggregate == "count_distinct":
        return pgsql.SQL("count(DISTINCT {})").format(ident)
    return pgsql.SQL("{}({})").format(pgsql.SQL(aggregate), ident)


def _cube_pivot_label(value) -> str:
    return "(blank)" if value is None else str(value)


def _cube_field_list(value, maximum: int = 8) -> list[str]:
    raw = value if isinstance(value, (list, tuple)) else [value]
    out = []
    for item in raw:
        name = str(item or "").strip()
        if name and name not in out:
            out.append(name)
        if len(out) >= maximum:
            break
    return out


def _cube_measure_list(measures, measure, aggregate) -> tuple[list[dict], dict | None]:
    if measures is None:
        raw = [{"field": measure, "aggregate": aggregate}]
    elif isinstance(measures, (list, tuple)):
        raw = list(measures)
    else:
        raw = [measures]
    out = []
    for item in raw[:8]:
        if isinstance(item, dict):
            field = item.get("field", item.get("measure", item.get("name")))
            agg = item.get("aggregate", item.get("agg", "sum"))
        else:
            field, agg = item, "sum"
        field = str(field or "").strip() or None
        if field in {"*", "__rows__"}:
            field = None
        agg = str(agg or "sum").strip().lower()
        if agg not in _CUBE_PIVOT_AGGREGATES:
            return [], {
                "code": "BAD_AGGREGATE",
                "message": (
                    f"'{agg}' is not supported; available: "
                    f"{list(_CUBE_PIVOT_AGGREGATES)}"
                ),
            }
        if field is None and agg != "count":
            return [], {
                "code": "BAD_MEASURE",
                "message": f"{agg} requires a numeric cube field",
            }
        key = f"{agg}:{field or '__rows__'}"
        if any(spec["key"] == key for spec in out):
            continue
        out.append({
            "key": key,
            "field": field,
            "aggregate": agg,
            "label": f"{agg.replace('_', ' ').upper()} {field or 'rows'}",
            "alias": f"__m{len(out)}",
        })
    if not out:
        return [], {
            "code": "BAD_MEASURE",
            "message": "choose at least one numeric value or row count",
        }
    return out, None


def _cube_group_query(relation, dimensions: list[str], measures: list[dict], limit: bool):
    select_parts = [pgsql.Identifier(name) for name in dimensions]
    select_parts.extend(
        pgsql.SQL("{} AS {}").format(
            _cube_pivot_aggregate(spec["aggregate"], spec["field"]),
            pgsql.Identifier(spec["alias"]),
        )
        for spec in measures
    )
    query = pgsql.SQL("SELECT {} FROM {}").format(
        pgsql.SQL(",").join(select_parts),
        relation,
    )
    if dimensions:
        ordinals = [pgsql.SQL(str(index + 1)) for index in range(len(dimensions))]
        ordered = [
            pgsql.SQL("{} NULLS LAST").format(ordinal)
            for ordinal in ordinals
        ]
        query += pgsql.SQL(" GROUP BY {} ORDER BY {}").format(
            pgsql.SQL(",").join(ordinals),
            pgsql.SQL(",").join(ordered),
        )
    if limit:
        query += pgsql.SQL(" LIMIT %s")
    return query


def _cube_dimension_values(row, dimensions: list[str]) -> dict[str, str]:
    return {name: _cube_pivot_label(row.get(name)) for name in dimensions}


def _cube_dimension_key(row, dimensions: list[str]) -> str:
    return json.dumps(
        [_cube_pivot_label(row.get(name)) for name in dimensions],
        separators=(",", ":"),
    )


def _cube_query_engine(conn, query) -> dict:
    """Use the same route-plan metadata as run_sql; never rerun the data query.

    Keep the probe in a savepoint: missing routing support must not abort an
    otherwise valid read-only pivot. This describes the cell query's selected
    route, not an assertion about every separate totals query or fallback.
    """
    try:
        with conn.transaction():
            route = conn.execute("SELECT rvbbit.route_explain(%s) AS e", (query.as_string(),)).fetchone()["e"]
            engine = route.get("chosen_candidate")
            if not engine and (route.get("reason") == "query does not reference Rvbbit tables"
                               or (_route_explain_read_only_select(route) and not route.get("safe_select"))):
                engine = "postgres"
            return {"engine": engine, "engine_source": "route_plan"} if engine else {}
    except Exception:
        return {}


def tool_cube_pivot(
    cube,
    rows,
    cols=None,
    measure=None,
    aggregate="sum",
    measures=None,
) -> dict:
    """Explore a cube directly as a grouped table or crosstab, without requiring a metric.

    ``rows`` and optional ``cols`` accept one field or a list of fields.
    ``measures`` accepts ``[{field, aggregate}, ...]`` and supersedes the legacy
    singular ``measure``/``aggregate`` pair. With no column dimensions the
    result is an ordinary grouped table. Adding column dimensions produces a
    crosstab. Every relation and field is validated and quoted.
    """
    started = time.monotonic()
    cube = str(cube or "").strip()
    row_dimensions = _cube_field_list(rows)
    column_dimensions = _cube_field_list(cols)
    measure_specs, measure_error = _cube_measure_list(
        measures,
        measure,
        aggregate,
    )
    if not cube:
        return {
            "error": {
                "code": "BAD_AXES",
                "message": "cube is required",
            }
        }
    if measure_error:
        return {"error": measure_error}
    overlap = sorted(set(row_dimensions) & set(column_dimensions))
    if overlap:
        return {
            "error": {
                "code": "BAD_AXES",
                "message": f"fields cannot be on both Rows and Columns: {overlap}",
            }
        }

    try:
        with _conn(read_only=True, role=_session_pg_role()) as c:
            found = c.execute(
                "SELECT name FROM rvbbit.cube_catalog WHERE name=%s",
                (cube,),
            ).fetchone()
            if not found:
                return {"error": {"code": "CUBE_NOT_FOUND", "message": cube}}

            column_rows = c.execute(
                "SELECT column_name,data_type FROM information_schema.columns "
                "WHERE table_schema='cubes' AND table_name=%s ORDER BY ordinal_position",
                (cube,),
            ).fetchall()
            if not column_rows:
                return {
                    "error": {
                        "code": "CUBE_UNAVAILABLE",
                        "message": f"cubes.{cube} is not materialized or is not visible",
                    }
                }
            dimension_rows = c.execute(
                "SELECT column_name,data_type,kind,groupable,distinct_est,semantics "
                "FROM rvbbit.cube_dimensions(%s)",
                (cube,),
            ).fetchall()
            dimensions = {str(row["column_name"]): dict(row) for row in dimension_rows}
            fields = []
            for column in column_rows:
                name = str(column["column_name"])
                data_type = str(column["data_type"] or "").lower()
                detail = dimensions.get(name, {})
                fallback_kind = _cube_fallback_kind(name, data_type)
                fields.append({
                    "name": name,
                    "type": data_type,
                    "kind": detail.get("kind") or fallback_kind,
                    "groupable": bool(detail.get(
                        "groupable",
                        fallback_kind != "measure",
                    )),
                    "numeric": data_type in _CUBE_NUMERIC_TYPES,
                    "distinct_est": detail.get("distinct_est"),
                    "semantics": detail.get("semantics"),
                })
            by_name = {field["name"]: field for field in fields}
            available_dimensions = [
                field["name"] for field in fields if field["groupable"]
            ]
            available_measures = [
                field["name"] for field in fields if field["numeric"]
            ]
            bad_axes = [
                axis for axis in row_dimensions + column_dimensions
                if axis not in available_dimensions
            ]
            if bad_axes:
                return {
                    "error": {
                        "code": "BAD_AXES",
                        "message": (
                            f"not groupable: {bad_axes}; available: "
                            f"{available_dimensions}"
                        ),
                    }
                }
            bad_measures = sorted({
                spec["field"]
                for spec in measure_specs
                if spec["field"] is not None
                and (
                    spec["field"] not in by_name
                    or not by_name[spec["field"]]["numeric"]
                )
            })
            if bad_measures:
                return {
                    "error": {
                        "code": "BAD_MEASURE",
                        "message": (
                            f"not numeric: {bad_measures}; available: "
                            f"{available_measures}"
                        ),
                    }
                }

            relation = pgsql.SQL("{}.{}").format(
                pgsql.Identifier("cubes"),
                pgsql.Identifier(cube),
            )
            cell_dimensions = row_dimensions + column_dimensions
            grouped_row_cap = max(
                1,
                CUBE_PIVOT_CELL_CAP // max(1, len(measure_specs)),
            )
            cell_query = _cube_group_query(
                relation,
                cell_dimensions,
                measure_specs,
                limit=bool(cell_dimensions),
            )
            plan_query = _cube_group_query(relation, cell_dimensions, measure_specs, limit=False)
            if cell_dimensions:
                plan_query += pgsql.SQL(" LIMIT {}").format(pgsql.Literal(grouped_row_cap + 1))
            execution = _cube_query_engine(c, plan_query)
            cell_rows = c.execute(
                cell_query,
                (grouped_row_cap + 1,) if cell_dimensions else None,
            ).fetchall()
            if len(cell_rows) > grouped_row_cap:
                return {
                    "error": {
                        "code": "PIVOT_TOO_LARGE",
                        "message": (
                            f"this pivot exceeds {CUBE_PIVOT_CELL_CAP:,} cells; "
                            "choose lower-cardinality axes"
                        ),
                    }
                }
            if column_dimensions:
                row_total_rows = c.execute(
                    _cube_group_query(
                        relation,
                        row_dimensions,
                        measure_specs,
                        limit=False,
                    )
                ).fetchall()
                col_total_rows = c.execute(
                    _cube_group_query(
                        relation,
                        column_dimensions,
                        measure_specs,
                        limit=False,
                    )
                ).fetchall()
            else:
                row_total_rows = []
                col_total_rows = []
            grand_row = c.execute(
                _cube_group_query(
                    relation,
                    [],
                    measure_specs,
                    limit=False,
                )
            ).fetchone()
    except Exception as exc:  # noqa: BLE001
        return {
            "error": {
                "code": "CUBE_PIVOT_FAILED",
                "message": str(exc),
            }
        }

    public_measures = [
        {key: spec[key] for key in ("key", "field", "aggregate", "label")}
        for spec in measure_specs
    ]
    grand_totals = {
        spec["key"]: grand_row.get(spec["alias"]) if grand_row else None
        for spec in measure_specs
    }
    common = {
        **execution,
        "elapsed_ms": round((time.monotonic() - started) * 1000),
        "cube": cube,
        "rows_dim": row_dimensions[0] if len(row_dimensions) == 1 else " › ".join(row_dimensions),
        "cols_dim": (
            column_dimensions[0]
            if len(column_dimensions) == 1
            else " › ".join(column_dimensions)
        ) or None,
        "row_dimensions": row_dimensions,
        "column_dimensions": column_dimensions,
        "measure": measure_specs[0]["field"],
        "value_label": measure_specs[0]["field"] or "rows",
        "aggregate": measure_specs[0]["aggregate"],
        "measures": public_measures,
        "available_dimensions": available_dimensions,
        "available_measures": available_measures,
        "available_aggregates": list(_CUBE_PIVOT_AGGREGATES),
        "fields": fields,
        "grand_totals": grand_totals,
        "grand_total": grand_totals.get(measure_specs[0]["key"]),
        "cell_count": len(cell_rows) * len(measure_specs),
    }

    if not column_dimensions:
        table_columns = [
            {"key": name, "label": name, "kind": "dimension"}
            for name in row_dimensions
        ] + [
            {
                "key": spec["key"],
                "label": spec["label"],
                "kind": "measure",
                "measure_key": spec["key"],
            }
            for spec in measure_specs
        ]
        table_rows = [
            {
                "dimensions": _cube_dimension_values(row, row_dimensions),
                "values": {
                    spec["key"]: row.get(spec["alias"])
                    for spec in measure_specs
                },
            }
            for row in cell_rows
        ]
        return {
            **common,
            "display_mode": "table",
            "table_columns": table_columns,
            "table_rows": table_rows,
            "row_count": len(table_rows),
            "render": {
                "as": "grouped_table",
                "note": (
                    f"Render {row_dimensions or ['overall']} as ordinary columns "
                    f"with values {[spec['label'] for spec in measure_specs]}."
                ),
            },
        }

    column_groups = []
    column_group_keys = {}
    row_items = {}
    for record in cell_rows:
        row_key = _cube_dimension_key(record, row_dimensions)
        col_key = _cube_dimension_key(record, column_dimensions)
        if col_key not in column_group_keys:
            short_key = f"c{len(column_groups)}"
            column_group_keys[col_key] = short_key
            column_groups.append({
                "key": short_key,
                "values": _cube_dimension_values(record, column_dimensions),
            })
        short_key = column_group_keys[col_key]
        if row_key not in row_items:
            row_items[row_key] = {
                "row": " › ".join(_cube_dimension_values(record, row_dimensions).values()) or "Overall",
                "dimensions": _cube_dimension_values(record, row_dimensions),
                "cells": {},
                "totals": {},
            }
        for spec in measure_specs:
            row_items[row_key]["cells"][f"{short_key}::{spec['key']}"] = record.get(
                spec["alias"]
            )

    row_totals = {
        _cube_dimension_key(record, row_dimensions): {
            spec["key"]: record.get(spec["alias"])
            for spec in measure_specs
        }
        for record in row_total_rows
    }
    for row_key, item in row_items.items():
        item["totals"] = row_totals.get(row_key, {})
        item["total"] = item["totals"].get(measure_specs[0]["key"])

    col_total_groups = {
        _cube_dimension_key(record, column_dimensions): record
        for record in col_total_rows
    }
    value_columns = []
    col_totals = {}
    for group in column_groups:
        raw_key = json.dumps(list(group["values"].values()), separators=(",", ":"))
        total_record = col_total_groups.get(raw_key, {})
        group_label = " › ".join(group["values"].values()) or "Overall"
        for spec in measure_specs:
            key = f"{group['key']}::{spec['key']}"
            value_columns.append({
                "key": key,
                "label": (
                    f"{group_label} · {spec['label']}"
                    if len(measure_specs) > 1
                    else group_label
                ),
                "column_values": group["values"],
                "measure_key": spec["key"],
            })
            col_totals[key] = total_record.get(spec["alias"])

    matrix = list(row_items.values())
    return {
        **common,
        "display_mode": "crosstab",
        "column_groups": column_groups,
        "value_columns": value_columns,
        "columns": [column["key"] for column in value_columns],
        "matrix": matrix,
        "col_totals": col_totals,
        "row_count": len(matrix),
        "render": {
            "as": "pivot",
            "note": (
                f"Render {row_dimensions or ['overall']} down the left, "
                f"{column_dimensions} across the top, with "
                f"{[spec['label'] for spec in measure_specs]} as values."
            ),
        },
    }


def tool_compare(metric, period_a, period_b, by=None, params=None) -> dict:
    """Period-over-period / variance for a metric: its value at period_a vs period_b with Δ and %Δ. Pass
    `by` (a cube dimension) to break it down per segment (a variance table). Periods are data-time
    instants (e.g. '2026-03-31' vs '2026-06-30') — each side is the metric AS OF that instant via the
    bitemporal engine. Render the breakdown as a table sorted by |Δ|."""
    pj = json.dumps(params or {})

    def delta(a, b):
        if a is None or b is None:
            return {"a": a, "b": b, "delta": None, "pct": None}
        d = b - a
        return {"a": a, "b": b, "delta": d, "pct": (d / a * 100.0) if a else None}

    measure = None
    with _conn() as c:
        try:
            if by:
                ra = [r["m"] for r in c.execute(
                    "SELECT rvbbit.metric_by(%s,%s::text[],%s::jsonb,now(),%s::timestamptz) AS m",
                    (metric, [by], pj, period_a)).fetchall() if r["m"] is not None]
                rb = [r["m"] for r in c.execute(
                    "SELECT rvbbit.metric_by(%s,%s::text[],%s::jsonb,now(),%s::timestamptz) AS m",
                    (metric, [by], pj, period_b)).fetchall() if r["m"] is not None]
                sample = (ra or rb or [{}])[0]
                picks = _pick_measures(c, metric, sample, {by})
                measure = picks[0] if picks else None
            else:
                ra = [r["m"] for r in c.execute(
                    "SELECT rvbbit.metric(%s,%s::jsonb,now(),%s::timestamptz) AS m",
                    (metric, pj, period_a)).fetchall() if r["m"] is not None]
                rb = [r["m"] for r in c.execute(
                    "SELECT rvbbit.metric(%s,%s::jsonb,now(),%s::timestamptz) AS m",
                    (metric, pj, period_b)).fetchall() if r["m"] is not None]
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "COMPARE_FAILED", "message": str(e)}}
    if by:
        amap = {str(r.get(by)): _metric_scalar(r, measure) for r in ra}
        bmap = {str(r.get(by)): _metric_scalar(r, measure) for r in rb}
        rows = [{"segment": s, **delta(amap.get(s), bmap.get(s))} for s in sorted(set(amap) | set(bmap))]
        rows.sort(key=lambda x: abs(x["delta"]) if x["delta"] is not None else -1, reverse=True)
        ta = sum(v for v in amap.values() if v is not None)
        tb = sum(v for v in bmap.values() if v is not None)
        return {"metric": metric, "by": by, "measure": measure, "period_a": period_a, "period_b": period_b,
                "total": delta(ta, tb), "rows": rows,
                "render": {"as": "variance",
                           "note": f"Variance table: one row per '{by}', columns value@{period_a}, value@{period_b}, "
                                   "Δ, %Δ; sorted by |Δ| (biggest movers first); show the total row; "
                                   "color Δ red(neg)/green(pos)."}}
    a = _metric_scalar(ra[0]) if ra else None
    b = _metric_scalar(rb[0]) if rb else None
    return {"metric": metric, "period_a": period_a, "period_b": period_b, **delta(a, b),
            "render": {"as": "delta", "note": "Show value@A, value@B, Δ and %Δ as a compact stat line."}}


# ── document brain — role-gated, semantically-searchable docs ─────────────────
# Access is enforced server-side from the AUTHENTICATED caller email (never a tool argument): the
# retrieval filters to the caller's permitted docs BEFORE the vector search, so a restricted doc never
# enters the result set and can't be paraphrased into an answer. caller_email is injected by the
# registration lambda from _caller(); read tools require it (default-deny on no identity).

def tool_ask_brain(query, k=8, filters=None, caller_email=None) -> dict:
    """Ask the document brain — semantic search over the docs YOU are permitted to see, returned as
    grounded, citeable context (NOT a synthesized answer — compose the answer from these chunks and
    cite title/folder). Access is enforced from your authenticated identity: docs you lack a role for,
    or that exclude you, never appear. The ABSENCE of a doc means you're not cleared for it — never
    speculate about what you can't see.

    PRE-FILTER to avoid mixing object classes: pass `filters` to narrow BEFORE the search —
      {"type": "ticket"}  ·  {"type": ["document","meeting"]}  ·  {"source": "Linear · all"}  ·
      {"folder": "/sops", "since": "2026-01-01"}.
    Every hit is tagged with `doc_type` (e.g. document, ticket, meeting) and `source`, and `types` /
    `sources` summarize what came back. Don't know what's filterable? Call brain_facets first.

    This is the ENTRY POINT, not the whole story. Each hit carries breadcrumbs — its doc's key
    `entities` (knowledge-graph handles) — and a doc-level `documents` rollup lists, per doc, its
    entities + `related` docs (other docs you can see that share its concepts). Pull threads on demand
    rather than over-fetching: brain_context(doc_id, chunk_idx) for the chunks around a hit,
    brain_get_doc(doc_id) for the full document, brain_related(doc_id) to walk the graph from a doc,
    brain_entity(name) to ask 'what do we know about X?'."""
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller (OAuth email)"}}
    k = max(1, min(int(k or 8), 50))
    flt = json.dumps(filters if isinstance(filters, dict) else {})
    with _conn() as c:   # _conn (writable): rvbbit.embed may populate its embedding cache
        try:
            hits = c.execute(
                "SELECT doc_id, chunk_idx, title, folder_path AS folder, source, doc_type, "
                "occurred_at::text AS occurred_at, chunk, round(score::numeric, 4) AS score, entities "
                "FROM rvbbit.brain_search(%s, %s, %s, %s::jsonb)", (caller_email, query, k, flt)).fetchall()
            # Doc-level rollup: dedupe the hit docs; attach DOC-LEVEL entities + related threads from
            # brain_related (same store as the relatedness `shared` counts, so they reconcile). Each
            # related doc carries `shared_entities` — the exact overlap that explains its `shared`.
            # (Per-hit `entities` stay CHUNK-scoped for local signal; the rollup is the doc-level view.)
            docs: dict = {}
            types: dict = {}
            for h in hits:
                d = docs.setdefault(h["doc_id"], {"doc_id": h["doc_id"], "title": h["title"],
                                                  "source": h["source"], "doc_type": h["doc_type"], "n_hits": 0})
                d["n_hits"] += 1
                types[h["doc_type"]] = types.get(h["doc_type"], 0) + 1
            # The doc-level rollup is breadcrumbs, not evidence: measured on the pilot
            # corpus, 15 related docs per hit doc with their shared-entity lists made up
            # ~80% of a 35k-char ask_brain payload that was then re-read on every later
            # step. Keep the top few threads per doc; brain_related walks the full graph.
            for did, d in docs.items():
                rel = c.execute("SELECT rvbbit.brain_related(%s, %s::bigint, %s) AS r",
                                (caller_email, did, _ASK_BRAIN_RELATED_PER_DOC)).fetchone()
                rr = (rel["r"] if rel else {}) or {}
                d["entities"] = [e.get("label") for e in rr.get("entities", []) if e.get("label")][:_ASK_BRAIN_ENTITIES_PER_DOC]
                d["related"] = [_compact_related_doc(item) for item in (rr.get("related") or [])[:_ASK_BRAIN_RELATED_PER_DOC]]
            for h in hits:
                if isinstance(h.get("entities"), list) and len(h["entities"]) > _ASK_BRAIN_ENTITIES_PER_HIT:
                    h["entities"] = h["entities"][:_ASK_BRAIN_ENTITIES_PER_HIT]
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "ASK_BRAIN_FAILED", "message": str(e)}}
    return {"query": query, "as": caller_email, "filters": filters or {}, "hits": hits,
            "documents": list(docs.values()), "count": len(hits), "types": types,
            "note": "Grounded context, not an answer — cite title/folder. Each hit is tagged `doc_type` — "
                    "don't conflate classes (a ticket ≠ an SOP). Pre-filter with `filters` (see brain_facets) "
                    "to narrow by type/source. `documents[].related` shows only the top threads; go deeper "
                    "with brain_context / brain_get_doc / brain_related / brain_entity. "
                    "Absence = not cleared, not 'nothing exists'."}


_ASK_BRAIN_RELATED_PER_DOC = 3
_ASK_BRAIN_ENTITIES_PER_DOC = 8
_ASK_BRAIN_ENTITIES_PER_HIT = 8


def _compact_related_doc(item) -> dict:
    """One related-doc breadcrumb: enough to decide whether to pull the thread."""
    if not isinstance(item, dict):
        return item
    out = {"doc_id": item.get("doc_id"), "title": item.get("title"), "shared": item.get("shared")}
    shared = item.get("shared_entities")
    if isinstance(shared, list) and shared:
        out["shared_entities"] = shared[:3]
    return out


def tool_brain_facets(caller_email=None) -> dict:
    """Discover what you can FILTER by: the document TYPES (document, ticket, meeting, …) and SOURCES you
    are cleared to see, each with a doc count. Call this before ask_brain when you want to narrow — then
    pass filters={"type": "ticket"} or {"source": "..."} to ask_brain. ACL-enforced: only your visible
    corpus is counted."""
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller"}}
    with _ro() as c:
        rows = c.execute("SELECT facet, value, docs FROM rvbbit.brain_facets(%s)", (caller_email,)).fetchall()
    return {"as": caller_email,
            "types":   {r["value"]: r["docs"] for r in rows if r["facet"] == "type"},
            "sources": {r["value"]: r["docs"] for r in rows if r["facet"] == "source"},
            "note": "Pass to ask_brain as filters={\"type\": …, \"source\": …} to pre-narrow the search."}


def tool_brain_browse(caller_email=None, source=None, folder=None, limit=100, offset=0) -> dict:
    """Browse one bounded page of the visible document tree (ACL-enforced).

    This is navigation metadata, not semantic retrieval and not evidence that a
    source or document is absent. Use brain_facets to discover visible sources
    and ask_brain to search their contents. Filter by an exact source label or a
    folder (including descendants), then follow next_offset when has_more=true.
    """
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller"}}
    page_limit = max(1, min(int(limit or 100), 250))
    page_offset = max(0, int(offset or 0))
    source_filter = str(source or "").strip() or None
    folder_filter = str(folder or "").strip() or None
    if folder_filter:
        folder_filter = "/" + folder_filter.strip("/") if folder_filter != "/" else "/"

    clauses = []
    params = [caller_email]
    if source_filter:
        clauses.append("lower(source) = lower(%s)")
        params.append(source_filter)
    if folder_filter and folder_filter != "/":
        clauses.append(
            "(folder_path = %s OR left(folder_path, length(%s) + 1) = %s || '/')"
        )
        params.extend((folder_filter, folder_filter, folder_filter))
    where = " WHERE " + " AND ".join(clauses) if clauses else ""
    params.extend((page_limit + 1, page_offset))
    with _ro() as c:
        rows = c.execute(
            "SELECT folder_path, doc_id, title, source, mime, author, occurred_at::text AS occurred_at, "
            "ingested_at::text AS ingested_at, chunks FROM rvbbit.brain_tree(%s)"
            + where
            + " ORDER BY source, folder_path, title, doc_id LIMIT %s OFFSET %s",
            tuple(params),
        ).fetchall()
    has_more = len(rows) > page_limit
    documents = rows[:page_limit]
    return {
        "as": caller_email,
        "filters": {"source": source_filter, "folder": folder_filter},
        "folders": sorted({r["folder_path"] for r in documents}),
        "documents": documents,
        "count": len(documents),
        "limit": page_limit,
        "offset": page_offset,
        "has_more": has_more,
        "next_offset": page_offset + page_limit if has_more else None,
        "note": "Bounded navigation metadata only. Use brain_facets + ask_brain for corpus retrieval or absence checks.",
    }


def tool_brain_get_doc(doc_id, caller_email=None) -> dict:
    """Open one document's full body + metadata — only if you're cleared for it (else NOT_VISIBLE)."""
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller"}}
    with _ro() as c:
        row = c.execute("SELECT rvbbit.brain_get_doc(%s, %s::bigint) AS d", (caller_email, doc_id)).fetchone()
    d = row["d"] if row else None
    if not d:
        return {"error": {"code": "NOT_VISIBLE", "message": f"doc {doc_id} not found or not permitted"}}
    return d


def tool_brain_context(doc_id, chunk_idx, window=2, caller_email=None) -> dict:
    """VERTICAL expand: the chunks immediately AROUND a search hit (window on each side) — cheaper than
    pulling a whole long document when you just need a hit's local context. Pass the doc_id + chunk_idx
    from an ask_brain hit. ACL-gated (empty if you're not cleared for the doc)."""
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller"}}
    with _ro() as c:
        rows = c.execute(
            "SELECT idx, chunk FROM rvbbit.brain_context(%s, %s::bigint, %s::int, %s::int)",
            (caller_email, doc_id, chunk_idx, window)).fetchall()
    return {"doc_id": doc_id, "chunk_idx": chunk_idx, "window": window, "chunks": rows, "count": len(rows)}


def tool_brain_related(doc_id, caller_email=None) -> dict:
    """LATERAL expand: a document's knowledge-graph neighborhood — the entities it names, the typed
    relations among them (e.g. X -acquired-> Y), and OTHER docs you can see that share its entities.
    Follow a thread from a doc instead of re-searching. ACL-gated."""
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller"}}
    with _ro() as c:
        row = c.execute("SELECT rvbbit.brain_related(%s, %s::bigint) AS r", (caller_email, doc_id)).fetchone()
    return (row["r"] if row else {}) or {}


def tool_brain_entity(name, caller_email=None) -> dict:
    """LATERAL expand, entity-centric: given a concept/person/org/metric (e.g. 'NPS', 'refund policy'),
    return its typed relations and the visible documents that mention it — 'what do we know about X?'.
    Resolves by exact then fuzzy name match. ACL-gated (docs list is filtered to what you can see)."""
    if not caller_email:
        return {"error": {"code": "NO_IDENTITY", "message": "brain access requires an authenticated caller"}}
    with _ro() as c:
        row = c.execute("SELECT rvbbit.brain_entity(%s, %s) AS r", (caller_email, name)).fetchone()
    return (row["r"] if row else {}) or {}


_SYSTEM_LEARNING_SUGGESTED_PROMPTS = [
    {
        "label": "Acceleration next steps",
        "query": "Which regular heap tables should I accelerate next, and why?",
        "use_when": "Start here when a database feels slow but you do not know which tables deserve acceleration.",
    },
    {
        "label": "Slow query explanation",
        "query": "What did RVBBIT learn about my slowest query shapes and routing choices?",
        "use_when": "Use after a workload run or benchmark to explain why some shapes prefer specific engines.",
    },
    {
        "label": "Layout payoff",
        "query": "Which accepted workload layouts are built, which are still pending, and what evidence supports them?",
        "use_when": "Use when deciding whether a workload layout should be built, rebuilt, or rejected.",
    },
    {
        "label": "Operator trust",
        "query": "Which SQL operators have enough receipts to trust, and which need more observation?",
        "use_when": "Use before leaning on semantic SQL operators in dashboards or agent workflows.",
    },
    {
        "label": "What changed",
        "query": "What has RVBBIT learned recently about acceleration, routing, layouts, and operators?",
        "use_when": "Use as a weekly or post-deploy briefing for humans and agents.",
    },
]


def _system_learning_answer_contract() -> dict:
    return {
        "style": "grounded_context_not_synthesis",
        "required_citations": ["hit.title", "artifact.uri"],
        "follow_the_breadcrumbs": [
            "Use hit.artifact.handles for the table/layout/shape/operator handle.",
            "Use hit.artifact.followups where tool='run_sql' for the exact learned row.",
            "Use run_sql on rvbbit.system_learning_items when you need the full body/props.",
        ],
        "do_not": [
            "Do not claim a table is accelerated unless the artifact status says so.",
            "Do not treat absence of a hit as absence of evidence; sync first or broaden the query.",
        ],
    }


def _system_learning_readiness(status: dict | None) -> dict:
    if not status or not status.get("installed"):
        return {
            "ready": False,
            "state": "missing",
            "why": "RVBBIT System Learning is not installed in this database.",
            "actions": [
                {"tool": "run_sql", "sql": "SELECT rvbbit.migrate()"},
            ],
        }
    if not status.get("enabled"):
        return {
            "ready": False,
            "state": "paused",
            "why": "The RVBBIT System Learning Brain source is disabled.",
            "actions": [
                {
                    "tool": "run_sql",
                    "sql": "UPDATE rvbbit.brain_sources SET enabled = true WHERE source_id = "
                           f"{int(status.get('source_id') or 0)}",
                },
            ],
        }
    indexed = int(status.get("indexed_items") or 0)
    docs = int(status.get("docs") or 0)
    last_run = status.get("last_run") or {}
    errors = int(last_run.get("errors") or 0)
    if indexed <= 0:
        return {
            "ready": False,
            "state": "empty",
            "why": "The provider is installed, but RVBBIT has not observed learning artifacts yet.",
            "actions": [
                {"tool": "run_sql", "sql": "SELECT * FROM rvbbit.system_learning_item_summary ORDER BY items DESC"},
            ],
        }
    if docs <= 0:
        return {
            "ready": False,
            "state": "needs_sync",
            "why": f"{indexed} learned artifact(s) exist, but none are indexed into Brain yet.",
            "actions": [{"tool": "sync_system_learning"}],
        }
    if errors > 0:
        return {
            "ready": False,
            "state": "degraded",
            "why": f"The last sync recorded {errors} error(s). Search may be incomplete.",
            "actions": [{"tool": "sync_system_learning"}, {"tool": "system_learning_status"}],
        }
    if docs < indexed:
        return {
            "ready": True,
            "state": "partial",
            "why": f"{docs} of {indexed} learned artifact(s) are indexed. Search works, but a sync may catch up.",
            "actions": [{"tool": "sync_system_learning"}],
        }
    return {
        "ready": True,
        "state": "ready",
        "why": f"{docs} learned artifact(s) are indexed and searchable.",
        "actions": [
            {"tool": "ask_system_learning", "query": _SYSTEM_LEARNING_SUGGESTED_PROMPTS[0]["query"]},
        ],
    }


def _system_learning_status_sql_followups() -> list[dict]:
    return [
        {
            "tool": "run_sql",
            "label": "Learning item summary",
            "sql": (
                "SELECT object_type, items, last_seen_at "
                "FROM rvbbit.system_learning_item_summary ORDER BY items DESC, object_type"
            ),
        },
        {
            "tool": "run_sql",
            "label": "Recent learned artifacts",
            "sql": (
                "SELECT uri, title, occurred_at, props "
                "FROM rvbbit.system_learning_items ORDER BY occurred_at DESC, title LIMIT 20"
            ),
        },
        {
            "tool": "run_sql",
            "label": "Brain sync state",
            "sql": "SELECT * FROM rvbbit.system_learning_brain_status",
        },
    ]


def tool_system_learning_status() -> dict:
    """What RVBBIT has learned about its own workload and agent corpus: artifact counts, sync state,
    graph edge handles, concrete breadcrumb examples, and the doc_type/source an MCP caller can
    search. This is the MCP-friendly mirror of the SQL Desktop's System Learning strip."""
    with _ro() as c:
        installed = c.execute(
            "SELECT to_regclass('rvbbit.system_learning_brain_status') IS NOT NULL AS ok"
        ).fetchone()["ok"]
        summary_installed = c.execute(
            "SELECT to_regclass('rvbbit.system_learning_item_summary') IS NOT NULL AS ok"
        ).fetchone()["ok"]
        if not installed:
            response = {
                "installed": False,
                "source": "RVBBIT System Learning",
                "doc_type": "system_learning",
                "summary": [],
                "breadcrumbs": [],
                "graph_edges": [],
                "agent_tools": ["system_learning_status", "sync_system_learning", "ask_system_learning"],
                "note": "Run rvbbit.migrate() to install the system-learning Brain provider.",
            }
            response["readiness"] = _system_learning_readiness(response)
            response["suggested_prompts"] = _SYSTEM_LEARNING_SUGGESTED_PROMPTS
            response["answer_contract"] = _system_learning_answer_contract()
            response["followups"] = [{"tool": "run_sql", "sql": "SELECT rvbbit.migrate()"}]
            return response
        status = c.execute(
            "SELECT installed, source_id, enabled, indexed_items, docs, "
            "last_synced_at::text AS last_synced_at, last_run_at::text AS last_run_at, "
            "last_run_added, last_run_changed, last_run_removed, last_run_skipped, "
            "last_run_errors, last_run_elapsed_sec "
            "FROM rvbbit.system_learning_brain_status"
        ).fetchone()
        summary = []
        if summary_installed:
            summary = c.execute(
                "SELECT object_type, items, last_seen_at::text AS last_seen_at "
                "FROM rvbbit.system_learning_item_summary ORDER BY items DESC, object_type"
            ).fetchall()
        provider = c.execute(
            "SELECT edge_map FROM rvbbit.brain_doc_providers WHERE provider = 'rvbbit-system-learning'"
        ).fetchone()
        breadcrumbs = c.execute(
            """
            WITH ranked AS (
                SELECT uri, title, occurred_at, body, props,
                       coalesce(props->>'object_type', 'unknown') AS object_type,
                       row_number() OVER (
                           PARTITION BY coalesce(props->>'object_type', 'unknown')
                           ORDER BY occurred_at DESC, title
                       ) AS rn
                FROM rvbbit.system_learning_items
            )
            SELECT uri, title, object_type, occurred_at::text AS occurred_at,
                   left(body, 700) AS preview,
                   jsonb_strip_nulls(jsonb_build_object(
                       'table', props->>'table',
                       'column', props->>'column',
                       'layout', props->>'layout',
                       'layout_kind', props->>'layout_kind',
                       'layout_status', props->>'layout_status',
                       'shape_key', props->>'shape_key',
                       'shape_family', props->>'shape_family',
                       'engine', props->>'engine',
                       'operator', props->>'operator',
                       'status', props->>'status',
                       'score', props->>'score',
                       'observations', props->>'observations'
                   )) AS handles
            FROM ranked
            WHERE rn <= 2
            ORDER BY object_type, occurred_at DESC, title
            LIMIT 12
            """
        ).fetchall()
    breadcrumbs = [_system_learning_breadcrumb(row) for row in breadcrumbs]
    response = {
        "installed": bool(status["installed"]) if status else False,
        "source_id": status["source_id"] if status else None,
        "enabled": bool(status["enabled"]) if status else False,
        "source": "RVBBIT System Learning",
        "doc_type": "system_learning",
        "indexed_items": status["indexed_items"] if status else 0,
        "docs": status["docs"] if status else 0,
        "last_synced_at": status["last_synced_at"] if status else None,
        "last_run": {
            "at": status["last_run_at"] if status else None,
            "added": status["last_run_added"] if status else 0,
            "changed": status["last_run_changed"] if status else 0,
            "removed": status["last_run_removed"] if status else 0,
            "skipped": status["last_run_skipped"] if status else 0,
            "errors": status["last_run_errors"] if status else 0,
            "elapsed_sec": status["last_run_elapsed_sec"] if status else None,
        },
        "summary": summary,
        "breadcrumbs": breadcrumbs,
        "graph_edges": (provider["edge_map"] if provider else []) or [],
        "agent_tools": ["system_learning_status", "sync_system_learning", "ask_system_learning", "run_sql"],
        "next_tools": ["ask_system_learning", "sync_system_learning", "run_sql"],
        "note": "Use breadcrumbs as handles: ask_system_learning for fuzzy context, run_sql for exact rvbbit.system_learning_items rows.",
    }
    response["readiness"] = _system_learning_readiness(response)
    response["suggested_prompts"] = _SYSTEM_LEARNING_SUGGESTED_PROMPTS
    response["answer_contract"] = _system_learning_answer_contract()
    response["followups"] = _system_learning_status_sql_followups()
    return response


def _system_learning_breadcrumb(row: dict) -> dict:
    handles = row.get("handles") or {}
    queries = []
    table = handles.get("table")
    column = handles.get("column")
    layout = handles.get("layout")
    shape_key = handles.get("shape_key")
    operator = handles.get("operator")
    engine = handles.get("engine")
    if table:
        queries.append(f"{table} acceleration workload")
    if table and column:
        queries.append(f"{table} {column} layout recommendation")
    if layout:
        queries.append(f"workload layout {layout}")
    if shape_key:
        queries.append(f"route shape {shape_key}")
    if engine:
        queries.append(f"{engine} routing performance")
    if operator:
        queries.append(f"operator {operator} trust receipts")
    if not queries:
        queries.append(str(row.get("title") or row.get("object_type") or "RVBBIT system learning"))
    uri = str(row.get("uri") or "")
    sql_uri = uri.replace("'", "''")
    inspect_sql = (
        "SELECT uri, title, occurred_at, body, props "
        f"FROM rvbbit.system_learning_items WHERE uri = '{sql_uri}'"
    )
    return {
        "uri": uri,
        "title": row.get("title"),
        "object_type": row.get("object_type"),
        "occurred_at": row.get("occurred_at"),
        "handles": handles,
        "preview": row.get("preview"),
        "inspect_sql": inspect_sql,
        "followups": [
            {"tool": "ask_system_learning", "query": queries[0]},
            {
                "tool": "run_sql",
                "sql": inspect_sql,
            },
        ],
    }


_SYSTEM_LEARNING_HANDLES_SQL = """
jsonb_strip_nulls(jsonb_build_object(
    'table', i.props->>'table',
    'column', i.props->>'column',
    'layout', i.props->>'layout',
    'layout_kind', i.props->>'layout_kind',
    'layout_status', i.props->>'layout_status',
    'shape_key', i.props->>'shape_key',
    'shape_family', i.props->>'shape_family',
    'engine', i.props->>'engine',
    'operator', i.props->>'operator',
    'status', i.props->>'status',
    'score', i.props->>'score',
    'observations', i.props->>'observations'
)) AS handles
"""


def _system_learning_breadcrumbs_for_docs(doc_ids: list[int]) -> dict[int, dict]:
    ids = sorted({int(doc_id) for doc_id in doc_ids if doc_id is not None})
    if not ids:
        return {}
    with _ro() as c:
        rows = c.execute(
            f"""
            SELECT d.doc_id, i.uri, i.title,
                   coalesce(i.props->>'object_type', 'unknown') AS object_type,
                   i.occurred_at::text AS occurred_at,
                   left(i.body, 700) AS preview,
                   {_SYSTEM_LEARNING_HANDLES_SQL}
            FROM rvbbit.brain_documents d
            JOIN rvbbit.system_learning_items i ON i.uri = d.uri
            WHERE d.doc_id = ANY(%s::bigint[])
            """,
            (ids,),
        ).fetchall()
    return {int(row["doc_id"]): _system_learning_breadcrumb(row) for row in rows}


def _attach_system_learning_breadcrumbs(result: dict) -> dict:
    if not isinstance(result, dict) or result.get("error"):
        return result

    doc_ids: list[int] = []
    for hit in result.get("hits", []):
        if isinstance(hit, dict) and hit.get("doc_id") is not None:
            doc_ids.append(hit["doc_id"])
    for doc in result.get("documents", []):
        if isinstance(doc, dict) and doc.get("doc_id") is not None:
            doc_ids.append(doc["doc_id"])

    try:
        breadcrumbs_by_doc = _system_learning_breadcrumbs_for_docs(doc_ids)
    except Exception as e:  # noqa: BLE001
        result["breadcrumb_error"] = str(e)
        return result

    seen = set()
    breadcrumbs = []
    for hit in result.get("hits", []):
        if not isinstance(hit, dict):
            continue
        artifact = breadcrumbs_by_doc.get(int(hit["doc_id"])) if hit.get("doc_id") is not None else None
        if artifact:
            hit["artifact"] = artifact
            if artifact["uri"] not in seen:
                seen.add(artifact["uri"])
                breadcrumbs.append(artifact)

    for doc in result.get("documents", []):
        if not isinstance(doc, dict):
            continue
        artifact = breadcrumbs_by_doc.get(int(doc["doc_id"])) if doc.get("doc_id") is not None else None
        if artifact:
            doc["artifact"] = artifact
            if artifact["uri"] not in seen:
                seen.add(artifact["uri"])
                breadcrumbs.append(artifact)

    result["breadcrumbs"] = breadcrumbs
    result["followups"] = [
        followup
        for breadcrumb in breadcrumbs[:5]
        for followup in breadcrumb.get("followups", [])
        if followup.get("tool") == "run_sql"
    ] or _system_learning_status_sql_followups()
    result["next_tools"] = ["ask_system_learning", "run_sql", "system_learning_status", "sync_system_learning"]
    result["suggested_prompts"] = _SYSTEM_LEARNING_SUGGESTED_PROMPTS
    result["answer_contract"] = _system_learning_answer_contract()
    try:
        result["readiness"] = tool_system_learning_status().get("readiness")
    except Exception as e:  # noqa: BLE001
        result["readiness_error"] = str(e)
    result["note"] = (
        "Grounded system-learning context, not an answer. Each hit/document may include an `artifact` "
        "with handles and followups; use run_sql followups for exact rvbbit.system_learning_items rows."
    )
    return result


def tool_sync_system_learning() -> dict:
    """Refresh RVBBIT System Learning into the Brain. This syncs learned workload layouts, route
    shapes, acceleration state/candidates, and operator trust artifacts so MCP agents search the same
    breadcrumbs the SQL Desktop shows."""
    with _conn() as c:
        try:
            source = c.execute(
                "SELECT source_id FROM rvbbit.brain_sources WHERE label = 'RVBBIT System Learning'"
            ).fetchone()
            if not source:
                return {"error": {"code": "NOT_INSTALLED", "message": "RVBBIT System Learning source is not installed; run rvbbit.migrate()"}}
            result = c.execute(
                "SELECT rvbbit.brain_sync_dispatch(%s, 'mcp') AS r", (source["source_id"],)
            ).fetchone()["r"]
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "SYNC_SYSTEM_LEARNING_FAILED", "message": str(e)}}
    status = tool_system_learning_status()
    return {"source": "RVBBIT System Learning", "result": result or {}, "status": status}


async def _mcp_sync_system_learning():
    """Run the potentially expensive Brain reconciliation off the ASGI loop.

    FastMCP executes ordinary ``def`` tools inline on its request/event loop.
    System Learning can scan a large workload catalog and reconcile many Brain
    documents, so registering its synchronous implementation directly makes
    unrelated Calliope HTTP routes and MCP keepalives wait for the whole sync.
    ``asyncio.to_thread`` preserves request ContextVars while allowing the
    server to continue serving the UI and other MCP sessions.
    """
    return await asyncio.to_thread(
        _logged, "sync_system_learning", {}, tool_sync_system_learning
    )


def tool_ask_system_learning(query, k=8, caller_email=None) -> dict:
    """Ask what RVBBIT has learned about this database. This is the agent-safe shortcut over
    ask_brain(filters={"type":["system_learning"]}) so callers do not need to remember the doc_type
    name. Results include workload/layout/routing/acceleration/operator breadcrumbs, not a synthesized
    answer. Compose an answer from the returned chunks and cite titles."""
    effective_email = caller_email or "mcp-system-learning@rvbbit.local"
    result = tool_ask_brain(
        query,
        k,
        {"type": ["system_learning"]},
        effective_email,
    )
    return _attach_system_learning_breadcrumbs(result)


def tool_brain_ingest(source, title, body, roles=None, folder=None, uri=None,
                      author=None, occurred_at=None) -> dict:
    """Ingest a document into the brain (operator action): chunks + embeds it and assigns access role(s).
    roles = the roles allowed to see it (omit → the source's default roles → if none, DEFAULT-DENY:
    nobody can see it until granted a role). folder = its file-explorer path. Returns the doc_id."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.brain_ingest(%s, %s, %s, %s::text[], %s, %s, %s, %s::timestamptz) AS id",
                (source, title, body, roles, folder, uri, author, occurred_at)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "INGEST_FAILED", "message": str(e)}}
    return {"doc_id": row["id"] if row else None, "source": source, "title": title, "roles": roles}


def tool_wiki_write_page(slug, title, body, tags=None, claim_fingerprints=None,
                         sources=None, author=None, subject_kind=None,
                         subject_key=None, caller_email=None) -> dict:
    """Write (or revise) a shared wiki page of working knowledge: procedures, gotchas, data caveats,
    operational patterns — the narrative that structured claims can't hold. Adopt-first: the page is
    served as a provisional working assumption immediately; no approval step. Pass claim_fingerprints
    (from business semantic assertions) to let the Evidence Lab flag the page if a linked claim is
    later contradicted. Rewriting a demoted/flagged page resolves the flag and revives it. Slug is
    kebab-case and stable — reuse it to revise, not to fork."""
    author_key = (author or caller_email or "unknown").strip()
    author_kind = "agent" if author else "human"
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.wiki_write_page(%s, %s, %s, %s, %s, %s::text[], %s::text[], "
                "%s::jsonb, %s, %s) AS result",
                (slug, title, body, author_kind, author_key,
                 tags or [], claim_fingerprints or [],
                 json.dumps(sources or []), subject_kind, subject_key)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "WIKI_WRITE_FAILED", "message": str(e)}}
    return row["result"] if row else {"error": {"code": "WIKI_WRITE_FAILED", "message": "no result"}}


def tool_wiki_read_page(slug) -> dict:
    """Read one wiki page in full (body, author, adoption state, Evidence-Lab verdict of linked
    claims, revision). A page in state auto_provisional is a working assumption — say so when
    leaning on it, and invite correction."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT page.slug, page.title, page.body, page.author_kind, page.author_key, "
                "page.tags, page.adoption_state, page.flagged_at, page.flag_reason, "
                "page.revision, page.updated_at::text, page.sources, "
                "verdict.linked_claims, verdict.supported, verdict.contradicted "
                "FROM rvbbit.wiki_pages page "
                "LEFT JOIN rvbbit.wiki_page_verdicts verdict USING (page_id) "
                "WHERE page.slug=%s", (slug,)).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "WIKI_READ_FAILED", "message": str(e)}}
    if not row:
        return {"error": {"code": "NOT_FOUND", "message": f"no wiki page with slug {slug!r}"}}
    return dict(row)


def tool_wiki_list_pages(author=None, state=None, flagged_only=False, k=40) -> dict:
    """List wiki pages (title, author, state, flag, verdict counts) — newest first. Filter by
    author key, adoption state, or flagged_only=true for the pages needing gardener attention."""
    clauses, params = [], []
    if author:
        clauses.append("page.author_key=%s")
        params.append(author)
    if state:
        clauses.append("page.adoption_state=%s")
        params.append(state)
    if flagged_only:
        clauses.append("page.flagged_at IS NOT NULL")
    where = ("WHERE " + " AND ".join(clauses)) if clauses else ""
    with _conn() as c:
        try:
            rows = c.execute(
                "SELECT page.slug, page.title, page.author_kind, page.author_key, "
                "page.adoption_state, page.flag_reason, page.revision, page.updated_at::text, "
                "verdict.linked_claims, verdict.contradicted "
                "FROM rvbbit.wiki_pages page "
                "LEFT JOIN rvbbit.wiki_page_verdicts verdict USING (page_id) "
                f"{where} ORDER BY page.updated_at DESC LIMIT %s",
                (*params, max(1, min(int(k or 40), 200)))).fetchall()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "WIKI_LIST_FAILED", "message": str(e)}}
    return {"count": len(rows), "pages": [dict(r) for r in rows]}


def tool_wiki_set_page_state(slug, state, reason=None, caller_email=None) -> dict:
    """Demote ('demoted'), retire ('retired'), or revive ('auto_provisional') a wiki page. An
    explicit human 'this is wrong' should demote; the gardener resolves flags by rewriting the
    page instead. Retired slugs stay retired until explicitly revived."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.wiki_set_page_state(%s, %s, %s, %s) AS result",
                (slug, state, reason, caller_email or "operator")).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "WIKI_STATE_FAILED", "message": str(e)}}
    return row["result"] if row else {"error": {"code": "WIKI_STATE_FAILED", "message": "no result"}}


def tool_agent_overlay_propose(agent_key, target_kind, section, body, kind,
                               rationale, target_key=None, sources=None,
                               author=None, caller_email=None) -> dict:
    """Propose a learned overlay block for an agent's SOUL ('soul') or one of its skills
    ('skill' + target_key). kind='knowledge' (additive facts/gotchas — adopts provisionally at
    once) or kind='behavior' (changes how the agent acts — waits for explicit operator adoption).
    The overlay composes beneath the repo baseline at the next reconcile; it never edits the
    baseline. A body identical to a previously rejected/demoted overlay is refused with the
    prior reason — revise it against that reason instead of re-proposing."""
    proposer = (author or caller_email or "unknown").strip()
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.agent_overlay_propose(%s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb) AS result",
                (agent_key, target_kind, target_key, section, body, kind,
                 rationale, proposer, json.dumps(sources or []))).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "OVERLAY_PROPOSE_FAILED", "message": str(e)}}
    return row["result"] if row else {"error": {"code": "OVERLAY_PROPOSE_FAILED", "message": "no result"}}


def tool_agent_overlay_list(agent_key=None, state=None, k=50) -> dict:
    """List agent overlays (SOUL/skill learned blocks) with state and audit context. Filter by
    agent_key or adoption state ('proposed' = behavior overlays awaiting operator adoption)."""
    clauses, params = [], []
    if agent_key:
        clauses.append("agent_key=%s")
        params.append(agent_key)
    if state:
        clauses.append("adoption_state=%s")
        params.append(state)
    where = ("WHERE " + " AND ".join(clauses)) if clauses else ""
    with _conn() as c:
        try:
            rows = c.execute(
                "SELECT overlay_id::text, agent_key, target_kind, target_key, section, "
                "kind, adoption_state, rationale, proposed_by, created_at::text, "
                "left(body, 400) AS body_preview "
                f"FROM rvbbit.agent_overlays {where} "
                "ORDER BY created_at DESC LIMIT %s",
                (*params, max(1, min(int(k or 50), 200)))).fetchall()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "OVERLAY_LIST_FAILED", "message": str(e)}}
    return {"count": len(rows), "overlays": [dict(r) for r in rows]}


def tool_agent_overlay_set_state(overlay_id, state, reason=None, caller_email=None) -> dict:
    """Adopt ('auto_provisional'), affirm, demote, retire, or reject an overlay. Adopting a
    'proposed' behavior overlay is the operator gate; rejections record the reason into the
    audit ledger so the same idea cannot be silently re-proposed. Adopted overlays reach the
    agent at the next Hermes reconcile (container restart or deploy)."""
    with _conn() as c:
        try:
            row = c.execute(
                "SELECT rvbbit.agent_overlay_set_state(%s::uuid, %s, %s, %s) AS result",
                (overlay_id, state, reason, caller_email or "operator")).fetchone()
        except Exception as e:  # noqa: BLE001
            return {"error": {"code": "OVERLAY_STATE_FAILED", "message": str(e)}}
    return row["result"] if row else {"error": {"code": "OVERLAY_STATE_FAILED", "message": "no result"}}


def _image_stage_destination(owner):
    """Capture the exact live turn before generation, using trusted provenance.

    Never infer a destination from an email's most recent chat. A specialist
    may finish after its parent turn, so retain its recorded source turn.
    """
    authorization = _AUTHORIZATION_CONTEXT.get()
    if (authorization is None or authorization.subject != owner
            or not _is_trusted_hermes_transport(authorization.client_id)
            or not authorization.session_ref):
        return None
    with _conn() as conn:
        available = conn.execute(
            "SELECT to_regclass('rvbbit.calliope_turns') AS turns, "
            "to_regclass('rvbbit.calliope_specialist_runs') AS runs"
        ).fetchone() or {}
        if not available.get("runs") or not available.get("turns"):
            return None
        rows = conn.execute(
            "SELECT s.id::text AS session_id,t.id::text AS turn_id "
            "FROM rvbbit.calliope_sessions s JOIN rvbbit.calliope_turns t ON t.session_id=s.id "
            "WHERE s.hermes_session_id=%s AND t.author_email=%s AND t.status='running' "
            "UNION "
            "SELECT r.source_session_id::text,r.source_turn_id::text "
            "FROM rvbbit.calliope_specialist_runs r "
            "JOIN rvbbit.calliope_turns t ON t.id=r.source_turn_id AND t.session_id=r.source_session_id "
            "WHERE r.hermes_session_id=%s AND r.owner_email=%s AND r.status='running'",
            (authorization.session_ref, owner, authorization.session_ref, owner),
        ).fetchall()
    return dict(rows[0]) if len(rows) == 1 else None


def _page_refresh_tool(run_id, outcome=None, body="", summary=""):
    import calliope_pages
    owner = _caller()[0]
    destination = _image_stage_destination(owner)
    if not destination:
        return {"error": {"code": "PAGE_CONTEXT_REQUIRED", "message": "Use this tool in the Page refresh turn."}}
    try:
        if outcome is None:
            return calliope_pages.read_refresh(_conn, owner, run_id, destination)
        return calliope_pages.finish_refresh(_conn, owner, run_id, destination, outcome, body, summary)
    except calliope_pages.PageError as exc:
        return {"error": {"code": exc.code, "message": str(exc)}}


def _mcp_read_page_refresh(run_id: str):
    """Read the standing brief, current document and caller-visible cited Brain evidence
    for a requested living Page refresh. Use the run_id supplied by the refresh request.
    This is read-only and only works in that Page's initiating turn. Finish with
    finish_page_refresh; conversational completion alone does not save the Page."""
    return _logged('read_page_refresh', {'run_id': run_id}, lambda: _page_refresh_tool(run_id))


def _mcp_finish_page_refresh(run_id: str, outcome: str, summary: str, body: str = ""):
    """Finish a requested living Page refresh. First read_page_refresh. outcome is
    updated (complete Markdown body with supplied [N] citations), unchanged (verified
    current), or incomplete (cannot verify). summary describes material changes or
    the reason for no update. Retains the previous revision on incomplete work. Source
    access, source versions, initiating turn and standing brief are checked before save.
    This tool only saves the Page; it does not authorize source-system mutations."""
    return _logged('finish_page_refresh', {'run_id': run_id, 'outcome': outcome},
                   lambda: _page_refresh_tool(run_id, outcome, body, summary))


def _calliope_page_tool(action, **args):
    import calliope
    import calliope_pages as pages
    owner = _caller()[0]
    destination = _image_stage_destination(owner)
    create_session = lambda who, title: calliope._create_session_record_sync(
        calliope.CalliopeConfig.from_env(), _conn, who, "Page · " + title)
    try:
        if action == 'list':
            query = str(args.get('query') or '').casefold()
            return {'pages': [p for p in pages.list_pages(_conn, owner)
                              if query in (p['title'] + ' ' + p['question']).casefold()][:100]}
        if action == 'read':
            if args.get('version') is not None:
                return {'revision': pages.read_revision(_conn, owner, args['page_id'], args['version'])}
            return {'page': pages.get_page(_conn, owner, args['page_id'])}
        with _conn() as conn:
            pages._require_tool_turn(conn, owner, destination)
        if action == 'update':
            return {'page': pages.update_definition(_conn, owner, **args),
                    'next': 'Definition saved. If the document needs revision, use refresh_calliope_page with this definition.'}
        if action == 'archive':
            pages.archive_page(_conn, owner, **args)
            return {'archived': True, 'page_id': args['page_id']}
        page = (pages.create_from_tool(_conn, owner, destination, **args) if action == 'create'
                else pages.get_page(_conn, owner, args['page_id']))
        # Creating the notebook does not launch another agent; this turn writes
        # through the same evidence contract as the browser Refresh action.
        page = pages.ensure_notebook(_conn, owner, page['id'], create_session)
        result = {'page': page, 'open_url': '/calliope?session=' + str(page['session_id']) + '&view=zen'}
        try:
            run = pages.begin_refresh(_conn, owner, page['id'], create_session, destination)
            result['refresh_contract'] = pages.read_refresh(_conn, owner, run['id'], destination)
        except pages.PageError as exc:
            result['refresh_error'] = {'code': exc.code, 'message': str(exc)}
        result['page'] = pages.get_page(_conn, owner, page['id'])
        return result
    except pages.PageError as exc:
        return {'error': {'code': exc.code, 'message': str(exc)}}


def _mcp_create_calliope_page(title: str, question: str, standing_brief: str = "", anchor_label: str = ""):
    """Create a private living Page for the caller, with its own reusable notebook.
    question is the enduring question; standing_brief describes sections, emphasis
    and scope. anchor_label optionally names a project/person/topic for evidence.
    Returns the Page link and a refresh_contract of caller-visible source evidence.
    Write the first revision HERE using finish_page_refresh and that contract's
    run_id and [N] citations. Do not spawn a second agent or use wiki/SQL/file tools
    to save it. Missing evidence leaves a saved empty Page with refresh_error.
    Retrying the same title in this turn reuses the Page. Surface its open_url."""
    return _logged('create_calliope_page', {'title': title}, lambda: _calliope_page_tool(
        'create', title=title, question=question, standing_brief=standing_brief, anchor_label=anchor_label))


def _mcp_list_calliope_pages(query: str = ""):
    """Find the caller's private living Pages by title or enduring question. Returns
    IDs, notebook session IDs, revision and refresh status. Not the shared agent wiki."""
    return _logged('list_calliope_pages', {'query': query}, lambda: _calliope_page_tool('list', query=query))


def _mcp_read_calliope_page(page_id: str, version: int | None = None):
    """Read a private living Page, its definition_version, standing brief, saved
    document, sources and history. Optional version reads a historical revision.
    Source access is rechecked; revoked evidence never exposes the old body."""
    return _logged('read_calliope_page', {'page_id': page_id, 'version': version},
                   lambda: _calliope_page_tool('read', page_id=page_id, version=version))


def _mcp_update_calliope_page(page_id: str, expected_version: int, title: str | None = None,
                             question: str | None = None, standing_brief: str | None = None,
                             anchor_label: str | None = None):
    """Update a living Page's enduring definition. Read it first and pass its
    definition_version as expected_version. Omitted fields are preserved. This
    changes the brief, not the saved document: use refresh_calliope_page afterward
    to obtain cited evidence, then finish_page_refresh to save revised content."""
    return _logged('update_calliope_page', {'page_id': page_id, 'expected_version': expected_version},
        lambda: _calliope_page_tool('update', page_id=page_id, expected_version=expected_version,
            title=title, question=question, standing_brief=standing_brief, anchor_label=anchor_label))


def _mcp_refresh_calliope_page(page_id: str):
    """Prepare a cited living Page refresh in THIS conversation turn. Returns
    refresh_contract with run_id, standing brief, previous document and fresh
    caller-visible evidence. Synthesize here, then finish_page_refresh with [N]
    citations. Does not launch another agent. Retrying reuses this turn's run;
    if already finished, report its outcome rather than executing again."""
    return _logged('refresh_calliope_page', {'page_id': page_id},
                   lambda: _calliope_page_tool('refresh', page_id=page_id))


