def tool_publish_map(title, queries, sources, layers, viewport=None, size='wide', height=420,
                     row_limit=5000, replaces_surface_id=None, caller_email=None):
    import stage_maps
    destination = _image_stage_destination(caller_email)
    if not destination:
        return {'error': {'code': 'NO_STAGE_CONTEXT', 'message': 'Publish from an active Calliope or specialist turn.'}}
    try:
        if not MAPBOX_TOKEN:
            raise ValueError('Maps are not configured on this appliance (no Mapbox token)')
        payload = stage_maps.validate(title, queries, sources, layers, viewport, size, height, row_limit)
        for name, sql in queries.items():
            check = tool_validate_sql(sql)
            if not check.get('valid') or not check.get('safe_select'):
                raise ValueError(f"{name}: {check.get('error') or check.get('reason') or 'requires read-only SELECT'}")
        return stage_maps.publish(_conn, destination, title, payload, replaces_surface_id)
    except (ValueError, TypeError) as exc:
        return {'error': {'code': 'MAP_PUBLICATION_FAILED', 'message': str(exc)[:1000]}}


def tool_read_map(surface_id, caller_email):
    import stage_maps
    return stage_maps.read(_conn, surface_id, caller_email)


def tool_update_map(surface_id, caller_email=None, **changes):
    saved = tool_read_map(surface_id, caller_email)
    if saved.get('error'):
        return saved
    if saved['latest_surface_id'] != str(surface_id):
        return {'error': {'code': 'MAP_SUPERSEDED', 'message': 'Read and update the current revision.', 'latest_surface_id': saved['latest_surface_id']}}
    fields = {k: changes.get(k) if changes.get(k) is not None else saved[k]
              for k in ('title', 'queries', 'sources', 'layers', 'viewport', 'size', 'height', 'row_limit')}
    return tool_publish_map(**fields, replaces_surface_id=surface_id, caller_email=caller_email)


def _mcp_publish_map(title: str, queries: dict[str, str], sources: dict, layers: list[dict],
                     viewport: dict | None = None, size: str = 'wide', height: int = 420,
                     row_limit: int = 5000, replaces_surface_id: str | None = None):
    """Publish a declarative SQL-backed Mapbox map directly to the Stage. No HTML, JS or token required.
    queries maps dataset names to read-only SELECT SQL, executed under the viewer on open/refresh.
    sources maps source IDs to {dataset:'query_name',longitude:'lon_column',latitude:'lat_column'}
    OR {dataset:'query_name',geometry:'geojson_geometry_column'} for Point/MultiPoint, LineString/
    MultiLineString, Polygon/MultiPolygon. Coordinates must already exist; no automatic geocoding.
    Each source may include tooltip:['name','value'] and point clustering options cluster:true,
    clusterRadius:50, clusterMaxZoom:14. Cluster labels/count styling uses native Mapbox layers.
    layers is an array of native Mapbox {id,type,source,paint,layout,filter,minzoom,maxzoom} objects.
    Supported types: circle, heatmap, line, fill, fill-extrusion, symbol. Native JSON expressions
    (get, match, case, step, interpolate) work in paint/layout/filter. No callbacks, external sources,
    custom JS or HTML. Use @accent, @positive, @warning, @danger, @text for theme paint colors;
    omitted colors receive theme defaults. Basemap automatically follows the current UI theme.
    viewport defaults to {fit:'data'}; alternatively set center:[lon,lat],zoom,pitch,bearing.
    size compact=one Stage column, wide=two, full=all; height is 240–900 pixels, default 420.
    Up to 8 SQL datasets and 24 layers; row_limit defaults to 5000, max 20000 (aggregate large data).
    Invalid geometry is counted visibly; all-invalid nonempty sources fail with a diagnostic.
    Use read_map to inspect the saved spec and browser render receipt, and update_map to repair
    in place while preserving revisions. Browser failures report automatically with bounded dedupe.
    Publication validates the contract and SQL, not successful tile loading or analytical correctness.
    Works for Calliope and specialists in their parent Stage. See dashboard_template maps for general
    native Mapbox guidance; use this tool instead of writing an HTML page for a standalone map.
    """
    return _logged('publish_map', {'title': title, 'queries': queries, 'size': size},
                   lambda: tool_publish_map(title, queries, sources, layers, viewport, size, height,
                                            row_limit, replaces_surface_id, _caller()[0]))


def _mcp_read_map(surface_id: str):
    """Read a Stage map's SQL, sources, native Mapbox layers, viewport, latest revision ID and
    render_receipt/last_render_error. Does not execute queries. No receipt means no owner browser
    has reported yet. Use update_map on latest_surface_id to repair without stacking visible maps."""
    return _logged('read_map', {'surface_id': surface_id}, lambda: tool_read_map(surface_id, _caller()[0]))


def _mcp_update_map(surface_id: str, title: str | None = None, queries: dict[str, str] | None = None,
                    sources: dict | None = None, layers: list[dict] | None = None, viewport: dict | None = None,
                    size: str | None = None, height: int | None = None, row_limit: int | None = None):
    """Revise an existing Stage map, preserving its lineage and showing only its latest revision.
    Read it first with read_map. Omitted fields are retained; supplied sources/layers/queries replace
    those whole objects. Same declarative contract as publish_map; no JS. Requires an active turn
    in the map's own chat. Stale revisions are rejected. Use render_receipt for targeted repairs."""
    return _logged('update_map', {'surface_id': surface_id},
                   lambda: tool_update_map(surface_id, _caller()[0], title=title, queries=queries,
                                           sources=sources, layers=layers, viewport=viewport, size=size,
                                           height=height, row_limit=row_limit))


