def _stage_capture_result(surface_id, owner, automatic=False, origin=None):
    import stage_capture
    target, _ = stage_capture.load(_conn, surface_id, owner)
    origin = origin or owner
    # One capture per immutable revision, bounded per originating turn. Reserve
    # a separate budget for assembled boards so child charts cannot starve it.
    with _conn() as conn, conn.transaction():
        conn.execute('SELECT pg_advisory_xact_lock(hashtextextended(%s,0))', ('stage-review:' + target['turn_id'],))
        row = conn.execute('SELECT payload FROM rvbbit.calliope_surfaces WHERE id=%s::uuid FOR UPDATE', (surface_id,)).fetchone()
        prior = (row['payload'] or {}).get('visual_review')
        if automatic and prior:
            return {**prior, 'paths': [], 'reused': True}
        if automatic:
            used = conn.execute("SELECT count(*) AS n FROM rvbbit.calliope_surfaces WHERE turn_id=%s::uuid "
                                "AND kind=%s AND payload#>>'{visual_review,origin}'=%s", (target['turn_id'], target['kind'], origin)).fetchone()['n']
            if used >= 3:
                return {'status': 'budget_reached', 'paths': [], 'message': 'Automatic review budget reached. Publication is saved; request capture_stage_surface only for a necessary focused check.'}
        conn.execute("UPDATE rvbbit.calliope_surfaces SET payload=payload || %s::jsonb WHERE id=%s::uuid",
                     (json.dumps({'visual_review': {'status': 'pending', 'surface_id': surface_id, 'origin': origin}}), surface_id))
    try:
        result = stage_capture.capture(_conn, surface_id, owner, _live_app_capture_root())
    except Exception as exc:
        result = {'surface_id': surface_id, 'status': 'unavailable', 'paths': [],
                  'message': str(exc)[:500] + '. Publication is saved; this is not a visual pass.'}
    public = {k: v for k, v in result.items() if k != 'paths'}
    public['origin'] = origin
    with _conn() as conn:
        conn.execute("UPDATE rvbbit.calliope_surfaces SET payload=payload || %s::jsonb WHERE id=%s::uuid",
                     (json.dumps({'visual_review': public}), surface_id))
    return result


def _with_authorization(fn):
    """Run ``fn`` with the request's authorization decided, as ``_logged`` does.

    Before that, ``_caller()`` on a Hermes service token is the service
    identity, not the person the turn acts for, and that identity cannot see
    their chat: a capture asked as it found no chart or board.
    """
    token = None
    if _AUTHORIZATION_CONTEXT.get() is None:
        token = _AUTHORIZATION_CONTEXT.set(_application_authorization_context())
    try:
        return fn()
    finally:
        if token is not None:
            _AUTHORIZATION_CONTEXT.reset(token)


async def _stage_publish_logged(tool, args, thunk, *, defer=False):
    # Capture runs in a worker so SQL-backed renders cannot deadlock the HTTP loop.
    result = await asyncio.to_thread(_logged, tool, args, thunk)
    if not isinstance(result, dict) or result.get('error') or not result.get('surface_id'):
        return result
    if defer:
        result['visual_review'] = {'status': 'deferred', 'message': 'Review this chart inside the assembled board; publish_board returns the render.'}
        return result

    def review_as_caller():
        owner = _caller()[0]
        origin = str((_hermes_mcp_envelope() or {}).get('session_id') or owner)
        return _stage_capture_result(result['surface_id'], owner, True, origin)
    try:
        review = await asyncio.to_thread(_with_authorization, review_as_caller)
    except Exception as exc:
        review = {'status': 'unavailable', 'paths': [], 'message': str(exc)[:500] + '. Publication is saved.'}
    result['visual_review'] = {k: v for k, v in review.items() if k != 'paths'}
    from mcp.server.fastmcp import Image
    return [result, *[Image(path=p) for p in review.get('paths', [])]] if review.get('paths') else result


async def _mcp_capture_stage_surface(surface_id: str):
    """Return clean rendered images of one chart or board in the current chat, without using Desktop.
    Usually unnecessary: publish/update already returns images. Use for an explicit visual check
    or after a failed capture. Tall boards include an overview and readable sections. Check
    status/clipped/errors before claiming verification. This reads live chart data but changes no SQL.
    """
    def capture():
        import stage_capture
        # Inside _logged, so this is the person, not the Hermes service token.
        owner = _caller()[0]
        destination = _image_stage_destination(owner)
        target, _ = stage_capture.load(_conn, surface_id, owner)
        if not destination or target['session_id'] != destination['session_id']:
            return {'error': {'code': 'NO_STAGE_CONTEXT', 'message': 'Choose a chart or board in this chat.'}}
        return _stage_capture_result(surface_id, owner)
    result = await asyncio.to_thread(_logged, 'capture_stage_surface', {'surface_id': surface_id}, capture)
    from mcp.server.fastmcp import Image
    paths = result.pop('paths', [])
    return [result, *[Image(path=p) for p in paths]] if paths else result


