def _hermes_admin_subject() -> str:
    authorization = _require_application_subject()
    with _conn() as conn:
        if not application_teams._is_admin(conn, authorization.subject):
            raise PermissionError(
                "Only a verified human member of the Admins Team may administer Hermes."
            )
    return authorization.subject


def _mcp_search_hermes_docs(query: str, limit: int = 8):
    """Search the exact, pre-enriched Hermes docs shipped with this appliance.

    Use this before changing Hermes messaging, gateway, profile, cron, plugin,
    or YAML settings. Results identify upstream pinned documentation separately
    from Calliope hosted-policy overlays. This corpus is not Company Brain and
    is never rebuilt on the customer appliance.
    """
    def search():
        result = {"results": hermes_config.docs_search(_conn, query, limit)}
        if re.search(r'\b(email|gmail|mailbox|imap|smtp)\b', query, re.I):
            result['calliope_setup'] = {
                'source_kind': 'calliope_overlay', 'action_id': 'email.connect',
                'message': 'For Calliope mailbox setup, use administer_calliope_action with the current session_id, action_id email.connect and optional inputs.address. It opens the native secure connection card in the human conversation. Finish your turn; submitting the app password there tests IMAP/SMTP and resumes the conversation. Do not use the desktop or enable the upstream Hermes automatic email responder for reviewed Calliope correspondence.',
            }
        if re.search(r'\b(sms|twilio|mms|text messaging)\b', query, re.I):
            result['calliope_sms_setup'] = {
                'source_kind': 'calliope_overlay', 'action_id': 'sms.connect',
                'message': 'Use administer_calliope_action with the current session_id and sms.connect to open the secure Twilio form. Then use sms.user to link each allowed phone to an EXISTING Calliope login. No token in chat, desktop setup, environment editing, or separate Hermes SMS listener. Incoming texts automatically start/resume a Floor conversation as that user. Replies go automatically to the same phone; email drafts still require native send approval. Use calliope_sms_status to inspect your connection and delivery status.',
            }
        return result
    return _logged(
        "search_hermes_docs",
        {"query": query, "limit": limit},
        search,
    )


