def _mcp_validate_hermes_config(
    config_yaml: str, secret_bindings: dict | None = None
):
    """Validate candidate Hermes YAML without changing or restarting anything.

    Admin-only. Validation uses both the exact pinned Hermes validator and the
    Calliope hosted invariants. `secret_bindings` maps environment names to
    canonical RVBBIT credential refs; the name may be referenced as
    `${env:NAME}` in YAML or consumed natively by a Hermes messaging adapter.
    Never pass a secret value.
    """
    return _logged(
        "validate_hermes_config",
        {"config_hash": hashlib.sha256(str(config_yaml).encode()).hexdigest()},
        lambda: (
            _hermes_admin_subject(),
            hermes_config.validate(config_yaml, secret_bindings),
        )[1],
    )


def _mcp_apply_hermes_config(
    config_yaml: str,
    reason: str,
    secret_bindings: dict | None = None,
):
    """Validate and queue a secret-free Hermes configuration revision.

    Admin-only mutation. The call returns before Hermes restarts. An independent
    controller resolves canonical credentials in memory, restarts the gateway,
    verifies its API, command catalog, and Warehouse bridge, and automatically
    restores the last-good YAML if verification fails. This is direct appliance
    administration and needs no separate plan ceremony.
    """
    def apply():
        actor = _hermes_admin_subject()
        return hermes_config.queue_apply(
            _conn,
            config_yaml,
            reason=reason,
            actor=actor,
            secret_bindings=secret_bindings,
        )

    return _logged(
        "apply_hermes_config",
        {
            "config_hash": hashlib.sha256(str(config_yaml).encode()).hexdigest(),
            "reason": reason,
            "secret_binding_names": sorted((secret_bindings or {}).keys()),
        },
        apply,
    )


def _mcp_restore_hermes_config(revision_id: str, reason: str = ""):
    """Queue a previous secret-free Hermes revision as a new verified revision.

    Admin-only mutation. The original revision remains immutable and the same
    automatic verification/rollback path is used.
    """
    def restore():
        actor = _hermes_admin_subject()
        return hermes_config.restore(
            _conn, revision_id, actor=actor, reason=reason
        )

    return _logged(
        "restore_hermes_config",
        {"revision_id": revision_id, "reason": reason},
        restore,
    )


def _mcp_restart_hermes_gateway(reason: str = ""):
    """Restart Hermes through the verified last-good configuration path.

    Admin-only mutation. This rehydrates canonical credential bindings and does
    not expose Docker, a shell, or the Hermes UI.
    """
    def restart():
        actor = _hermes_admin_subject()
        return hermes_config.restart(_conn, actor=actor, reason=reason)

    return _logged("restart_hermes_gateway", {"reason": reason}, restart)


