def _mcp_brain_ingest_file(path: str, source: str, roles: list[str] | None = None,
                           folder: str | None = None):
    """Import a staged text/Markdown, EML, or document JSON/JSONL file into Company Brain.

    Uses the existing Brain connection; no credentials, Fletch or desktop needed.
    Files live in the shared Hermes workspace/outputs or configured Brain import roots.
    JSONL records need title (or subject), body, and stable uri (or message_id);
    optional author/occurred_at preserve correspondence metadata. Normalize other
    formats in the workspace first. Choose ONE representation of each document or
    email, not JSONL plus EML plus MBOX. Stable source+URI makes retries idempotent.
    Use only for requested ingestion; roles use the source defaults if omitted.
    Inspect the source's access roles so the intended audience can retrieve it.
    For a text-document folder use brain_crawl_folder; tabular data uses import_local_file.
    """
    def ingest():
        import file_imports
        label = str(source or '').strip()
        if not label:
            raise ValueError('Provide a Company Brain source label')
        source_path, data = file_imports.read_source(path, 'WAREHOUSE_BRAIN_IMPORT_ROOTS')
        records = list(file_imports.document_records(source_path, data))
        if len(records) > 5000:
            raise ValueError('Split the document manifest into batches of at most 5000 records')
        docs, errors = [], []
        for record in records:
            result = tool_brain_ingest(label, roles=roles, folder=folder, **record)
            if result.get('error'):
                errors.append({'uri': record['uri'], 'error': result['error']})
            else:
                docs.append({'doc_id': result['doc_id'], 'title': record['title']})
        result = {'source': label, 'path': str(source_path), 'sha256': hashlib.sha256(data).hexdigest(),
                'ingested': len(docs), 'failed': len(errors), 'docs': docs[:50], 'errors': errors[:10],
                'note': 'Source defaults apply; verify access roles before testing retrieval.' if roles is None else None}
        if errors:
            result['error'] = {'code': 'BRAIN_FILE_PARTIAL_IMPORT', 'message': 'Some documents failed; inspect errors and retry with the same source and URIs.'}
        return result
    return _logged('brain_ingest_file', {'path': path, 'source': source, 'roles': roles}, ingest)


