def _mcp_live_app_status(slug=None):
    """Inspect local live-app runner state for one app or every running app."""
    if slug:
        return _logged(
            "live_app_status", {"slug": slug},
            lambda: _artifact_view_result(slug, lambda: tool_live_app_status(slug)),
        )

    def visible_statuses():
        subject = _artifact_authorization().subject
        with _conn() as conn:
            allowed = {
                row["slug"] for row in conn.execute(
                    "SELECT slug FROM rvbbit.dashboards "
                    "WHERE rvbbit.artifact_can_view(id,%s,false)",
                    (subject,),
                ).fetchall()
            }
        return {
            "live_apps": [
                _live_app_runner_status(candidate, probe=False)
                for candidate in sorted(_LIVE_APP_PROCS)
                if candidate in allowed
            ]
        }

    return _logged("live_app_status", {"slug": None}, visible_statuses)


async def _mcp_capture_live_app(slug, path=None, width=1440, height=900, full_page=True, start=True,
                                wait_ms=750, return_image=False, data_timeout_ms=None):
    """Capture a PNG screenshot of a live app. Omit path for normal use.
    path is an OUTPUT IMAGE FILENAME (.png/.jpg) on the server, NOT a URL or /apps/ route;
    the receipt always returns a separate retained capture so filename reuse cannot replace it.
    slug identifies the page. Capture the final published version.
    Native a2ui apps render their exact saved app.json with governed server reads
    and simulated actions in the Web renderer. Their receipt includes preview
    hashes/readiness. Use capture_ui_app for paired Web/GPUI desktop/phone images.
    HTML captures inject the live rvbbitQuery bridge and wait for all queries to settle.
    data_timeout_ms optionally sets the HTML data wait (500–60000ms; default 60000ms,
    configurable by the host). wait_ms is a separate post-readiness paint delay.
    verification.status distinguishes ready, no_queries, data_pending, query_failed, and render_failed.
    The bounded readiness timeout still
    returns a visibly labeled diagnostic screenshot, with bridge.data_ready=false and a concrete timeout message for
    the agent. Results also report per-query bridge health (queries run/failed, console + page errors);
    Python captures auto-start the local runner by default. return_image=true additionally returns
    the PNG itself as image content for direct visual inspection (the saved path is on the MCP
    host, so remote agents should use return_image; keep the viewport modest — a full-page
    1440px capture can be megabytes)."""
    res = await asyncio.to_thread(
        lambda: _logged("capture_live_app", {
            "slug": slug,
            "path": path,
            "width": width,
            "height": height,
            "full_page": full_page,
            "start": start,
            "wait_ms": wait_ms,
            "return_image": return_image,
            "data_timeout_ms": data_timeout_ms,
        }, lambda: _artifact_editor_result(
            slug,
            lambda: tool_capture_live_app(
                slug, path, width, height, full_page, start, wait_ms, data_timeout_ms
            ),
        ))
    )
    if return_image and isinstance(res, dict) and not res.get("error") and res.get("path"):
        try:
            from mcp.server.fastmcp import Image
            return [res, Image(path=res["path"])]
        except Exception as e:  # noqa: BLE001 — the capture itself succeeded; degrade gracefully
            res["image_error"] = str(e)
    return res


