    # ── tool discovery: search the catalog instead of "tasting" tools ────────
    # This server exposes ~80 tools; agents burn calls (and context) probing
    # them one by one. search_tools ranks the catalog for a task description;
    # get_tool_help returns full descriptions + schemas for the shortlist.
    # Index is built lazily from the SAME registry agents see (the FastMCP
    # tool manager), so it can never drift from reality.
    catalog_notified_sessions = set()

    def _tool_index():
        out = []
        for t in mcp._tool_manager.list_tools():
            params = []
            try:
                params = list(((t.parameters or {}).get("properties") or {}).keys())
            except Exception:
                pass
            out.append({"name": t.name, "description": t.description or "", "params": params,
                        "parameters": t.parameters or {}})
        return out

    def tool_search_tools(query, limit=8):
        import re as _re
        limit = max(1, min(int(limit or 8), 25))
        index = [t for t in _tool_index() if t["name"] not in ("search_tools", "get_tool_help")]
        visible_names = _capability_visible_names(
            "cap_mcp_tool", [t["name"] for t in index]
        )
        index = [t for t in index if t["name"] in visible_names]
        words = [w for w in _re.split(r"[^a-z0-9]+", (query or "").lower()) if len(w) > 1]
        if not words:
            names = sorted(t["name"] for t in index)
            return {"tools": names, "count": len(names),
                    "hint": "pass a task description, e.g. search_tools('build a live dashboard')"}
        scored = []
        for t in index:
            name_toks = set(_re.split(r"[^a-z0-9]+", t["name"].lower()))
            desc = t["description"].lower()
            score = 0
            for w in words:
                if w in name_toks:
                    score += 5
                elif any(w in nt for nt in name_toks):
                    score += 3
                if w in desc:
                    score += 1
                if any(w in p.lower() for p in t["params"]):
                    score += 1
            if score > 0:
                scored.append((score, t))
        scored.sort(key=lambda x: (-x[0], x[1]["name"]))
        return {
            "matches": [{
                "name": t["name"],
                "score": sc,
                "description": t["description"].split("\n")[0][:180],
                "params": t["params"][:10],
            } for sc, t in scored[:limit]],
            "hint": "call get_tool_help(names=[...]) for full descriptions and argument schemas; "
                    "for reads, ONE run_sql (or run_sql_multi) usually beats several small tool calls",
        }

    def tool_get_tool_help(names):
        if isinstance(names, str):
            raw = names.strip()
            parsed = None
            if raw.startswith("["):
                try:
                    parsed = json.loads(raw)
                except ValueError:
                    parsed = None
            if isinstance(parsed, list):
                names = parsed
            else:
                # Accept the natural "a, b c" spellings the schema's `string` type invites.
                names = [part for part in re.split(r"[,\s]+", raw) if part]
        if not isinstance(names, list) or not names:
            return {"error": {"code": "BAD_NAMES", "message": "names must be a non-empty list of tool names"}}
        tools = list(mcp._tool_manager.list_tools())
        visible_names = _capability_visible_names(
            "cap_mcp_tool", [t.name for t in tools]
        )
        by_name = {t.name: t for t in tools if t.name in visible_names}
        out, missing = [], []
        for n in [str(x) for x in names][:16]:
            t = by_name.get(n)
            if not t:
                missing.append(n)
                continue
            out.append({"name": t.name, "description": t.description or "", "schema": t.parameters})
        res = {"tools": out}
        if missing:
            res["missing"] = missing
        return res

    async def mcp_search_tools(query, limit=8, ctx=None):
        """Find tools in the deferred catalog by what you are trying to do.

        Pass a task in plain words (e.g. 'build a live dashboard', 'retire a
        wrong caveat') and get back the best-matching tool names with one-line
        descriptions; then call get_tool_help(names=[...]) for full argument
        schemas. Pinned tools are already in your tool list and are marked as
        callable directly."""
        result = _logged(
            "search_tools",
            {"query": query, "limit": limit},
            lambda: tool_search_tools(query, limit),
        )
        await _notify_tool_list_changed_once(ctx, catalog_notified_sessions)
        return result

    async def mcp_get_tool_help(names, ctx=None):
        """Full description and argument schema for one or more tools by name.

        names: list of tool names (from search_tools or the catalog). Unknown
        names come back under `missing` instead of failing the call."""
        result = _logged(
            "get_tool_help", {"names": names}, lambda: tool_get_tool_help(names)
        )
        await _notify_tool_list_changed_once(ctx, catalog_notified_sessions)
        return result

