def _specialist_role_label(row):
    description = str(row.get("description") or "")
    if " — " in description:
        return description.split(" — ", 1)[0].strip()
    return str(row.get("specialist_key") or "").replace("-", " ").title()


def _specialist_roster_rows():
    """Active specialists from the database, curated order first; [] when the
    database is unavailable (callers fall back to the static text)."""
    try:
        with _conn() as conn:
            has_hints = conn.execute(
                "SELECT 1 FROM information_schema.columns "
                "WHERE table_schema='rvbbit' AND table_name='calliope_specialists' "
                "AND column_name='routing_hint'"
            ).fetchone()
            hint_col = ",routing_hint" if has_hints else ""
            rows = conn.execute(
                f"SELECT specialist_key,display_name,description{hint_col} "
                "FROM rvbbit.calliope_specialists WHERE status='active' "
                "ORDER BY display_name"
            ).fetchall()
    except Exception:  # noqa: BLE001 — tests / cold boots without a database
        return []
    rows = [dict(row) for row in rows]
    order = {key: index for index, key in enumerate(_SPECIALIST_ROSTER_ORDER)}
    rows.sort(key=lambda row: (order.get(str(row.get("specialist_key")), 99), str(row.get("display_name") or "")))
    return rows


def _specialist_roster_line(rows):
    parts = [
        f"{row.get('display_name')} is {_specialist_role_label(row)} with specialist_key {row.get('specialist_key')}"
        for row in rows
    ]
    return "The managed roster is known: " + "; ".join(parts) + "."


def _specialist_preference_text(rows):
    sentences = []
    for row in rows:
        key = str(row.get("specialist_key") or "")
        # A DB routing hint (factory-crafted, source-system-scoped) outranks
        # the static dictionary; the dictionary outranks the derived default.
        sentence = str(row.get("routing_hint") or "").strip() \
            or _SPECIALIST_PREFERENCE_SENTENCES.get(key)
        if not sentence:
            description = str(row.get("description") or "").strip()
            clause = description.split(" — ", 1)[1].strip() if " — " in description else description
            clause = clause.rstrip(".")
            sentence = (
                f"Prefer {row.get('display_name')}, the {_specialist_role_label(row)} "
                f"(specialist_key {key})"
                + (f": {clause[0].lower()}{clause[1:]}." if clause else ".")
            )
        sentences.append(sentence)
    return " ".join(sentences)


_SPECIALIST_ROSTER_STATIC = (
    "The managed roster is known: Iris is Dashboard Studio with specialist_key dashboard-studio; "
    "Hestia is Warehouse Steward with specialist_key warehouse-steward (the whole appliance: "
    "platform health, acceleration trials and layouts, external integrations); Athena is Semantic "
    "Architect with specialist_key semantic-architect; Argus is Signal Watch with specialist_key "
    "signal-watch; Demeter is Knowledge Gardener with specialist_key knowledge-gardener; Cassandra "
    "is Analytical Skeptic with specialist_key analytical-skeptic; Nemesis is Design Red Team with "
    "specialist_key design-red-team. Business-domain experts "
    "(full-stack analysis within one domain, accumulating domain memory) are hired by the domain "
    "agent factory from this business's own promoted topology and appear on the live roster with "
    "their own keys and routing preferences."
)
_SPECIALIST_PREFERENCES_STATIC = " ".join(
    _SPECIALIST_PREFERENCE_SENTENCES[key] for key in _SPECIALIST_ROSTER_ORDER
)


def _instructions_current():
    """_INSTRUCTIONS with the roster paragraph rebuilt from the live roster.
    Byte-identical to the static text while the standing crew is all active."""
    rows = _specialist_roster_rows()
    if not rows:
        return _INSTRUCTIONS
    return (
        _INSTRUCTIONS
        .replace(_SPECIALIST_ROSTER_STATIC, _specialist_roster_line(rows))
        .replace(_SPECIALIST_PREFERENCES_STATIC, _specialist_preference_text(rows))
    )


_DELEGATE_DOC_STATIC = str(_mcp_delegate_calliope_specialist.__doc__ or "")


def _delegate_doc_current():
    doc = _DELEGATE_DOC_STATIC
    rows = _specialist_roster_rows()
    if not rows:
        return doc
    generated = _specialist_preference_text(rows)
    # The docstring's own preference paragraph is replaced wholesale; the
    # invariant text around it (step zero, explicit-process override, review
    # independence, async contract) stays hand-written.
    marker_start = doc.find("Strongly prefer Iris")
    marker_end = doc.find("Delegate directly by known key")
    if marker_start == -1 or marker_end == -1 or marker_end <= marker_start:
        return doc
    return doc[:marker_start] + generated + " " + doc[marker_end:]


